window.CURRICULUM = [{"subject": "math", "edition": "人教版经典目录（2014 年第一版）·九年级数学", "editionNote": "按人教版九年级上册第21—25章、下册第26—29章组织，参照2014年第一版目录体系。本文为原创教学与练习资源，不是教材全文，也不声称对应最新修订版；使用前请核对学校现用教材的章号与顺序。", "sources": [{"title": "人民教育出版社：义务教育教科书 数学 九年级下册（2014年第一版目录依据）", "url": "https://www.pep.com.cn/products/jc/czjks/201602/t20160228_1258442.shtml"}, {"title": "人民教育出版社中小学教材电子版入口（供教师核对现用版本）", "url": "https://jc.pep.com.cn/"}], "chapters": [{"id": "math-21", "subject": "math", "chapter": "第二十一章", "title": "一元二次方程", "term": "上册", "category": "同步", "intro": "一块矩形花圃同时改变长和宽，面积条件为什么会得到一个二次方程？", "periods": "8—10课时（建议）", "goals": ["能将方程整理为一般形式并辨认各项系数", "能选择直接开平方法、配方法、公式法或因式分解法求解", "能利用判别式和实际条件解释根的个数与取舍"], "sections": [{"title": "21.1 一元二次方程与方程的根", "body": "先去分母、去括号、移项、合并同类项，再判断方程类型。只含一个未知数，未知数的最高次数是2，而且是整式方程，才是一元二次方程。一般形式写成ax²＋bx＋c＝0，其中a不能为0；b、c可以为0，读系数时必须连同符号。方程的根是使等号两边相等的未知数的值，代入检验是最直接的判断方法。含字母参数时，应先检查二次项系数是否为0，再讨论能否使用本章的解法。"}, {"title": "21.2 解法一：直接开平方与配方法", "body": "当方程可写成x²＝p或(x－m)²＝p时，先判断p的符号：p为正有两个实数根，p为0有一个二重根，p为负没有实数根。配方法把含一次项的式子改写成完全平方。先将二次项系数化为1，再把常数移到右边，两边同时加上一次项系数一半的平方。这个步骤保持等式成立，不能只在左边添加。得到平方形式后开平方，保留正负两种可能。可以用面积拼图说明配方，但代数推理不依赖图形尺寸必须为正。"}, {"title": "21.2 解法二：公式法与因式分解法", "body": "公式法来自对一般方程的配方，适用于二次项系数不为0的情况。先算判别式Δ＝b²－4ac，再决定是否求实数根；代入求根公式时用括号保护负系数，整个分子都除以2a。若方程易于分解，应先把一边整理成0，再利用两个因式的积为0推出至少一个因式为0。例如x(x－5)＝0得到0与5。不可在未讨论x＝0时直接除以x，那会丢根。选择解法的标准是结构是否清楚、计算是否简便。"}, {"title": "21.2 判别式与根、系数的关系", "body": "判别式把求根之前的判断变成一个数的符号问题：Δ大于0时有两个不相等的实数根，等于0时有两个相等的实数根，小于0时没有实数根。若两实数根为x₁、x₂，则它们的和为－b/a，积为c/a。这一关系可以检验计算，也能把根的对称式化成系数运算，例如先由和与积求两根平方和。使用时要注明方程确有实数根。不要把根的和误写为b/a，也不要把二重根误说成两个不同数值。"}, {"title": "21.3 实际问题与一元二次方程", "body": "建模依次经历选未知数、写范围、找相等关系、列方程、求解和回到情境检验。面积变化常出现两个一次式的乘积；连续两次按同一增长率变化通常得到原量乘以(1＋r)²；比赛与握手计数要判断是否重复计数。求出的代数根不一定都是实际答案，例如负长度、超过总人数的值都应舍去。增长率以小数代入，减少率则使用1－r。最后同时写数值、单位和依据，并检查结果是否符合题目描述的增减趋势。"}], "formulas": [{"text": "ax²＋bx＋c＝0；a≠0", "note": "一元二次方程的一般形式，a、b、c为实数。"}, {"text": "Δ＝b²－4ac；x＝(－b±√Δ)/(2a)", "note": "求实数根需Δ≥0；根号只作用于Δ。"}, {"text": "x₁＋x₂＝－b/a；x₁x₂＝c/a", "note": "x₁、x₂为方程的两个实数根，允许相等。"}, {"text": "连续两期同率增长：末量＝初量×(1＋r)²", "note": "每期均以上一期的量为基数；r用小数表示。"}], "examples": [{"question": "解方程2x²－5x－3＝0，并利用根与系数的关系检验。", "steps": ["计算Δ＝(－5)²－4×2×(－3)＝49。", "x＝(5±7)/4，得到x₁＝3、x₂＝－1/2。", "两根和为5/2＝－b/a，两根积为－3/2＝c/a，检验一致。"], "answer": "x＝3或x＝－1/2。"}, {"question": "一块矩形花圃长比宽多3 m，面积为40 m²。求花圃的长和宽。", "steps": ["设宽为x m，则长为(x＋3) m，且x＞0。", "根据面积列x(x＋3)＝40，整理得x²＋3x－40＝0。", "分解为(x＋8)(x－5)＝0，得x＝－8或x＝5。", "负长度不符合实际，取x＝5，再求长为8 m。"], "answer": "宽5 m，长8 m。"}], "activity": {"title": "用面积拼片看懂配方", "materials": "纸质代数拼片或方格纸、直尺、铅笔", "steps": ["画一个边长为x的正方形和4个宽为1、长为x的长方形，表示x²＋4x。", "将4个长方形均分放在正方形的两条相邻边外侧。", "观察缺角并补上边长为2的正方形，记录补入面积。", "写出x²＋4x＋4＝(x＋2)²，再将同样操作用于方程x²＋4x＝12。", "比较图中可表示的正长度解与代数得到的两个实数根。"], "recordHeaders": ["原表达式", "补入面积", "完全平方式", "方程的根"], "conclusion": "配方补入的是一次项系数一半的平方；x²＋4x＝12的代数根为2和－6，正长度模型只表示x＝2。", "safety": "可直接手绘拼片；如裁剪须规范使用剪刀。图形的正长度限制不能替代代数方程的完整求根。"}, "mistakes": ["把x²＝9只解为x＝3：还应有x＝－3，平方会隐藏符号。", "对x²＝5x直接除以x：先移项分解x(x－5)＝0，避免丢掉x＝0。", "实际问题求出两根就全部作答：必须检查长度、人数、增长率等情境范围。"], "quiz": [{"type": "choice", "question": "方程3x²＋4＝7x化成一般形式后，一次项系数是？", "options": ["7", "－7", "4", "－4"], "answer": 1, "explanation": "整理为3x²－7x＋4＝0，一次项系数连同符号为－7。"}, {"type": "choice", "question": "方程(x－2)²＝9的实数根是？", "options": ["只有5", "只有－1", "5和－1", "3和－3"], "answer": 2, "explanation": "x－2＝±3，所以x＝5或－1。"}, {"type": "choice", "question": "方程x²＋6x＋10＝0的实数根情况是？", "options": ["两个不相等的实数根", "两个相等的实数根", "没有实数根", "只有一个正根"], "answer": 2, "explanation": "Δ＝36－40＝－4＜0，所以没有实数根。"}, {"type": "choice", "question": "若x₁、x₂是x²－7x＋10＝0的根，则x₁＋x₂等于？", "options": ["－7", "7", "10", "－10"], "answer": 1, "explanation": "根的和为－b/a＝－(－7)/1＝7。"}, {"type": "short", "question": "用配方法解x²－6x＋5＝0，写出补入的数。", "answer": "补入9；(x－3)²＝4，所以x＝1或5。", "explanation": "移项得x²－6x＝－5；两边同时加9，得到完全平方，再取正负平方根。", "rubric": ["两边同时加9并写出(x－3)²＝4", "完整给出x＝1和x＝5两个根"]}, {"type": "short", "question": "一个阅读小组原有50人，连续两月以相同月增长率增加到72人。求月增长率。", "answer": "月增长率为20%。", "explanation": "设增长率r＞0，50(1＋r)²＝72，所以1＋r＝1.2，r＝0.2。另一代数解r＝－2.2不符合增长情境。", "rubric": ["列出以逐月人数为基数的方程50(1＋r)²＝72", "求得并保留符合增长条件的20%"]}], "sim": "quadratic", "tags": ["一元二次方程", "配方法", "求根公式", "判别式", "增长率"]}, {"id": "math-22", "subject": "math", "chapter": "第二十二章", "title": "二次函数", "term": "上册", "category": "同步", "intro": "相同周长的矩形，长宽怎样分配面积最大？抛物线如何给出答案？", "periods": "9—11课时（建议）", "goals": ["能从一般式、顶点式和交点式读取图象信息", "能结合对称轴判断函数增减及有范围限制的最值", "能将图象与方程、面积或运动模型联系起来"], "sections": [{"title": "22.1 二次函数的图象与性质", "body": "二次函数的一般式为y＝ax²＋bx＋c，a不为0，图象是抛物线。先研究y＝ax²：a的符号决定开口方向，绝对值影响图象离开顶点后上升或下降的快慢。再用左右、上下平移得到顶点式y＝a(x－h)²＋k，顶点是(h，k)，对称轴是x＝h。描点时围绕对称轴成对选点，并标出顶点和坐标轴交点。图象上的点必须同时满足横、纵坐标的对应关系，曲线形状不能只凭视觉猜测。"}, {"title": "22.1 三种表达式与待定系数法", "body": "不同信息适合不同表达式：已知顶点，优先用顶点式；已知两个横轴交点，优先用交点式y＝a(x－x₁)(x－x₂)；一般的三个点可代入一般式建立方程组。每选一种形式，都应确认未知系数还有几个，再使用足够且相互独立的条件求出它们。一般式可以通过配方变为顶点式，对称轴为x＝－b/(2a)。求完表达式后，把题目给出的点逐一代回检验；点在同一竖线上却有不同纵坐标时，不可能属于同一个函数。"}, {"title": "22.2 二次函数与一元二次方程", "body": "把函数值设为0，就得到ax²＋bx＋c＝0。方程的实数根正是抛物线与x轴交点的横坐标，因此两个交点、一个相切点和没有交点分别对应判别式为正、零、负。若要解f(x)＝m，可观察抛物线与水平直线y＝m的交点，而不应仍只盯住x轴。图象也能帮助估计何时函数值大于或小于某个量，但近似读图不能代替要求精确值时的代数计算。交点的纵坐标与方程的根是不同概念。"}, {"title": "22.3 增减性、最值与实际问题", "body": "二次函数的增减由开口方向和对称轴共同决定，不能脱离区间只说它一直增加。开口向上时，顶点左侧递减、右侧递增；开口向下时情况相反。实际问题必须先写自变量范围，再判断顶点横坐标是否落在范围内：若在区间内，顶点可能给出最值；若不在，则需比较允许的端点。面积、抛物运动高度和利润都能形成二次模型，但单位和模型成立的范围必须随表达式写清。现实测量得到的参数通常有误差。"}], "formulas": [{"text": "y＝a(x－h)²＋k；a≠0", "note": "顶点(h，k)，对称轴x＝h；a＞0开口向上，a＜0开口向下。"}, {"text": "h＝－b/(2a)；k＝(4ac－b²)/(4a)", "note": "适用于一般式y＝ax²＋bx＋c。"}, {"text": "y＝a(x－x₁)(x－x₂)", "note": "x₁、x₂为与x轴交点的横坐标，允许相等。"}, {"text": "区间最值：比较区间内顶点与允许的端点", "note": "有实际范围时，不能直接把抛物线顶点当作可实现答案。"}], "examples": [{"question": "已知抛物线顶点为(2，－3)，且经过(0，5)，求表达式及横轴交点。", "steps": ["设y＝a(x－2)²－3，代入(0，5)得5＝4a－3，所以a＝2。", "函数为y＝2(x－2)²－3。令y＝0，得到(x－2)²＝3/2。", "x＝2±√6/2；交点的纵坐标均为0。"], "answer": "y＝2(x－2)²－3；交点为(2－√6/2，0)与(2＋√6/2，0)。"}, {"question": "用24 m篱笆围成矩形，不借助墙体。设一边为x m，怎样使面积最大？", "steps": ["另一边为12－x，长度条件为0＜x＜12。", "面积S＝x(12－x)＝－(x－6)²＋36。", "顶点横坐标6在允许范围内，故x＝6时面积最大。"], "answer": "围成边长6 m的正方形，最大面积36 m²。"}], "activity": {"title": "从一条抛物线到参数家族", "materials": "方格纸或本章函数交互图、直尺、计算器", "steps": ["固定h＝0、k＝0，分别取a＝1、2、－1，比较开口和相同横坐标下的纵坐标。", "固定a＝1、k＝0，把h由0调到3，记录顶点的移动方向。", "固定a＝1、h＝3，把k改为－2，在纸上标注顶点与对称轴。", "选择距对称轴同为2的两个横坐标，计算并比较函数值。", "对所得函数设一个有限区间，检查顶点是否属于区间再判断最值。"], "recordHeaders": ["a、h、k", "顶点", "开口方向", "等距点函数值", "区间最值"], "conclusion": "a决定开口，h、k决定顶点位置；关于对称轴的等距点函数值相等，有范围限制时要额外检查顶点。", "safety": "屏幕曲线与滑块读数用于探索，精确值仍应通过代入或配方求出。"}, "mistakes": ["把y＝(x－3)²看成向左平移3：其顶点横坐标为3，应向右平移3。", "只看a的正负就判断整个函数递增：必须结合对称轴并指定自变量区间。", "求实际最大值忽略范围：顶点不在允许范围内时，要比较边界或分析区间单调性。"], "quiz": [{"type": "choice", "question": "y＝－2(x＋1)²＋4的顶点是？", "options": ["(1，4)", "(－1，4)", "(－1，－4)", "(2，4)"], "answer": 1, "explanation": "x＋1＝x－(－1)，所以h＝－1、k＝4。"}, {"type": "choice", "question": "对y＝x²－4x＋1，当x从0增加到1时，y怎样变化？", "options": ["增加", "减少", "保持不变", "先减后增"], "answer": 1, "explanation": "对称轴x＝2，开口向上；区间[0，1]位于对称轴左侧，函数递减。"}, {"type": "choice", "question": "函数y＝x²＋2x＋3与x轴有几个交点？", "options": ["0个", "1个", "2个", "3个"], "answer": 0, "explanation": "Δ＝4－12＝－8＜0，或配方为(x＋1)²＋2始终大于0。"}, {"type": "choice", "question": "在0≤x≤2范围内，y＝－(x－3)²＋5的最大值是？", "options": ["5", "4", "0", "－4"], "answer": 1, "explanation": "顶点x＝3不在区间内；该区间函数递增，在x＝2时取得最大值4。"}, {"type": "short", "question": "把y＝x²－6x＋8化为顶点式，并求与x轴的交点。", "answer": "y＝(x－3)²－1；交点为(2，0)、(4，0)。", "explanation": "配方得到顶点式；令y＝0，(x－3)²＝1，所以x＝2或4。", "rubric": ["正确配方为(x－3)²－1", "交点同时写出正确横坐标与纵坐标0"]}, {"type": "short", "question": "一条抛物线与x轴交于(1，0)、(5，0)，且经过(0，5)。求函数表达式和最小值。", "answer": "y＝(x－1)(x－5)＝(x－3)²－4，最小值为－4。", "explanation": "设y＝a(x－1)(x－5)，代入(0，5)得a＝1；顶点为(3，－4)，开口向上。", "rubric": ["利用三个已知点得到a＝1的表达式", "配方或对称轴分析得最小值－4"]}], "sim": "quadratic", "tags": ["二次函数", "抛物线", "待定系数", "最值", "函数与方程"]}, {"id": "math-23", "subject": "math", "chapter": "第二十三章", "title": "旋转", "term": "上册", "category": "同步", "intro": "图形绕一点转动后，哪些量改变，哪些关系始终保持？", "periods": "5—6课时（建议）", "goals": ["能说明旋转中心、角度和方向三个要素", "能作简单图形旋转后的图形并证明对应关系", "能辨认中心对称并写出关于原点对称的点的坐标"], "sections": [{"title": "23.1 图形的旋转与作图", "body": "旋转把平面内每个点绕同一个定点按同一方向转过相同角度，这个定点是旋转中心。对应点到中心的距离相等，两条对应射线夹成规定的旋转角，因此长度、角度和图形大小都保持不变。作图时先连接中心与关键顶点，再按指定方向作角，在新射线上截取相等距离，最后按原连接顺序连线。中心本身保持不动。观察图案时要同时确认中心、角度和方向，仅凭两个图形全等，不能保证它们之间一定是旋转关系。"}, {"title": "23.2 中心对称与中心对称图形", "body": "旋转180°时，对应点与中心在同一直线上，且位于中心两侧，中心正好是对应点连线的中点。两个图形经这一旋转能重合，称为它们关于该点中心对称；一个图形旋转180°后与自身重合，称它是中心对称图形。两种说法分别描述图形之间的关系和单个图形的性质。平行四边形以两对角线交点为对称中心，普通三角形则没有对称中心。作中心对称图形时，可以逐个延长顶点与中心的连线并截取等长线段。"}, {"title": "23.2 关于原点对称的点与坐标表达", "body": "在平面直角坐标系中，点P(x，y)关于原点中心对称后得到P′(－x，－y)，横、纵坐标同时变号。这与关于x轴对称只改变纵坐标、关于y轴对称只改变横坐标不同。用中点公式也能理解：P、P′连线中点的两个坐标都是0。做坐标题先识别变换类型，再处理各顶点，不能只移动其中一个点。还可用长度或象限位置检查答案，例如第一象限的点经过关于原点的中心对称后应位于第三象限。"}, {"title": "23.3 用旋转设计图案", "body": "从一个简单基本图形出发，固定旋转中心，按等角重复旋转，可以制作风车、花瓣或镶嵌图案。如果希望n次等角旋转后恰好转一周，每次角度应为360°/n，但旋转后的图形仍可能重叠，需结合基本图形的形状检查。设计不只是画得相似，还应标注一个对应点、旋转角和中心，用几何语言证明生成规则。可比较同一基本图形在不同中心下的结果，体会图案的变化来自参数变化，而对应边长与角度始终保持。"}], "formulas": [{"text": "OP＝OP′；∠POP′对应规定的旋转角", "note": "O为旋转中心，P与P′为对应点；作图需注明方向。"}, {"text": "P(x，y) → P′(－x，－y)", "note": "关于原点的中心对称，即绕原点旋转180°。"}, {"text": "n次等角转满一周：θ＝360°/n", "note": "n为正整数；图案是否重叠仍需观察。"}], "examples": [{"question": "点A(3，1)绕原点逆时针旋转90°，求像点A′并核对距离。", "steps": ["逆时针旋转90°时，向右的分量转为向上，向上的分量转为向左。", "A′的坐标为(－1，3)。", "OA²＝3²＋1²＝10，OA′²＝(－1)²＋3²＝10，长度保持不变。"], "answer": "A′(－1，3)，OA＝OA′＝√10。"}, {"question": "三角形ABC的顶点为A(1，2)、B(4，1)、C(2，－1)，求关于原点中心对称后的顶点。", "steps": ["关于原点中心对称时，每个点的两个坐标同时变号。", "得到A′(－1，－2)、B′(－4，－1)、C′(－2，1)。", "逐对取中点均得到(0，0)，说明原点是各对应点连线的中点。"], "answer": "A′(－1，－2)、B′(－4，－1)、C′(－2，1)。"}], "activity": {"title": "纸上旋转与对称中心的定位", "materials": "透明描图纸、方格纸、量角器、直尺", "steps": ["在方格纸上画不等边三角形，选择图形外一点O作为中心。", "用透明纸描下三角形并标出O，绕O逆时针转60°后描出像。", "测量一对对应点到O的距离和它们组成的旋转角。", "改为旋转180°，连接三对对应点，检查各连线是否通过O。", "隐去O，只保留原图和180°后的图，通过两对对应点连线的中点找回中心。"], "recordHeaders": ["对应点", "原点距O", "像点距O", "旋转角", "中点位置"], "conclusion": "任意旋转保持到中心的距离；180°旋转还使O成为所有对应点连线的中点。", "safety": "不必使用图钉固定纸张，用手指轻压中心即可；测量结果允许合理作图误差。"}, "mistakes": ["只说旋转90°却不注明方向：顺时针与逆时针通常产生不同像。", "把轴对称与中心对称混淆：前者对应点连线垂直对称轴，后者中心是连线中点。", "认为等边三角形一定中心对称：它有120°旋转对称，但旋转180°不能与自身重合。"], "quiz": [{"type": "choice", "question": "P(－2，5)关于原点中心对称的点是？", "options": ["(2，5)", "(－2，－5)", "(2，－5)", "(5，－2)"], "answer": 2, "explanation": "关于原点中心对称时两个坐标同时变号。"}, {"type": "choice", "question": "以下哪个图形一定是中心对称图形？", "options": ["任意三角形", "任意平行四边形", "任意等腰梯形", "任意扇形"], "answer": 1, "explanation": "平行四边形旋转180°能与自身重合，其中心是两对角线交点。"}, {"type": "choice", "question": "一个点绕O旋转后，下面哪一个量一定不变？", "options": ["横坐标", "纵坐标", "到O的距离", "与x轴正方向的夹角"], "answer": 2, "explanation": "旋转保持对应点到旋转中心的距离，但坐标和方向通常改变。"}, {"type": "choice", "question": "绕同一中心连续逆时针旋转60°两次，等效于？", "options": ["顺时针旋转120°", "逆时针旋转120°", "中心对称", "平移120个单位"], "answer": 1, "explanation": "同中心、同方向的旋转角相加：60°＋60°＝120°。"}, {"type": "short", "question": "点A(1，－2)与A′(5，4)关于某点O中心对称，求O。", "answer": "O(3，1)。", "explanation": "中心对称的中心是对应点连线中点：((1＋5)/2，(－2＋4)/2)＝(3，1)。", "rubric": ["说明O是AA′的中点", "两个坐标均计算正确"]}, {"type": "short", "question": "为制作五瓣等角花形，同一花瓣绕固定中心依次转动，每次至少转多少度可均匀分成五个方向？如果改为六瓣呢？", "answer": "五瓣每次72°；六瓣每次60°。", "explanation": "一周为360°，分别除以5和6。是否重叠要根据花瓣宽度另外检查。", "rubric": ["用360°平均分配旋转方向", "给出72°与60°，并认识形状重叠需另行检查"]}], "sim": "rotation", "tags": ["旋转", "中心对称", "坐标变换", "图案设计"]}, {"id": "math-24", "subject": "math", "chapter": "第二十四章", "title": "圆", "term": "上册", "category": "同步", "intro": "为什么同一段圆弧在不同位置看到的圆周角相等，而圆心角恰好是它的两倍？", "periods": "12—15课时（建议）", "goals": ["能使用垂径定理和圆周角定理建立角与弦的关系", "能判断点、直线与圆的位置关系并说明切线理由", "能计算弧长、扇形面积和圆锥侧面积"], "sections": [{"title": "24.1 圆的基本性质与垂径定理", "body": "圆是到固定点距离等于固定长度的点的集合，固定点是圆心，固定长度是半径。连接圆上两点的线段叫弦，经过圆心的弦是直径。垂直于弦的直径会平分这条弦，并平分这条弦所对的两条弧；反过来，平分非直径弦的直径垂直于该弦。遇到弦长与圆心到弦的距离问题，应连接半径构造直角三角形，用半弦长、弦心距和半径组成勾股关系。注意“非直径”的限定，因为一条直径的中点都是圆心。"}, {"title": "24.1 弧、弦、圆心角与圆周角", "body": "在同圆或等圆中，相等的圆心角对应相等的弧和弦，反过来也成立。圆周角的顶点在圆上，两边分别与圆相交；同弧所对的圆周角等于圆心角的一半。由此可知同弧或等弧所对的圆周角相等，直径所对的圆周角是90°，90°圆周角所对的弦是直径。使用时先辨认截取的是哪一段弧，不能把同一弦两侧的圆周角都直接当成相等。圆内接四边形的对角互补，也可由两段弧角度合成一周来解释。"}, {"title": "24.2 点与圆的位置关系、确定圆", "body": "判断点与圆的位置关系，只需比较点到圆心的距离d与半径r：d小于r在圆内，等于r在圆上，大于r在圆外。经过三个不在同一直线上的点可以确定唯一的圆，因为两条弦的垂直平分线交于同一点，此点到三个顶点的距离相等，是三角形的外心。三个点共线时不能确定这样的圆。外心不一定在三角形内部：锐角三角形在内，直角三角形在斜边中点，钝角三角形在外。作图需保留垂直平分线的依据。"}, {"title": "24.2 直线与圆的位置关系和切线", "body": "圆心到直线的垂直距离d小于、等于或大于r，分别对应相交、相切和相离。证明一条直线是切线，常先连接圆心与直线上一个已知圆上点，再证明半径与直线垂直；已知切线时也应补出过切点的半径。由圆外一点引圆的两条切线，两条切线段长度相等，这是求周长和证明线段关系的常用工具。切线与一般割线的区别在于公共点个数，不应依据图上看起来“刚好贴住”来判断，必须给出距离或垂直关系。"}, {"title": "24.3 正多边形和圆", "body": "各边相等、各内角相等的多边形是正多边形。把一个圆n等分后，顺次连接分点可得圆内接正n边形，相邻顶点对应的圆心角是360°/n。从圆心连向相邻顶点，再向一条边作垂线，能得到两个全等直角三角形，联系外接圆半径、边心距和半边长。正六边形边长等于外接圆半径；正方形的对角线等于外接圆直径。求面积可把正多边形分成n个同底高的等腰三角形，而不是直接套用圆面积作为多边形面积。"}, {"title": "24.4 弧长、扇形面积与圆锥展开", "body": "弧长与圆心角占一周的比例相同，扇形面积与圆心角占一周的比例也相同，因此可由整圆周长和面积推导公式。计算前统一长度单位，并确认角度使用的是度数。圆锥的侧面展开是扇形，其半径为母线长，弧长等于底面圆周长，所以侧面积为πrl。圆锥的高、底面半径与母线构成直角三角形，母线不是竖直高。求全面积还要加底面面积；求只有侧面的包装纸面积则只用侧面积，并按题目需要考虑接缝余量。"}], "formulas": [{"text": "半弦长²＋弦心距²＝半径²", "note": "从圆心向弦作垂线，垂足平分弦。"}, {"text": "同弧圆周角＝对应圆心角/2", "note": "要明确两角截取同一段弧；直径对应的圆周角为90°。"}, {"text": "d＜r相交；d＝r相切；d＞r相离", "note": "此处d为圆心到直线的垂直距离。"}, {"text": "弧长s＝nπr/180；扇形面积S＝nπr²/360＝sr/2", "note": "n为圆心角的度数数值，r为半径。"}, {"text": "圆锥S侧＝πrl；S全＝πrl＋πr²；l²＝r²＋h²", "note": "r为底面半径，l为母线，h为高；直圆锥。"}], "examples": [{"question": "半径为5 cm的圆中，一条弦到圆心的距离为3 cm，求弦长。", "steps": ["从圆心O向弦AB作垂线，垂足为M。", "由垂径定理，AM＝MB。连接OA，在直角三角形OMA中，AM²＝5²－3²＝16。", "AM＝4 cm，AB＝2AM＝8 cm。"], "answer": "弦长为8 cm。"}, {"question": "一个直圆锥底面半径3 cm，高4 cm。求母线、侧面积及侧面展开扇形的圆心角。", "steps": ["母线l＝√(3²＋4²)＝5 cm。", "侧面积S＝πrl＝15π cm²。", "展开扇形半径为5 cm，弧长等于底面周长6π cm。", "设圆心角n°，nπ×5/180＝6π，解得n＝216。"], "answer": "母线5 cm，侧面积15π cm²，展开扇形圆心角216°。"}], "activity": {"title": "同弧圆周角的动态测量", "materials": "圆形纸片、量角器、直尺或本章交互圆图", "steps": ["固定圆上两点A、B，选定一条小弧AB并标注。", "在另一条大弧上取P、Q、R三个不同位置，分别连接它们与A、B。", "测量∠APB、∠AQB、∠ARB并记录。", "连接OA、OB，测量截取所选小弧AB的圆心角，与三个圆周角比较。", "将一个观察点移到小弧AB上，讨论为什么它截取的弧改变，原等角结论不能直接照搬。"], "recordHeaders": ["观察点", "截取的弧", "圆周角", "圆心角", "比值"], "conclusion": "截取同一段弧的圆周角相等，且等于相应圆心角的一半；跨到弦的另一侧后应重新辨认截弧。", "safety": "手绘或屏幕测量只形成猜想，教学时仍需补充定理推理；使用圆规注意尖端。"}, "mistakes": ["把任何平分弦的直径都判为垂直于弦：逆用定理时要排除被平分的弦本身是直径。", "同一弦两侧的圆周角都当成相等：它们通常互补，只有直径时都为90°。", "计算圆锥侧面积用竖直高代替母线：应先由l²＝r²＋h²求母线。"], "quiz": [{"type": "choice", "question": "圆的半径为6 cm，圆心到某直线的距离也为6 cm，直线与圆的关系是？", "options": ["相交", "相切", "相离", "无法判断"], "answer": 1, "explanation": "圆心到直线的垂直距离等于半径，直线与圆相切。"}, {"type": "choice", "question": "一条小弧所对的圆心角为100°，截取同一小弧的圆周角为？", "options": ["25°", "50°", "100°", "200°"], "answer": 1, "explanation": "同弧圆周角是对应圆心角的一半，即100°/2＝50°。"}, {"type": "choice", "question": "半径为3 cm、圆心角为120°的扇形面积是？", "options": ["π cm²", "2π cm²", "3π cm²", "6π cm²"], "answer": 2, "explanation": "S＝120×π×3²/360＝3π cm²。"}, {"type": "choice", "question": "圆内接正六边形的外接圆半径为4 cm，它的边长是？", "options": ["2 cm", "4 cm", "4√2 cm", "8 cm"], "answer": 1, "explanation": "每个中心三角形的圆心角为60°，是等边三角形，所以边长等于半径。"}, {"type": "short", "question": "圆外一点P引两条切线PA、PB，A、B为切点。若PA＝7 cm，OA＝4 cm，求PB和OP。", "answer": "PB＝7 cm；OP＝√65 cm。", "explanation": "同一外点引出的切线段相等；半径OA垂直切线PA，故OP²＝7²＋4²＝65。", "rubric": ["根据切线长定理求PB＝7 cm", "说明OA⊥PA并用勾股定理求OP"]}, {"type": "short", "question": "一个直圆锥底面半径2 cm、母线5 cm，求侧面积和包括底面的全面积。", "answer": "侧面积10π cm²；全面积14π cm²。", "explanation": "S侧＝πrl＝10π；底面积为πr²＝4π，二者相加为14π。", "rubric": ["侧面积正确使用母线得到10π cm²", "加上底面面积得到14π cm²"]}], "sim": "circle", "tags": ["圆", "垂径定理", "圆周角", "切线", "圆锥"]}, {"id": "math-25", "subject": "math", "chapter": "第二十五章", "title": "概率初步", "term": "上册", "category": "同步", "intro": "试验结果无法预先确定时，我们怎样用一个数描述某个事件发生的可能性？", "periods": "6—7课时（建议）", "goals": ["能区分必然、不可能与随机事件", "能在等可能条件下列举结果并计算概率", "能解释大量重复试验中频率与概率的关系"], "sections": [{"title": "25.1 随机事件与概率", "body": "在条件不变的试验中，必然发生的是必然事件，绝不发生的是不可能事件，可能发生也可能不发生的是随机事件。概率是对事件发生可能性大小的数量描述，取值在0与1之间；必然事件为1，不可能事件为0。判断事件类型要说明试验条件，例如一个袋子是否含目标颜色球。若所有基本结果有限且等可能，就可以用有利结果数除以全部结果数。看起来“只有几种情况”并不表示这些情况同样可能，必须先检查等可能性。"}, {"title": "25.2 用列举法计算概率", "body": "列举法的关键是完整、不重复地写出每个等可能基本结果，再圈出满足条件的结果。一步试验可直接列举，两步试验常用列表，多步或分支结构适合树状图。要分清“有放回”与“无放回”：前者下一次可选对象数量不变，后者会减少，还要记录已经抽出的对象。两枚骰子的和虽然只有2到12这11个值，它们的出现机会并不相同；应列举有序点数组合这36个等可能结果。必要时给相同颜色的球编号，避免合并不同基本结果。"}, {"title": "25.3 用频率估计概率", "body": "当不能方便列举全部结果时，可以在相同条件下重复试验，计算事件发生次数与总次数之比，这个比值是频率。随着试验次数增多，频率通常在某个数附近波动，长期稳定的水平可以用来估计概率。这里不是保证次数每增加一次就更接近，也不是达到某个次数后频率就不再变化。比较实验必须保持器材、规则与记录标准一致。单次试验结果无法由概率准确预报，小概率事件也可能发生；用模拟软件时同样应检查模型是否符合真实试验。"}], "formulas": [{"text": "P(A)＝m/n", "note": "n个基本结果有限且等可能，m个结果使事件A发生。"}, {"text": "频率＝事件发生次数/总试验次数", "note": "试验条件相同；有限次数的频率通常不等于理论概率。"}, {"text": "0≤P(A)≤1；P(不发生A)＝1－P(A)", "note": "“不发生A”包含试验结果中A之外的全部情况。"}], "examples": [{"question": "同时掷两枚均匀六面骰子，点数之和为8的概率是多少？", "steps": ["区分第一枚与第二枚骰子，全部有序组合共有6×6＝36个，等可能。", "和为8的组合为(2，6)、(3，5)、(4，4)、(5，3)、(6，2)，共有5个。", "用有利结果数除以全部结果数。"], "answer": "概率为5/36。"}, {"question": "袋中有两个红球R₁、R₂和一个蓝球B，除颜色外完全相同。不放回连续摸两个球，都是红球的概率是多少？", "steps": ["用编号区分球，等可能有序结果为R₁R₂、R₁B、R₂R₁、R₂B、BR₁、BR₂，共6个。", "两个均红的有R₁R₂与R₂R₁，共2个。", "概率为2/6＝1/3。"], "answer": "概率为1/3。"}], "activity": {"title": "频率会不会每次都更接近概率", "materials": "均匀硬币、记录表或抛硬币模拟器", "steps": ["约定正面朝上为事件A，先写出均匀硬币的理论概率1/2。", "分组进行100次试验，每20次记录累计正面次数与累计频率。", "把各小组数据合并，计算班级总体频率，注意使用总次数作分母。", "把累计频率画成折线，与水平线0.5比较。", "寻找某一步比前一步偏离0.5更远的情况，解释为什么这不推翻概率模型。"], "recordHeaders": ["累计次数", "正面次数", "累计频率", "距0.5的差"], "conclusion": "频率会波动，更多试验能提供较稳定估计，但不保证逐步单调接近理论概率。", "safety": "使用普通教具硬币，避免高抛和投向他人；模拟器假定各次独立且硬币均匀。"}, "mistakes": ["骰子和为2到12共11种，所以每种概率都是1/11：这些和值并不等可能。", "已经连续出现多次正面，下一次反面一定更可能：独立均匀抛掷中下一次仍各为1/2。", "无放回摸球后仍用原来的球数作为第二步分母：必须按照新的可选对象列举。"], "quiz": [{"type": "choice", "question": "掷一枚均匀六面骰子，出现点数7属于？", "options": ["必然事件", "不可能事件", "概率为1/6的事件", "概率为1/7的事件"], "answer": 1, "explanation": "骰子只有1到6点，不含7点，所以不可能发生。"}, {"type": "choice", "question": "袋中3个红球、2个蓝球除颜色外相同，随机摸一球是蓝球的概率为？", "options": ["1/2", "2/3", "2/5", "3/5"], "answer": 2, "explanation": "5个球等可能被摸到，2个蓝球对应有利结果。"}, {"type": "choice", "question": "均匀硬币连续抛3次，恰有2次正面朝上的概率为？", "options": ["1/8", "3/8", "1/2", "3/4"], "answer": 1, "explanation": "共有8个等可能序列，正正反、正反正、反正正3个符合条件。"}, {"type": "choice", "question": "某事件在400次相同条件试验中发生236次，其频率为？", "options": ["0.41", "0.50", "0.59", "0.64"], "answer": 2, "explanation": "频率＝236/400＝0.59，这是此次数据的频率而非必然精确的概率。"}, {"type": "short", "question": "写有1、2、3的三张卡片，随机先抽一张不放回，再抽一张。求两数之和为奇数的概率。", "answer": "概率为2/3。", "explanation": "有序结果12、13、21、23、31、32共6个；和为奇数的为12、21、23、32共4个，所以4/6＝2/3。", "rubric": ["列举6个不重复且完整的等可能结果", "找出4个有利结果并算得2/3"]}, {"type": "short", "question": "某组抛均匀硬币100次得到58次正面。能否断言下一次一定出现反面来使频率接近1/2？说明理由。", "answer": "不能；下一次正、反面概率仍各为1/2。", "explanation": "各次独立抛掷不受前面结果补偿，频率是有限数据的统计结果，理论概率不保证每一步都靠近。", "rubric": ["否定下一次必定反面的说法", "用独立性或频率波动解释，指出下一次反面概率1/2"]}], "sim": "probability", "tags": ["随机事件", "列表", "树状图", "频率", "概率"]}, {"id": "math-26", "subject": "math", "chapter": "第二十六章", "title": "反比例函数", "term": "下册", "category": "同步", "intro": "路程相同，速度加倍时所用时间为什么减半？图象为什么不能碰到坐标轴？", "periods": "5—6课时（建议）", "goals": ["能识别反比例关系并求比例系数", "能根据k的符号分析图象所在象限与各分支增减", "能结合正值范围解释路程、面积和压强等模型"], "sections": [{"title": "26.1 反比例函数的意义与表达式", "body": "当两个变量的乘积恒为非零常数时，可以把其中一个写成另一个的反比例函数：y＝k/x，其中k不为0，x不能等于0。判断时既要检查乘积是否恒定，也要注意常数是否非零；例如y＝3/x＋1不是反比例函数，因为xy并非常数。已知图象上一点，直接用k＝xy求系数，再写出完整表达式。问题中若x代表时间、速度或边长，还要在代数定义域之外补上正值等实际限制，不能机械保留所有非零实数。"}, {"title": "26.1 双曲线的图象和性质", "body": "反比例函数图象由两条分支组成，k大于0时在第一、三象限，k小于0时在第二、四象限。x越接近0，函数值的绝对值越大；x的绝对值越大，函数值越接近0，但图象永不与坐标轴相交。讨论增减必须限定同一分支：k大于0时每个分支都随x增大而减小，k小于0时每个分支都随x增大而增大。不能跨越x＝0直接应用这一说法。描点时选取便于整除的横坐标，并把正负两组点分别平滑连线。"}, {"title": "26.2 反比例函数的应用与综合", "body": "建模要先找恒定的乘积。例如固定路程s中速度v与时间t满足vt＝s；固定矩形面积S中长宽乘积为S；固定压力F作用下压强p与受力面积A满足pA＝F。写表达式前统一单位，代入后再检查范围。图象上一点向两坐标轴作垂线围成的矩形面积为|k|，若连接原点形成相应直角三角形，其面积为|k|/2。与一次函数联立时，可借交点解释共同满足的条件，但把两边同乘x前必须保留x≠0的前提。"}], "formulas": [{"text": "y＝k/x；xy＝k；k≠0，x≠0", "note": "图象为两支双曲线；实际问题可能只取其中一支。"}, {"text": "k＝x₀y₀", "note": "(x₀，y₀)为图象上的已知点。"}, {"text": "矩形面积＝|k|；对应直角三角形面积＝|k|/2", "note": "顶点由图象上一点及其在两坐标轴上的垂足、原点组成。"}], "examples": [{"question": "反比例函数经过(－3，4)，求表达式，并求x＝6时的函数值。", "steps": ["k＝(－3)×4＝－12，因此y＝－12/x，x≠0。", "k＜0，图象位于第二、四象限。", "把x＝6代入，y＝－12/6＝－2。"], "answer": "y＝－12/x；x＝6时y＝－2。"}, {"question": "一段路程长180 km。若匀速行驶，速度v限定为45—90 km/h，写出时间t与v的关系及t的范围。", "steps": ["路程＝速度×时间，所以t＝180/v。", "实际范围45≤v≤90，均为正值。", "在该正数分支上t随v增大而减小；v＝45时t＝4，v＝90时t＝2。"], "answer": "t＝180/v，45≤v≤90；2≤t≤4，时间单位h。"}], "activity": {"title": "同面积矩形与双曲线", "materials": "方格纸、直尺或反比例交互图", "steps": ["规定矩形面积为24个平方单位，依次选择宽x＝1、2、3、4、6、8。", "计算对应的长y并核对xy是否总为24。", "以x为横坐标、y为纵坐标描点，画出正值分支。", "把宽加倍，比较长如何变化，再讨论宽趋近于0时能否得到有限长度。", "把几何模型延伸为代数函数时，在第三象限补点，并解释负值分支不表示实际边长。"], "recordHeaders": ["宽x", "长y", "xy", "宽变化倍数", "长变化倍数"], "conclusion": "固定面积产生y＝24/x，宽扩大几倍，长缩小为原来的几分之一；实际边长只取正值。", "safety": "纸面矩形是理想模型，不用把非常小的宽和非常大的长实际制作出来。"}, "mistakes": ["认为y＝k/x可以取x＝0：分母不能为0，图象也不经过坐标轴。", "说k＞0时整个定义域都递减：应分别在x＜0和x＞0两个分支内讨论。", "把图象与坐标轴围成的矩形面积写成k：面积非负，应为|k|。"], "quiz": [{"type": "choice", "question": "下列哪个是反比例函数？", "options": ["y＝2x", "y＝2/x", "y＝2/x＋1", "y＝x²"], "answer": 1, "explanation": "只有y＝2/x具有k/x的形式，且k＝2不为0。"}, {"type": "choice", "question": "y＝－8/x经过下列哪个点？", "options": ["(2，4)", "(－2，－4)", "(2，－4)", "(0，－8)"], "answer": 2, "explanation": "点(2，－4)满足xy＝－8；x＝0无定义。"}, {"type": "choice", "question": "y＝6/x在x＞0范围内，x从2增加到3，y如何变化？", "options": ["从3减为2", "从2增为3", "从6减为3", "保持3不变"], "answer": 0, "explanation": "分别代入得y(2)＝3、y(3)＝2，正值分支递减。"}, {"type": "choice", "question": "点P在y＝－10/x上，P与其两坐标轴垂足、原点围成矩形，面积是？", "options": ["－10", "5", "10", "20"], "answer": 2, "explanation": "矩形面积为|xy|＝|k|＝10。"}, {"type": "short", "question": "反比例函数与直线y＝2x交于第一象限点(2，4)。求该反比例函数和另一交点。", "answer": "y＝8/x；另一交点为(－2，－4)。", "explanation": "由(2，4)得k＝8。联立8/x＝2x，得x²＝4，x＝±2；代回直线求y。", "rubric": ["用已知交点求出k＝8", "联立并求出另一个交点(－2，－4)"]}, {"type": "short", "question": "固定200 N的压力作用在面积A上，压强p＝200/A。A由0.04 m²变为0.10 m²，压强如何变化？", "answer": "压强从5000 Pa降为2000 Pa，变为原来的2/5。", "explanation": "分别代入p＝F/A。面积扩大2.5倍，压强变为原来的1/2.5＝2/5。", "rubric": ["两次计算使用平方米并得5000 Pa、2000 Pa", "说明压强与受力面积成反比例或给出2/5"]}], "sim": "inverse", "tags": ["反比例函数", "双曲线", "比例系数", "实际范围"]}, {"id": "math-27", "subject": "math", "chapter": "第二十七章", "title": "相似", "term": "下册", "category": "同步", "intro": "一张图片等比例放大后，长度、周长和面积分别按什么规律变化？", "periods": "8—10课时（建议）", "goals": ["能按对应顺序写相似关系与相似比", "能用三角形相似判定解决测高、分割和比例问题", "能解释位似作图及长度、面积缩放的区别"], "sections": [{"title": "27.1 图形的相似与对应关系", "body": "相似图形具有相同形状，大小可以不同。对相似多边形，对应角相等，对应边成比例，两类条件共同描述相似。先根据角或图形结构确定对应顶点，按相同顺序写出相似关系，再列边的比例。相似比具有方向，例如图A与图B的相似比为2，反过来图B与图A就是1/2。不要把“边长都增加相同长度”看作相似，那通常会改变比值。对于一般四边形，仅对应边成比例不一定相似，还要检查对应角和整体形状。"}, {"title": "27.2 相似三角形的判定", "body": "证明三角形相似，可用两角分别相等、三边成比例、两边成比例且夹角相等等条件。若三角形一边的平行线截另外两边或其延长线，常能从平行线角关系得到相似三角形。选择判定前先标注已有相等角与已知边比，注意“两边和一角”中的角必须是这两边的夹角，任意角并不足够。直角三角形通常容易利用一个共同锐角或互余锐角建立两角相等。写证明时对应顺序必须与随后使用的边比一致。"}, {"title": "27.2 相似三角形的性质与应用", "body": "若两个三角形的相似比为k，对应高、中线、角平分线以及周长的比都为k，面积比为k²。面积多出一个比例因子，是因为底和高同时缩放。测高时可利用同一时刻太阳光近似平行所形成的影子三角形；也可利用平面镜、测距线等构造相似，但必须说明地面水平、物体竖直等条件。遇到分段长度时先分清整边与局部线段，往往要先求总长再列比。得到长度后，应检查它是否与图形中的大小关系一致。"}, {"title": "27.3 位似与坐标中的放缩", "body": "位似是一种特殊的相似变换：对应点与同一固定点共线，对应线段平行或在同一直线上，这个固定点叫位似中心。以O为中心作图时，沿各顶点与O的射线或反向射线，按统一比例截取距离，再顺次连成新图。如果以原点为中心且对应点位于同侧，坐标可同时乘同一个正数k；若位于两侧，则乘－k。长度相似比始终取正值|k|，面积比为k²。只把横坐标放大而纵坐标不变通常会拉伸形状，不能称为位似。"}], "formulas": [{"text": "△ABC∽△DEF ⇒ AB/DE＝BC/EF＝AC/DF＝k", "note": "对应次序为A↔D、B↔E、C↔F，k＞0。"}, {"text": "周长比＝对应高之比＝k；面积比＝k²", "note": "比较方向与所定义的相似比一致。"}, {"text": "原点位似：P(x，y) → P′(λx，λy)", "note": "λ≠0；长度相似比为|λ|，λ＜0时对应点在原点两侧。"}], "examples": [{"question": "△ABC中，D在AB上、E在AC上且DE∥BC。已知AD＝3、DB＝2、AC＝10、BC＝8，求AE和DE。", "steps": ["由平行线得到两组对应角相等，故△ADE∽△ABC。", "AB＝AD＋DB＝5，相似比AD/AB＝3/5。", "AE＝(3/5)×10＝6，DE＝(3/5)×8＝24/5。"], "answer": "AE＝6，DE＝24/5。"}, {"question": "同一时刻，1.5 m高的标杆影长1.2 m，一棵竖直树的影长6.4 m。地面水平，求树高。", "steps": ["太阳光近似平行，标杆和树均竖直，两个直角三角形有相同锐角，因而相似。", "设树高h m，则h/6.4＝1.5/1.2。", "解得h＝6.4×1.25＝8。"], "answer": "树高约8 m。"}], "activity": {"title": "照片放大：一维和二维的差别", "materials": "方格纸、直尺、含网格的简单三角形", "steps": ["画顶点为(0，0)、(3，0)、(1，2)的三角形，计算底、高和面积。", "将每个顶点的两个坐标都乘2，画出放大后的三角形。", "量取对应边并比较周长，再用底乘高除以2计算面积。", "仅把横坐标乘2、纵坐标不变，画出另一图形，比较角度是否保持。", "总结等比例放大与单方向拉伸的区别。"], "recordHeaders": ["变换规则", "底", "高", "面积", "是否相似"], "conclusion": "两个方向都放大2倍时，长度与周长放大2倍、面积放大4倍；只沿一个方向拉伸通常不相似。", "safety": "作图与测量有误差，以坐标和计算结果为主要判断依据。"}, "mistakes": ["比例式对应错位：先写相似三角形的对应顺序，再列相应边比。", "已知两边成比例和一个非夹角相等就判相似：该条件一般不足，需检查判定要求。", "相似比为3就把面积比写成3：面积比应为9，因为底和高都乘3。"], "quiz": [{"type": "choice", "question": "两个相似三角形对应边之比为2∶3，它们的面积比为？", "options": ["2∶3", "3∶2", "4∶9", "8∶27"], "answer": 2, "explanation": "面积比等于相似比的平方，即(2/3)²＝4/9。"}, {"type": "choice", "question": "以下哪组条件足以判定两个三角形相似？", "options": ["两个角分别相等", "一条边相等", "面积相等", "周长相等"], "answer": 0, "explanation": "两角分别相等是相似三角形的有效判定，其他条件单独都不足。"}, {"type": "choice", "question": "以原点为中心同侧放大3倍，点(－2，1)变为？", "options": ["(－6，3)", "(6，－3)", "(－2，3)", "(1，4)"], "answer": 0, "explanation": "同侧位似时两个坐标都乘正数3。"}, {"type": "choice", "question": "△ABC∽△DEF，A、B、C依次对应D、E、F。若AB/DE＝3/4且BC＝9，则EF为？", "options": ["27/4", "12", "6", "16"], "answer": 1, "explanation": "BC/EF＝3/4，所以9/EF＝3/4，EF＝12。"}, {"type": "short", "question": "在△ABC中，DE∥BC，D、E分别位于AB、AC上。若AD∶DB＝2∶3，BC＝15，求DE及△ADE与△ABC的面积比。", "answer": "DE＝6；面积比为4∶25。", "explanation": "AD/AB＝2/(2＋3)＝2/5。两三角形相似，DE＝15×2/5＝6，面积比为(2/5)²。", "rubric": ["把局部线段比转换为AD/AB＝2/5并求DE", "将长度相似比平方得到4∶25"]}, {"type": "short", "question": "原图中一条对应高为5 cm、面积为20 cm²。相似放大后该高为8 cm，求新图面积。", "answer": "新图面积为51.2 cm²。", "explanation": "相似比为8/5，面积比为64/25，新面积＝20×64/25＝51.2。", "rubric": ["用对应高得到相似比8/5", "正确平方并算出面积51.2 cm²"]}], "sim": "similarity", "tags": ["相似三角形", "相似比", "面积比", "位似", "测高"]}, {"id": "math-28", "subject": "math", "chapter": "第二十八章", "title": "锐角三角函数", "term": "下册", "category": "同步", "intro": "不攀登建筑物，只测地面距离和仰角，怎样求它的高度？", "periods": "7—9课时（建议）", "goals": ["能相对于指定锐角辨认对边、邻边和斜边", "能准确使用30°、45°、60°的三角函数值", "能结合仰俯角、坡度及测量高度解直角三角形"], "sections": [{"title": "28.1 锐角三角函数的定义", "body": "在直角三角形中，固定一个锐角A，与它相对的直角边叫对边，与它相邻的直角边叫邻边，直角对着的最长边叫斜边。sin A是对边与斜边之比，cos A是邻边与斜边之比，tan A是对边与邻边之比。相似直角三角形的对应边成比例，所以这些比值由角A决定，不随图形整体放大而改变。先标角再认边，不能把纸面上的上下、左右当作定义。三角函数值是比值，没有长度单位，但用于计算后所得的边长有单位。"}, {"title": "28.1 特殊角与数值计算", "body": "用边长为1的等腰直角三角形可推出45°的正弦、余弦都为√2/2，正切为1。把边长为2的等边三角形一分为二，可以得到30°、60°的三组函数值。记忆最好从这些图形出发，而不是互不联系地背表。使用计算器求任意锐角的函数值或反求角度时，应确认处于角度制而非弧度制，并按题目要求保留精度。中间步骤尽量保留足够位数，到最后再统一四舍五入，避免测高结果因多次取整累积偏差。"}, {"title": "28.2 解直角三角形", "body": "解直角三角形是由已知的边、角求其余元素。两锐角和为90°，三边满足勾股关系，还可根据已知边与目标边选择正弦、余弦或正切。已知两个锐角只能确定形状，不能确定大小，必须至少知道一条边才能确定具体边长。设直角为C，若已知A及斜边c，则对边a＝c sin A、邻边b＝c cos A；若已知邻边和角，可用tan A求对边。列式前画草图并标出已知量，可以显著减少把边与角对应错位的错误。"}, {"title": "28.2 仰角、俯角与坡度应用", "body": "仰角是视线向上时与观察者水平线的夹角，俯角是向下时与水平线的夹角，二者都不是默认与竖直线夹角。测高时先求目标与眼睛之间的高度差，再加上眼高；若地面存在高差，应额外画出参考水平线。坡度通常用竖直升高与水平距离之比表示，等于坡角的正切，不是升高除以斜坡长度。处理航行方向或方位角时先按题意画方向线，再转化为直角三角形。现实测量要说明距离、角度误差以及竖直、水平等假设。"}], "formulas": [{"text": "sin A＝对边/斜边；cos A＝邻边/斜边；tan A＝对边/邻边", "note": "A为直角三角形中的锐角；邻边专指与A相邻的直角边。"}, {"text": "30°：(sin，cos，tan)＝(1/2，√3/2，√3/3)", "note": "由等边三角形的一半推导。"}, {"text": "45°：(sin，cos，tan)＝(√2/2，√2/2，1)", "note": "由等腰直角三角形推导。"}, {"text": "60°：(sin，cos，tan)＝(√3/2，1/2，√3)", "note": "与30°互余。"}, {"text": "坡度i＝竖直高度/水平距离＝tan α", "note": "α为坡面与水平面的夹角；不要把水平距离换成坡长。"}], "examples": [{"question": "直角三角形ABC中∠C＝90°，AB＝10 cm，∠A＝30°。求两条直角边。", "steps": ["AB为斜边，BC是∠A的对边，AC是邻边。", "BC＝AB sin30°＝10×1/2＝5 cm。", "AC＝AB cos30°＝10×√3/2＝5√3 cm。"], "answer": "BC＝5 cm，AC＝5√3 cm。"}, {"question": "观察者眼睛离地1.6 m，在距竖直旗杆底部12 m的水平地面上测得顶部仰角45°，求旗杆高度。", "steps": ["从眼睛作水平线与旗杆相交，形成水平边12 m的直角三角形。", "顶部相对眼睛的高度差为12tan45°＝12 m。", "旗杆全高＝高度差＋眼高＝12＋1.6。"], "answer": "旗杆高度为13.6 m。"}], "activity": {"title": "在安全平地完成一次间接测高", "materials": "量角器与铅垂线制成的简易测角器、卷尺、记录表", "steps": ["选择平地上竖直、底部可安全接近的目标，测量观察点到目标底部的水平距离。", "测量观察者眼高，并由同伴协助读取顶部视线的仰角。", "画出示意图，写出目标高度＝水平距离×tan仰角＋眼高。", "换两个观察距离重复测量，比较三次结果。", "讨论地面倾斜、读角误差和目标不竖直会怎样影响估计。"], "recordHeaders": ["水平距离/m", "仰角/°", "眼高/m", "估计高度/m", "误差来源"], "conclusion": "测角与测距可用三角函数转化为高度；重复测量有助于识别误差，三次结果不会必然完全相同。", "safety": "只在教师允许的平地测量，不攀爬、不靠近道路和带电设施，不观察太阳；卷尺使用注意行人。"}, "mistakes": ["看到同一条直角边就总称它为对边：对边和邻边随指定锐角改变。", "测高只写d tanα：它通常是目标与眼睛的高度差，需加眼高并处理地面高差。", "坡度用高度除以坡长：定义中的分母是水平距离，坡度等于坡角的正切。"], "quiz": [{"type": "choice", "question": "sin30°的值为？", "options": ["1/2", "√2/2", "√3/2", "1"], "answer": 0, "explanation": "30°直角三角形中30°对边等于斜边的一半。"}, {"type": "choice", "question": "直角三角形中，锐角A的对边为6、邻边为8，则tan A＝？", "options": ["3/5", "4/5", "3/4", "4/3"], "answer": 2, "explanation": "正切等于对边与邻边的比，tan A＝6/8＝3/4。"}, {"type": "choice", "question": "一斜坡每水平前进5 m升高1 m，它的坡度为？", "options": ["1∶5", "5∶1", "1∶√26", "5∶√26"], "answer": 0, "explanation": "坡度是竖直高度与水平距离之比，即1∶5。"}, {"type": "choice", "question": "已知直角三角形的一个锐角为40°，另一个锐角为？", "options": ["40°", "50°", "60°", "140°"], "answer": 1, "explanation": "两锐角互余，90°－40°＝50°。"}, {"type": "short", "question": "一根长6 m的梯子与水平地面成60°角，求梯脚到墙的水平距离和梯顶离地高度。墙与地面垂直。", "answer": "水平距离3 m；高度3√3 m。", "explanation": "梯子是斜边，水平距离＝6cos60°＝3，高度＝6sin60°＝3√3。该题是理想几何模型，不作为真实架梯操作建议。", "rubric": ["识别梯长为斜边并选择cos求邻边", "用sin求高度，两个结果均带正确单位"]}, {"type": "short", "question": "在水平地面距楼底20 m处，眼高1.5 m的观察者测得楼顶仰角30°。求楼高的精确式及近似值，结果保留0.1 m。", "answer": "楼高为1.5＋20√3/3 m，约13.0 m。", "explanation": "高度差＝20tan30°＝20√3/3≈11.547，再加1.5得13.047，保留一位小数为13.0。", "rubric": ["用tan30°求高度差并加眼高1.5 m", "精确式和按要求取整的13.0 m正确"]}], "sim": "trig", "tags": ["正弦", "余弦", "正切", "解直角三角形", "仰角", "坡度"]}, {"id": "math-29", "subject": "math", "chapter": "第二十九章", "title": "投影与视图", "term": "下册", "category": "同步", "intro": "从正面、左面和上面看到的三张平面图，怎样共同描述一个立体？", "periods": "5—6课时（建议）", "goals": ["能区分平行投影、中心投影和正投影", "能按长对正、高平齐、宽相等绘制简单物体三视图", "能利用视图解释立体结构并识别信息不足的情形"], "sections": [{"title": "29.1 投影及其类型", "body": "物体在光线照射下形成的影子可帮助理解投影。由平行光线形成的是平行投影，由同一点发出的光线形成的是中心投影；投射线垂直于投影面时，平行投影称为正投影。太阳光可近似看作平行光，近处点光源产生的影子则体现中心投影。影子的形状与大小取决于物体姿态、投射方向和投影面位置，不能由“影子一样大”直接推断物体一样大。正投影便于表达物体尺寸，是三视图的基础；斜放的线段可能在投影中缩短。"}, {"title": "29.2 三视图及其位置关系", "body": "从正面、左面和上面观察物体，分别得到主视图、左视图和俯视图，三者都使用正投影。规范排布通常把俯视图放在主视图下方，把左视图放在主视图右侧。三图遵循长对正、高平齐、宽相等：主视图与俯视图共有长度，主视图与左视图共有高度，左视图与俯视图共有宽度。绘制前先明确正面方向，再区分看得见的轮廓线与被遮挡的棱线，后者需要时用虚线表示。观察方向变了，主视图的形状也可能改变。"}, {"title": "29.2 从立体到视图、从视图到立体", "body": "画视图时可以先确定外轮廓，再补内部可见棱与必要的隐藏线。长方体的三个视图都是矩形；圆柱在轴线竖直放置时，主、左视图为矩形，俯视图为圆。反向还原时，须同时满足三幅图提供的约束，单凭一个圆形视图不能确定物体就是球，因为圆柱等立体也可能出现圆形投影。小正方体搭建题可先根据俯视图确定占地格子，再用主、左视图约束每行每列最高层数。若约束不足，可能存在多个不同搭法，应明确说明而非强行给唯一答案。"}], "formulas": [{"text": "主视图：长×高；俯视图：长×宽；左视图：宽×高", "note": "这里表示所反映的尺寸方向；不表示每个视图必定为矩形。"}, {"text": "三视图配合：长对正，高平齐，宽相等", "note": "先统一观察方向和比例，再对应尺寸。"}, {"text": "正投影：投射线互相平行且垂直于投影面", "note": "平行投影并非都属于正投影。"}], "examples": [{"question": "一个长方体左右方向长6 cm、前后方向宽4 cm、竖直高3 cm。求主视图、俯视图和左视图的尺寸。", "steps": ["正面投影保留左右长度与竖直高度，主视图为6 cm×3 cm。", "上方投影保留左右长度与前后宽度，俯视图为6 cm×4 cm。", "左侧投影保留前后宽度与竖直高度，左视图为4 cm×3 cm。"], "answer": "主视图6×3 cm，俯视图6×4 cm，左视图4×3 cm，均为矩形。"}, {"question": "桌面同一排摆放三列小正方体，从左到右层数分别为1、3、2，且前后只有一排。描述三视图并求方块总数。", "steps": ["主视图从左到右的列高为1、3、2。", "俯视图为横向相连的三个单位正方形。", "从左看，不同左右位置互相遮挡，只保留最大高度3，所以左视图是一列高3的长方形。", "方块总数为1＋3＋2＝6。"], "answer": "主视图列高1、3、2；俯视图一排3格；左视图一列高3；共6块。"}], "activity": {"title": "三张轮廓图能否唯一还原积木", "materials": "至少7个相同小正方体、2×2方格底板、方格纸", "steps": ["在2×2底板上搭出各格层数为前排[2，1]、后排[1，2]的结构，总计6块。", "记录占地格子，并从正面、左面画出只表示每列最高层数的轮廓。", "把前排右格增为2层，得到前排[2，2]、后排[1，2]的结构，总计7块。", "比较两种结构的俯视占地和主、左视最高轮廓是否改变。", "讨论若需要区分这两种结构，应该补充哪些分层信息、内部棱线或立体图。"], "recordHeaders": ["搭法", "前排层数", "后排层数", "方块总数", "最高轮廓是否相同"], "conclusion": "两种搭法占地均为2×2格，主视和左视最高轮廓均为两列各高2，但总数分别为6与7；仅这些轮廓信息不能唯一还原。", "safety": "本活动特意只比较最高轮廓和占地，不把它们等同于标出全部可见棱线的完整工程视图；积木稳定摆放，避免抛掷。"}, "mistakes": ["把左视图理解为画在纸的左边：规范三视图中左视图通常排在主视图右侧。", "看到圆形俯视图就断定是球：圆柱、圆锥等也可能有圆形俯视图，还需其他视图。", "用俯视占地格子数当作积木总数：同一格可能叠有多层，需要结合高度约束。"], "quiz": [{"type": "choice", "question": "以下哪种情况最接近平行投影？", "options": ["近处小灯泡照射物体", "太阳光照射地面物体", "从固定眼点透视看物体", "物体绕轴旋转"], "answer": 1, "explanation": "太阳距离很远，照射一个小范围物体的光线可近似平行。"}, {"type": "choice", "question": "主视图与俯视图必须对应相等的尺寸是？", "options": ["高度", "宽度", "长度", "体积"], "answer": 2, "explanation": "主视图反映长与高，俯视图反映长与宽，两图共有长度方向。"}, {"type": "choice", "question": "轴线竖直放置的实心圆柱，其俯视图通常是？", "options": ["三角形", "圆", "斜线段", "梯形"], "answer": 1, "explanation": "从上向下作正投影，看到圆形底面轮廓。"}, {"type": "choice", "question": "同一排三列积木层数依次为2、4、1，前后只有一排，从左面看的最高层数为？", "options": ["1", "2", "4", "7"], "answer": 2, "explanation": "左右各列在左视方向重叠，轮廓保留最高的4层。"}, {"type": "short", "question": "长方体长8 cm、宽5 cm、高2 cm，写出三个视图的尺寸，并指出哪两图体现相同高度。", "answer": "主视图8×2 cm，俯视图8×5 cm，左视图5×2 cm；主视图与左视图体现相同高度。", "explanation": "按长、宽、高三个空间方向分别投影，主视与左视均保留竖直方向，故高平齐。", "rubric": ["三个视图尺寸与观察方向对应正确", "说明主视图和左视图高度相同且为2 cm"]}, {"type": "short", "question": "某物体俯视图为圆。仅凭这一信息能否断定物体是球？请给两个其他可能的例子并说明需要补充什么。", "answer": "不能；轴线竖直的圆柱或圆锥也可有圆形俯视图，需要补充主视图、左视图或立体结构信息。", "explanation": "正投影会丢失观察方向上的深度信息，不同立体可能得到相同单一视图；综合多个方向才能增加约束。", "rubric": ["否定唯一判断并给出圆柱、圆锥两个合理反例", "说明需要其他方向视图或结构信息"]}], "sim": "views", "tags": ["平行投影", "中心投影", "正投影", "三视图", "空间想象"]}]}, {"subject": "physics", "edition": "人教版九年级物理全一册 · 经典目录", "editionNote": "按人民教育出版社公开的2011课标版经典目录编排，覆盖第十三至二十二章全部39节。2024审定新版的节次、部分章名和跨学科实践安排有所调整；请按本校教材及知识名称对应使用，不标称最新版。正文、例题和练习均为原创教学资料，建议课时由教师按学情调整。", "sources": [{"title": "人民教育出版社：物理·九年级全一册（经典目录，ISBN 9787107262173）", "url": "https://www.pep.com.cn/products/jc/czjks/201510/t20151026_1250822.shtml"}, {"title": "人民教育出版社：义务教育教科书教师教学用书物理九年级", "url": "https://www.pep.com.cn/products/jc/jks/201510/t20151026_1250904.shtml"}, {"title": "国家消防救援局消防科普：什么是电器火灾（安全用电依据）", "url": "https://www.119.gov.cn/kp/zjts/hz/2022/1068.shtml"}, {"title": "江苏省消防救援总队：注意家里这些小细节，别留安全隐患", "url": "https://js.119.gov.cn/202311/35463ade55aa4cb185f79be3182b26de_c_3b534e7bb0db4cf8b867.html"}], "chapters": [{"id": "physics-13", "subject": "physics", "chapter": "第十三章", "title": "内能", "term": "全一册", "category": "同步", "intro": "为什么同样晒一会儿，沙滩比海水热得快？从微观运动解释温度与热量。", "periods": "5—6课时（建议）", "goals": ["用扩散现象说明分子在不停地做无规则运动", "区分温度、内能与热量，辨认两种改变内能的方式", "用Q=cmΔt解决无物态变化的吸放热问题"], "sections": [{"title": "13.1 分子热运动", "body": "物质由大量微观粒子组成，分子之间有间隙，并存在相互作用的引力和斥力。不同物质接触后彼此进入对方的现象叫扩散，反映分子不停地做无规则运动；温度越高，热运动越剧烈。水滴中可见的细小颗粒或空气中的灰尘都不是分子。固体难以压缩、也难以拉伸，要分别联系距离很近时的斥力和适当距离下的引力。观察食用色素在水中的散开时，还要辨别滴入扰动、对流等因素，不能把所有宏观流动都直接当作分子运动。"}, {"title": "13.2 内能", "body": "物体内部所有分子热运动的动能与分子势能的总和叫内能。内能属于物体的微观能量，不等同于整个物体运动的机械能；静止的冰块也有内能。内能与温度、质量、物态等有关，不能只比较温度高低。做功和热传递都能改变内能：摩擦把机械能转化为内能；较热物体向较冷物体传递能量。热量是热传递过程中传递能量的多少，不能说物体“含有热量”。温度变化有助于判断内能变化，但物态变化时也可能吸热而温度不变。"}, {"title": "13.3 比热容", "body": "比较不同物质升温的难易，要控制质量和升高的温度相同，再比较吸收的热量。单位质量的某种物质温度升高1℃吸收的热量叫比热容，单位是J/(kg·℃)。相同物态下，比热容表征物质的热学性质，不由样品质量决定。水的比热容约为4.2×10³J/(kg·℃)，可解释沿海昼夜温差较小和水用于冷却等现象。计算Q=cmΔt时，质量用千克，升温量取末温减初温；降温放热量取初温减末温。该式用于不发生物态变化且比热容可视为恒定的过程。"}], "formulas": [{"text": "Q吸=cm(t末−t初)", "note": "无物态变化；c单位J/(kg·℃)，m单位kg，Q单位J。"}, {"text": "Q放=cm(t初−t末)", "note": "计算放出热量的大小，温差取正值。"}], "examples": [{"question": "0.50kg水从20℃升到40℃，吸收多少热量？取c水=4.2×10³J/(kg·℃)。", "steps": ["温升Δt=40−20=20℃。", "Q=cmΔt=4.2×10³×0.50×20J。"], "answer": "4.2×10⁴J。"}, {"question": "质量相同的水和某液体吸收相同热量后，水升温5℃，该液体升温10℃。求该液体比热容。", "steps": ["相同热量、相同质量，c水Δt水=c液Δt液。", "c液=4.2×10³×5÷10J/(kg·℃)。"], "answer": "2.1×10³J/(kg·℃)。"}], "activity": {"title": "同温不同量：比较水的降温", "materials": "两个相同耐温杯、室温水、教师准备的不超过40℃温水、温度计、量杯、计时器。", "steps": ["分别量取100mL、200mL同初温的温水，放在同样环境中。", "同时记录初温，此后每2分钟读温度一次，共记录10分钟。", "画出温度随时间变化图，讨论质量与储存、放出能量的关系。", "指出两杯散热面积、对流等也可能不同，不能把该实验当成对比热容的精确测量。"], "recordHeaders": ["水量/mL", "时间/min", "水温/℃", "降温量/℃"], "conclusion": "相同温降时，质量较大的水放出热量较多；降温快慢还受散热条件影响，应把计算结论与观察条件分开。", "safety": "只用不超过40℃温水，不用明火和沸水；温度计轻放，不碰杯底杯壁。"}, "mistakes": ["“温度高，内能一定大”错误：还要考虑质量、物态与物质种类。", "“吸热一定升温”错误：熔化、沸腾等过程可吸热而温度不变。", "“热量从内能大的物体传向内能小的物体”错误：自发热传递方向由温度差决定。"], "quiz": [{"type": "choice", "question": "下列哪一现象最直接支持分子在不停地运动？", "options": ["操场上灰尘随风飞舞", "糖溶于静置水后，远处的水也逐渐变甜", "足球沿地面滚动", "搅拌使茶叶旋转"], "answer": 1, "explanation": "糖分子逐渐扩散到水的各处；其余主要是宏观物体运动。"}, {"type": "choice", "question": "一块0℃的冰，下列说法正确的是？", "options": ["没有内能", "分子完全静止", "仍具有内能", "内能等于热量"], "answer": 2, "explanation": "0℃不是分子停止运动的温度，冰也有内能。"}, {"type": "choice", "question": "用力搓手后手变暖，主要通过哪种方式改变内能？", "options": ["做功", "热传递", "蒸发", "光的反射"], "answer": 0, "explanation": "摩擦做功把机械能转化为内能。"}, {"type": "choice", "question": "0.20kg水升高10℃需要吸收多少热量？c水=4.2×10³J/(kg·℃)。", "options": ["420J", "840J", "4200J", "8400J"], "answer": 3, "explanation": "Q=4.2×10³×0.20×10=8400J。"}, {"type": "short", "question": "质量均为1kg的水和铜，吸收相同热量且没有物态变化。已知c水大于c铜，谁的温升更大？说明理由。", "answer": "铜的温升更大。", "explanation": "由Δt=Q/(cm)，相同Q和m时，比热容越小，温升越大。", "rubric": ["判断铜温升更大。", "说明控制Q、m相同，并用反比关系解释。"]}, {"type": "short", "question": "将2kg水从35℃冷却到25℃，求水放出的热量。取c水=4.2×10³J/(kg·℃)。", "answer": "8.4×10⁴J。", "explanation": "Q放=4.2×10³×2×(35−25)=8.4×10⁴J。", "rubric": ["温差取35−25=10℃。", "公式、计算和单位正确。"]}], "sim": "heat", "tags": ["分子热运动", "温度", "内能", "热量", "比热容"]}, {"id": "physics-14", "subject": "physics", "chapter": "第十四章", "title": "内能的利用", "term": "全一册", "category": "同步", "intro": "汽车怎样把燃料的能量变成运动？没有做成有用功的能量去了哪里？", "periods": "4—5课时（建议）", "goals": ["辨认四冲程内燃机的基本工作过程", "用热值与效率计算有用能量或燃料消耗", "用能量转化与守恒解释实际装置中的损耗"], "sections": [{"title": "14.1 热机", "body": "热机把内能转化为机械能，四冲程汽油机可按吸气、压缩、做功、排气来理解。吸气冲程吸入燃料与空气的混合物；压缩时活塞对气体做功，机械能转为内能；点火后高温高压气体推动活塞，在做功冲程把部分内能转为机械能；排气冲程排出废气。完整工作循环中活塞往复两次、曲轴通常转两周，只有一次做功冲程，其余过程依靠飞轮惯性等完成。柴油机压缩空气再喷入燃料压燃，不能把所有内燃机都描述为火花塞点火。"}, {"title": "14.2 热机的效率", "body": "燃料完全燃烧放出的热量可由Q=mq计算，热值q表示单位质量燃料完全燃烧放出的热量。若热值以J/m³给出，则用Q=Vq。实际热机中，燃料释放的能量一部分成为有用机械功，另外通过废气、冷却系统、摩擦等传向环境。热机效率等于有用机械功与燃料完全燃烧放热量之比。提高效率可减少不必要散热和摩擦、改善燃烧，但不能据此得到百分之百有效的实际热机。热值是燃料性质，效率是装置利用能量的程度，两者不是同一个量。"}, {"title": "14.3 能量的转化和守恒", "body": "能量可以在内能、机械能、电能、化学能等形式之间转化，也可以在物体之间转移；转化或转移过程中总能量守恒。电动玩具中，电池化学能转为电能，再转为机械能、内能和声音携带的能量。所谓“能量损失”通常指能量分散到环境中，难以继续按照原目的利用，并非能量消失。分析问题先确定研究的系统边界，再写出输入、有用输出和其他输出。节约能源与能量守恒并不矛盾，因为可便捷利用的能源有限，能量转化具有方向性和利用代价。"}], "formulas": [{"text": "Q放=mq；Q放=Vq", "note": "m用kg；质量热值q用J/kg。体积公式中V与q的体积单位需一致。"}, {"text": "η=W有用/Q放×100%", "note": "效率计算中各能量必须同单位；有用输出依装置目的定义。"}, {"text": "E输入=E有用+E其他", "note": "先明确系统边界；稳态简化模型中忽略装置自身储能变化。"}], "examples": [{"question": "某燃料热值为4.0×10⁷J/kg，完全燃烧0.05kg，放热多少？若热机效率为30%，有用功多少？", "steps": ["Q=mq=0.05×4.0×10⁷=2.0×10⁶J。", "W有用=ηQ=0.30×2.0×10⁶J。"], "answer": "放热2.0×10⁶J，有用功6.0×10⁵J。"}, {"question": "某四冲程汽油机曲轴转速为1800r/min，每秒完成多少次做功冲程？", "steps": ["每秒转数1800÷60=30r。", "每完成一个工作循环曲轴转2周，且有一次做功冲程。"], "answer": "每秒15次做功冲程。"}], "activity": {"title": "用能量筹码给热机画收支图", "materials": "100个纸筹码或数字计数器、纸笔、彩笔。", "steps": ["把100个筹码设为一次工作循环的输入能量。", "按有用功30、废气40、冷却25、摩擦等5个筹码分组。", "画能量流向图，计算效率，并检验输出总和。", "提出节能改进：例如减少摩擦后重新分配筹码，说明模型假设。"], "recordHeaders": ["方案", "输入能量/格", "有用功/格", "其他输出/格", "效率/%"], "conclusion": "能量收支始终平衡；效率提高意味着相同输入下有用输出增加，不能凭空制造能量。", "safety": "本活动为纸上能量模型，不点燃燃料，不密闭加热容器，不制作高温高压热机。"}, "mistakes": ["“燃料燃烧越充分，热值就越大”错误：热值按完全燃烧定义，取决于燃料种类等性质。", "“效率提高就是能量增加”错误：提高的是有用输出占输入的比例。", "“四个冲程都对外做功”错误：一般只有做功冲程由高温气体推动活塞对外做功。"], "quiz": [{"type": "choice", "question": "四冲程汽油机中，气体内能明显转化为机械能的是哪一冲程？", "options": ["吸气", "压缩", "做功", "排气"], "answer": 2, "explanation": "做功冲程中高温高压气体推动活塞。"}, {"type": "choice", "question": "燃烧同种燃料，质量变为原来的2倍，热值如何变化？", "options": ["不变", "变为2倍", "变为一半", "变为4倍"], "answer": 0, "explanation": "热值不随所取燃料质量改变。"}, {"type": "choice", "question": "输入能量为5000J，有用机械功为1500J，效率是多少？", "options": ["15%", "30%", "70%", "3.3%"], "answer": 1, "explanation": "η=1500/5000×100%=30%。"}, {"type": "choice", "question": "关于节约能源，正确的是？", "options": ["能量守恒，所以永远不用节能", "能量损失表示能量彻底消失", "效率为100%的燃油机已普遍使用", "分散到环境的能量通常难以重新按原目的利用"], "answer": 3, "explanation": "能量虽然守恒，但利用有方向性和代价。"}, {"type": "short", "question": "某燃料热值为3.0×10⁷J/kg，热机效率为25%。要输出1.5×10⁶J有用功，至少需完全燃烧多少千克燃料？", "answer": "0.20kg。", "explanation": "Q=W/η=6.0×10⁶J，m=Q/q=0.20kg。", "rubric": ["用W/η求所需输入能量。", "算出质量0.20kg，单位正确。"]}, {"type": "short", "question": "同一杯水由电热器加热时，电能1000J转入系统，水获得800J内能。其余200J可能去了哪里？这是否违背能量守恒？", "answer": "可能成为容器、加热器和周围空气的内能；不违背能量守恒。", "explanation": "选取水作为目标对象时，有用吸收只占一部分；扩大系统边界后能量总收支仍相等。", "rubric": ["合理指出至少一种其他能量去向。", "明确能量未消失，并联系系统边界解释。"]}], "sim": "energy", "tags": ["热机", "四冲程", "热值", "效率", "能量守恒"]}, {"id": "physics-15", "subject": "physics", "chapter": "第十五章", "title": "电流和电路", "term": "全一册", "category": "同步", "intro": "同一开关为什么能控制一盏灯，也能控制几盏灯？先学会识图、连接与测量。", "periods": "6—8课时（建议）", "goals": ["用电荷相互作用和电荷转移解释简单静电现象", "识别通路、断路、短路并画串并联电路", "正确连接电流表并验证串并联电流规律"], "sections": [{"title": "15.1 两种电荷", "body": "自然界存在正、负两种电荷，同种电荷相互排斥，异种电荷相互吸引。摩擦起电通常是电子从一个物体转移到另一个物体，并不是摩擦创造了电荷：失去电子的物体带正电，得到电子的带负电。带电体还能吸引轻小的中性物体，因此“能吸引”不能单独证明两物体带异种电荷；相互排斥则能支持它们带同种电荷。验电器利用同种电荷相斥原理。金属容易导电，是因为内部有能够自由移动的电子；绝缘体并非没有电荷，而是自由移动的电荷很少。"}, {"title": "15.2 电流和电路", "body": "电荷的定向移动形成电流，规定正电荷定向移动的方向为电流方向，金属导线中电子移动方向与之相反。电路通常包括电源、用电器、开关和导线；持续电流需要电源以及闭合通路。通路中用电器正常接入，断路时路径被切断，电源短路则用低电阻导线直接连通电源两端，可能产生过大电流。绘图使用规范元件符号，导线横平竖直、结点标清。分析时先从电源正极出发追踪完整路径，不把空间位置的“靠近”误判为电路上的相连。"}, {"title": "15.3 串联和并联", "body": "串联电路中的元件依次相连，电流只有一条路径；任一处断开，整条回路都不通。并联电路在结点处分流，各支路分别连接到相同的两结点，一条支路断开时其他支路仍可能工作。干路开关控制所有支路，支路开关只控制该支路。判断串并联要看电流路径与连接结点，不能仅看灯泡画在同一行还是上下两排。将电路图沿导线“拉伸”而不改变结点关系，电路性质不变；导线交叉但无连接点的地方，按图示约定不能擅自当成相连。"}, {"title": "15.4 电流的测量", "body": "电流用I表示，单位安培，1A=1000mA。电流表必须串联在被测路径中，使电流从正接线柱流入、负接线柱流出；量程不确定时先选较大量程，经过教师检查后试触，再按需要调整。读数先辨量程和分度值，视线正对刻度。电流表内阻很小，不能直接接在电源两端，否则可能造成短路。换接电表或改变电路时先断开开关。若读数方向反向或超过量程，应立即断开检查，不能靠长时间观察来确认故障。"}, {"title": "15.5 串、并联电路中电流的规律", "body": "串联电路各处电流相等，原因是沿同一条路径没有持续积累电荷的地方。并联电路干路电流等于各支路电流之和，体现结点处电荷流入与流出的平衡。验证规律要分别测量多处电流，再改变灯泡或电阻的组合进行多次实验，避免只用相同元件得到特殊结果。两条并联支路电流并不总相等，具体大小取决于支路条件。记录表要明确每个测量位置和单位；出现小差异时先考虑仪器分度、读数和连接等因素，不应未经分析就否定规律。"}], "formulas": [{"text": "串联：I=I₁=I₂", "note": "稳定直流串联电路，各处电流相同。"}, {"text": "并联：I总=I₁+I₂+…", "note": "同一结点处流入电流之和等于流出电流之和。"}, {"text": "1A=1000mA", "note": "电流单位换算，避免把0.2A写成0.2mA。"}], "examples": [{"question": "两灯并联，干路电流0.70A，一条支路电流0.25A，另一条支路是多少？", "steps": ["使用并联电流规律I总=I₁+I₂。", "I₂=0.70−0.25A。"], "answer": "0.45A。"}, {"question": "电流表接0—0.6A量程，刻度盘共有30个小格，指针在第18格。读数是多少？", "steps": ["分度值为0.6÷30=0.02A/格。", "读数为18×0.02A。"], "answer": "0.36A，即360mA。"}], "activity": {"title": "低压电路的三处电流", "materials": "教师提供的3V电池盒、两只额定电压适合的教学小灯泡、开关、电流表、导线。", "steps": ["断开开关，把两灯串联并画图，请教师检查后短时通电。", "分别把电流表串在三个位置，每次换接前断开开关。", "记录电流，比较三处数值。", "在教师指导下改为并联，测量干路与两支路电流，比较它们的和。"], "recordHeaders": ["连接方式", "测量位置", "量程/A", "电流/A", "规律判断"], "conclusion": "串联各处电流相等，并联干路电流等于支路电流之和；具体测值允许有合理测量误差。", "safety": "只用3V电池教学电路；绝不接市电，禁止导线或电流表直接跨接电源两端，电池发热立即断开。"}, "mistakes": ["“电流经过灯泡就被用掉”错误：用电器转化电能，并不持续消耗电荷。", "“两灯画在上下两排就是并联”错误：要检查是否连接在同一对结点之间。", "“电流表和电压表接法一样”错误：电流表必须串联，不能直接跨接电源。"], "quiz": [{"type": "choice", "question": "摩擦后塑料棒带负电，说明塑料棒通常发生了什么？", "options": ["产生了大量质子", "得到电子", "失去电子", "失去所有电荷"], "answer": 1, "explanation": "得到电子使物体带负电，摩擦没有创造净电荷。"}, {"type": "choice", "question": "下列连接中最容易造成电源短路的是？", "options": ["电池、灯泡和开关串联", "开关处于断开状态", "电压表测灯泡两端电压", "一根导线直接连通电池正负极"], "answer": 3, "explanation": "导线电阻很小，直接跨接电源两端可导致很大的电流。"}, {"type": "choice", "question": "两灯串联，通过第一盏灯的电流为0.18A，第二盏为多少？", "options": ["0.09A", "0.18A", "0.36A", "不能判断"], "answer": 1, "explanation": "串联电路各处电流相等。"}, {"type": "choice", "question": "金属导线中自由电子向左定向移动，电流方向是？", "options": ["向右", "向左", "上下交替", "无电流"], "answer": 0, "explanation": "规定的电流方向与电子定向移动方向相反。"}, {"type": "short", "question": "两条并联支路电流分别为120mA和0.28A，求干路电流，并解释为什么先统一单位。", "answer": "干路电流0.40A。", "explanation": "120mA=0.12A，I总=0.12+0.28=0.40A；不同单位的数值不能直接相加。", "rubric": ["将120mA正确换为0.12A。", "应用并联规律并说明统一单位。"]}, {"type": "short", "question": "想使两盏台灯能够各自独立开关，低压模型中应怎样连接灯和开关？", "answer": "两灯并联，每条灯支路分别串联一个开关。", "explanation": "并联各支路可独立成路，支路开关只切断相应路径。", "rubric": ["指出两灯并联。", "指出各开关分别与对应灯串联。"]}], "sim": "circuit", "tags": ["静电", "电流", "串联", "并联", "电流表"]}, {"id": "physics-16", "subject": "physics", "chapter": "第十六章", "title": "电压 电阻", "term": "全一册", "category": "同步", "intro": "电池为什么能推动电荷定向移动？怎样用一个滑片控制电流大小？", "periods": "5—6课时（建议）", "goals": ["正确用电压表测量并运用串并联电压规律", "用控制变量法分析导体电阻的影响因素", "辨认滑动变阻器有效接入的电阻丝部分"], "sections": [{"title": "16.1 电压", "body": "电压是使电荷定向移动形成电流的原因之一，电源在两端提供电压，但电路中有电压不等于一定有电流，还必须形成通路。电压用U表示，单位伏特，1kV=1000V，1V=1000mV。一节常见干电池约为1.5V。电压表并联在被测元件两端，使电流从正接线柱流入；测量前先估计范围，选择合适量程。理想电压表电阻很大，接入后对原电路影响可忽略。串接电压表通常不能代替正常通路，电流表与电压表的接法不可混用。"}, {"title": "16.2 串、并联电路中电压的规律", "body": "串联电路电源两端电压等于各串联元件两端电压之和；并联的各支路跨接在同一对结点之间，所以支路两端电压相等，并等于干路两端电压。串联灯泡若规格不同，分得的电压一般也不同；只有满足相应条件才会平均分压。探究时改变元件组合、重复测量，让特殊数据与普遍规律分开。两节同规格电池同向串联时电压约相加；接法不当会抵消或产生风险。解题先画出被测两结点，防止把“相邻位置”误当成同一电压。"}, {"title": "16.3 电阻", "body": "导体对电流的阻碍作用用电阻描述，电阻符号R，单位欧姆Ω。一定温度下，导体电阻与材料、长度和横截面积有关：同种材料、相同粗细时，越长电阻越大；同种材料、相同长度时，越粗电阻越小。探究必须一次只改变一个因素。电阻也常受温度影响，金属灯丝发热后电阻通常增大，所以灯泡不是处处电阻恒定的元件。导体两端没有电压、没有电流，并不表示电阻消失；用R=U/I计算是在测定该状态下的电阻，不能把商式误读成因果关系。"}, {"title": "16.4 变阻器", "body": "滑动变阻器通过改变接入电路的电阻丝长度来改变电阻，常用于调节电流和保护电路。正确使用通常选择一个上接线柱和一个下接线柱，实际接入部分是滑片与所选下接线柱之间的电阻丝。判断电阻增减先标出该段，再看滑片移动后长度改变，不能死记“向左增大”。若只接两个下接线柱，相当于接入整段定值电阻；只接两个上接线柱时接入电阻通常很小。闭合前将有效接入电阻调到最大，并检查允许通过的最大电流，不能超过铭牌限值。"}], "formulas": [{"text": "串联：U总=U₁+U₂+…", "note": "各分电压与总电压必须对应同一条串联路径。"}, {"text": "并联：U总=U₁=U₂=…", "note": "支路跨接同一对结点，忽略导线电阻。"}, {"text": "1kΩ=1000Ω；1MΩ=10⁶Ω", "note": "电阻是导体自身的性质，通常还要说明温度。"}], "examples": [{"question": "两个电阻串联接在6.0V电源两端，其中一个两端电压2.4V，另一个是多少？", "steps": ["串联总电压等于各部分电压之和。", "U₂=6.0−2.4V。"], "answer": "3.6V。"}, {"question": "滑动变阻器选左下接线柱与任一上接线柱。滑片向右移动，接入电阻怎样改变？", "steps": ["有效电阻丝位于左下接线柱与滑片之间。", "滑片向右时这段电阻丝变长。"], "answer": "电阻增大；接入其他条件不变的串联电路时，电流通常减小。"}], "activity": {"title": "测出“相加”和“相等”", "materials": "3V电池盒、20Ω与30Ω且额定功率不低于1W的电阻、开关、电压表、导线。", "steps": ["断开开关，将两个电阻串联，请教师检查连接和量程。", "依次测电源、每个电阻两端电压并记录，比较U总与U₁+U₂。", "断开后改为并联，测两支路两端电压。", "画出两套电路，圈出各次测量的一对结点，解释读数关系。"], "recordHeaders": ["连接方式", "U总/V", "U₁/V", "U₂/V", "关系"], "conclusion": "串联各部分电压相加得到总电压；并联支路电压相等。电阻不同可避免误以为串联总是平均分压。", "safety": "只用3V电源；换线前断开。电阻可能温热，通电仅用于读数；禁止短路和接入家庭插座。"}, "mistakes": ["“有电压必有电流”错误：断路两端可有电压，但没有持续电流。", "“电阻由U/I决定，电压越大电阻越大”错误：对定温欧姆导体，电阻由材料和几何等条件决定。", "“滑片向右一定使电阻增大”错误：要看使用哪个下接线柱。"], "quiz": [{"type": "choice", "question": "电压表应怎样接入被测灯泡电路？", "options": ["与灯泡串联", "与灯泡并联", "直接代替开关导线", "任意连接"], "answer": 1, "explanation": "电压测量的是元件两端的电势差，要并联接入。"}, {"type": "choice", "question": "两个不同电阻并联在3V电池两端，各电阻两端电压为？", "options": ["均为1.5V", "分别为1V和2V", "均为3V", "由电阻大小决定，无法判断"], "answer": 2, "explanation": "并联元件连接在同一对结点之间，电压相等。"}, {"type": "choice", "question": "同种材料、相同温度和长度的两根导线，哪根电阻较小？", "options": ["横截面积较大的", "横截面积较小的", "一定相同", "只有通电才能判断"], "answer": 0, "explanation": "其余条件相同时，导线越粗电阻越小。"}, {"type": "choice", "question": "滑动变阻器只使用两个下接线柱，移动滑片后接入电阻通常怎样？", "options": ["连续变小", "连续变大", "先大后小", "保持整段电阻丝的电阻不变"], "answer": 3, "explanation": "两个下接线柱跨接整段电阻丝，滑片位置不改变这段长度。"}, {"type": "short", "question": "三段电阻串联，总电压9V。前两段电压分别是2V与3V，第三段为多少？", "answer": "4V。", "explanation": "U₃=U总−U₁−U₂=9−2−3=4V。", "rubric": ["写出串联总电压关系。", "计算4V并标单位。"]}, {"type": "short", "question": "要探究导体电阻与长度的关系，应选择怎样的两根导线？还要控制什么条件？", "answer": "材料、横截面积相同而长度不同的两根导线，并尽量保持温度相同。", "explanation": "控制变量法要求只改变所研究的长度；材料、粗细和温度都会影响电阻。", "rubric": ["指出同材料、同横截面积而长度不同。", "指出控制温度相同。"]}], "sim": "circuit", "tags": ["电压", "电压表", "电阻", "控制变量", "滑动变阻器"]}, {"id": "physics-17", "subject": "physics", "chapter": "第十七章", "title": "欧姆定律", "term": "全一册", "category": "同步", "intro": "电流、电压和电阻怎样共同决定电路状态？让测量数据变成可预测的规律。", "periods": "6—7课时（建议）", "goals": ["以控制变量实验说明电流与电压、电阻的关系", "用欧姆定律处理同一元件同一状态的U、I、R", "设计伏安法测电阻并分析简单串并联电路"], "sections": [{"title": "17.1 电流与电压和电阻的关系", "body": "探究电流与电压关系时，应选定一个电阻并尽量保持温度不变，用滑动变阻器调节其两端电压，记录多组U和I。图像若为过原点的直线，说明电阻一定时电流与电压成正比。探究电流与电阻关系时，要更换不同电阻，并用变阻器把每次被测电阻两端的电压调回同一数值；数据表明电压一定时电流与电阻成反比。不能只替换电阻而任由电压变化。研究范围必须保证元件不过热、不过载，灯丝明显变温时其U-I图像可能不再是直线。"}, {"title": "17.2 欧姆定律", "body": "对于适用欧姆定律的导体，通过它的电流等于它两端电压与其电阻的比值，即I=U/R。使用时，三个量必须属于同一元件或同一段电路，并对应同一时刻的工作状态。电压用V、电阻用Ω，得到的电流才是A。变形式U=IR、R=U/I方便求未知量，但不能说电阻随电压增大而必然增大。若电路接法或滑片位置变化，应分别画出变化前后的有效电路，再确定保持不变的是电源电压、定值电阻还是其他条件，避免把不同状态的量混用。"}, {"title": "17.3 电阻的测量", "body": "伏安法测电阻用电压表并联测被测电阻两端电压，用电流表串联测通过它的电流，然后计算R=U/I。接线时断开开关，变阻器先调到最大有效电阻，经检查后短时闭合。测定近似定值电阻时，改变电压获得几组数据，分别算电阻，再求平均值可减小随机误差。小灯泡灯丝温度随电压明显改变，得到的是不同工作状态下的电阻，不能不加说明地把这些数平均成“固定电阻”。记录异常数据应查接线、量程和发热原因，不能为了符合结论随意修改读数。"}, {"title": "17.4 欧姆定律在串、并联电路中的应用", "body": "串联电路电流相等，结合U=IR可得总电阻等于各电阻之和，电阻越大的部分分得电压越大。并联电路电压相等，支路电流I=U/R，电阻越小的支路电流越大；两电阻并联满足1/R总=1/R₁+1/R₂，总电阻小于任一支路电阻。分析变阻器电路时先排除被短接或断开的部分，再写串并联关系。理想电源电压不变时，增加并联支路会使总电阻减小、总电流增大，但原有定值电阻支路两端电压和支路电流可以保持不变。"}], "formulas": [{"text": "I=U/R；U=IR；R=U/I", "note": "适用于欧姆导体；同一段电路、同一状态，单位A、V、Ω。"}, {"text": "R串=R₁+R₂；U₁/U₂=R₁/R₂", "note": "串联分压；各电阻中电流相同。"}, {"text": "1/R并=1/R₁+1/R₂；I₁/I₂=R₂/R₁", "note": "并联分流；各支路电压相同。两电阻时R并=R₁R₂/(R₁+R₂)。"}], "examples": [{"question": "10Ω和20Ω电阻串联接在6V电源两端，求电流及两电阻电压。", "steps": ["R总=10+20=30Ω，I=6/30=0.20A。", "U₁=0.20×10=2V，U₂=0.20×20=4V。"], "answer": "电流0.20A，电压分别2V、4V。"}, {"question": "6Ω与3Ω电阻并联接在3V电源两端，求干路电流与总电阻。", "steps": ["I₁=3/6=0.50A，I₂=3/3=1.0A。", "I总=0.50+1.0=1.5A，R总=3/1.5=2Ω。"], "answer": "干路电流1.5A，总电阻2Ω；这是计算模型，实验需另行核定元件功率和电源限流。"}], "activity": {"title": "三组数据测一个电阻", "materials": "带限流的0—3V教学电源或3V电池盒、20Ω/1W电阻、合适变阻器、开关、电压表、电流表、导线。", "steps": ["断开开关，电流表串联、电压表并联；变阻器置最大有效电阻。", "经教师检查后，将电阻两端电压依次调为1.0V、1.5V、2.0V，分别读电流。", "计算三次R=U/I，并比较是否近似相等。", "求平均值，列举读数、接触和温升可能造成的偏差。"], "recordHeaders": ["次数", "电压U/V", "电流I/A", "电阻R/Ω", "偏差观察"], "conclusion": "在温度变化不大时，同一电阻的U/I应近似不变；多次测量帮助评估可靠性。", "safety": "只用不超过3V且适当限流的教学电源；换线前断开，电表量程与电阻、变阻器功率及电流限值均须教师核对。"}, "mistakes": ["“电流与电压成正比”要补条件：被研究的电阻保持不变。", "“更换电阻后直接读电流”不完整：探究I与R关系时应把该电阻两端电压调回原值。", "“并联总电阻大于支路电阻”错误：并联增加了导电路径，总电阻比任一支路都小。"], "quiz": [{"type": "choice", "question": "一个10Ω定值电阻两端电压为2V，电流是多少？", "options": ["0.20A", "5A", "20A", "0.02A"], "answer": 0, "explanation": "I=U/R=2/10=0.20A。"}, {"type": "choice", "question": "探究电流与电阻关系时，必须保持哪一个量相同？", "options": ["电源中电荷总数", "滑片位置", "被测电阻两端电压", "每次电流"], "answer": 2, "explanation": "要控制被测电阻两端电压相同，电流才只随电阻改变。"}, {"type": "choice", "question": "4Ω与6Ω串联，总电阻是多少？", "options": ["2.4Ω", "10Ω", "24Ω", "2Ω"], "answer": 1, "explanation": "串联总电阻为4+6=10Ω。"}, {"type": "choice", "question": "两个均为12Ω的电阻并联，总电阻为？", "options": ["24Ω", "12Ω", "0Ω", "6Ω"], "answer": 3, "explanation": "相同两电阻并联，总电阻为一个电阻的一半。"}, {"type": "short", "question": "某电阻三次测量为(1.0V,0.10A)、(1.5V,0.15A)、(2.0V,0.20A)。求电阻，并说明数据支持什么关系。", "answer": "电阻均为10Ω；在实验温度变化可忽略时，电流与电压成正比。", "explanation": "三次U/I分别为10Ω，商不变，对应I=U/10。", "rubric": ["算出每次电阻10Ω。", "写出电阻一定的前提和正比关系。"]}, {"type": "short", "question": "8Ω与12Ω电阻并联在6V理想电源上，求两支路电流及干路电流。", "answer": "分别为0.75A、0.50A，干路为1.25A。", "explanation": "并联各支路电压6V，分别用I=U/R，再将电流相加。", "rubric": ["两支路各用6V计算且数值正确。", "干路电流求和为1.25A。"]}], "sim": "ohm", "tags": ["欧姆定律", "伏安法", "分压", "分流", "动态电路"]}, {"id": "physics-18", "subject": "physics", "chapter": "第十八章", "title": "电功率", "term": "全一册", "category": "同步", "intro": "“一天用了几度电”和“这台电器多少瓦”有什么不同？学会评价用电多少和转化快慢。", "periods": "6—7课时（建议）", "goals": ["区分电能、电功率并正确换算kW·h与J", "通过电压、电流求实际功率并区分额定值", "用焦耳定律分析电热与节能问题"], "sections": [{"title": "18.1 电能 电功", "body": "电流做功的过程就是电能转化为其他形式能量的过程。电动机把电能转为机械能和内能，灯把电能转为光能和内能。电能表记录用电器消耗的电能，先后两次示数之差是这段时间的用电量，常用单位kW·h，也叫“度”；1kW·h=3.6×10⁶J。电压和电流恒定时，电功W=UIt，若使用V、A、s，结果为J。读取带小数位的电能表示数时要保留其实际含义。W在公式中可代表功，而W作为单位符号代表瓦特，两者要根据上下文区分。"}, {"title": "18.2 电功率", "body": "电功率表示电流做功、即电能转化的快慢，P=W/t=UI，单位瓦特，1kW=1000W。消耗电能多少同时取决于功率与使用时间，所以大功率电器短时工作未必比小功率电器长时工作更费电。额定电压是正常工作所规定的电压，额定功率是在额定条件下的功率；实际功率由实际工作状态决定。对电阻近似不变的纯电阻元件，可用P=U²/R或P=I²R。真实白炽灯电阻随温度变化，不能无条件把额定电阻当成所有状态下不变的电阻。"}, {"title": "18.3 测量小灯泡的电功率", "body": "测小灯泡功率时，电流表串联测电流，电压表并联测灯泡电压，用滑动变阻器调节工作电压。先核对灯泡额定电压、仪表量程和电源，再从较低电压开始测量；当电压恰等于额定值时，用此时U与I的乘积求额定功率。还可比较较低电压下的亮度与实际功率，但不应为观察更亮而随意超压。灯丝温度变化会改变电阻，因此多组数据得到的是多个工作状态的功率，不能取平均值称为灯的“额定功率”。记录应把电压、电流、亮度和状态一一对应。"}, {"title": "18.4 焦耳定律", "body": "电流通过导体产生热量，与电流的平方、导体电阻和通电时间成正比，即Q=I²Rt；公式使用恒定或近似恒定的电流、电阻。探究时可用串联控制电流相同、用并联等方法按设计控制其他变量，但真实实验必须核对元件安全额定值。电热器利用电流热效应，导线和电动机线圈发热则常是应减少的损耗。纯电阻电路中电功全部转为内能，可写Q=W=UIt；电动机等同时输出机械能时，不能把全部电能都当成电热。电流加倍、其余不变时，发热量变为四倍。"}], "formulas": [{"text": "W=UIt=Pt；1kW·h=3.6×10⁶J", "note": "U、I恒定；P用kW、t用h时W为kW·h。"}, {"text": "P=UI；P=U²/R=I²R", "note": "后两个变形式用于满足欧姆关系的电阻元件。"}, {"text": "Q=I²Rt", "note": "I用A、R用Ω、t用s时，Q为J；不把电动机输入电能全部等同于电热。"}], "examples": [{"question": "一台40W电风扇每天工作5h，连续30天共耗电多少度？", "steps": ["功率40W=0.040kW，总时间5×30=150h。", "W=Pt=0.040×150kW·h。"], "answer": "6.0kW·h，即6度。"}, {"question": "某灯额定电压2.5V，正常工作时电流0.30A。求额定功率与正常工作100s消耗的电能。", "steps": ["P额=UI=2.5×0.30=0.75W。", "W=Pt=0.75×100J。"], "answer": "额定功率0.75W，电能75J。"}, {"question": "10Ω电阻中电流为0.20A，通电60s，产生多少热量？", "steps": ["用Q=I²Rt，先将电流平方。", "Q=0.20²×10×60J。"], "answer": "24J。"}], "activity": {"title": "给教室制定照明节电建议", "materials": "灯具铭牌照片或教师给定功率资料、使用时长记录表、计算器。", "steps": ["只阅读铭牌照片，记录灯具数量与实际功率资料；若仅有额定值，标记为估算。", "以一周为周期记录照明时间，计算总电能。", "设计利用自然光、无人关闭等方案，估算减少的时长和电能。", "说明采光、学习舒适度和管理条件，提出可执行建议。"], "recordHeaders": ["灯具数", "单灯功率/W", "每日时长/h", "周电能/kW·h", "预计节电量"], "conclusion": "估算电能=总功率×使用时间；合理减少不必要使用时间，可以在保证照明需求的前提下节电。", "safety": "仅做观察、照片阅读和计算，不拆灯具、不触碰插座与导线；调灯、检修交由有资质人员。"}, "mistakes": ["“功率大一定更耗电”不完整：还要比较使用时间。", "“kW是电能单位”错误：kW是功率，kW·h才是电能。", "“电动机的发热量等于UIt”错误：电动机还有机械能输出，电热通常只占输入电能的一部分。"], "quiz": [{"type": "choice", "question": "1度电等于多少电能？", "options": ["1000J", "3600J", "3.6×10⁶J", "1W"], "answer": 2, "explanation": "1度=1kW·h=1000W×3600s=3.6×10⁶J。"}, {"type": "choice", "question": "一只5W台灯工作4h，消耗电能为？", "options": ["0.020kW·h", "20kW·h", "1.25kW·h", "0.00125kW·h"], "answer": 0, "explanation": "5W=0.005kW，W=0.005×4=0.020kW·h。"}, {"type": "choice", "question": "某电阻I、R近似恒定，电流增至原来的2倍、时间不变，热量变为原来的？", "options": ["2倍", "4倍", "一半", "不变"], "answer": 1, "explanation": "焦耳定律中热量与电流平方成正比。"}, {"type": "choice", "question": "测得灯泡U=2V、I=0.25A，实际功率是？", "options": ["8W", "0.125W", "2.25W", "0.50W"], "answer": 3, "explanation": "P=UI=2×0.25=0.50W。"}, {"type": "short", "question": "100W电器工作2h和25W电器工作10h，哪个耗电多？分别算出用电量。", "answer": "分别为0.20kW·h和0.25kW·h；25W电器耗电更多。", "explanation": "电能由功率和时间共同决定，功率换成kW后分别乘使用小时数。", "rubric": ["两个电能计算及单位正确。", "明确25W电器更多，并联系工作时间解释。"]}, {"type": "short", "question": "一个5Ω电阻通过0.40A电流，持续30s，产生多少热量？若电流减半，时间不变，热量多少？", "answer": "原来24J，减半电流后6J。", "explanation": "Q=0.40²×5×30=24J；电流减半，平方变为原来的1/4，故6J。", "rubric": ["原热量24J计算正确。", "解释平方关系，得6J。"]}], "sim": "power", "tags": ["电能", "电功率", "额定功率", "焦耳定律", "节电"]}, {"id": "physics-19", "subject": "physics", "chapter": "第十九章", "title": "生活用电", "term": "全一册", "category": "同步", "intro": "为什么不能在一块插线板上随意叠加大功率电器？把电路知识变成安全判断。", "periods": "3—4课时（建议）", "goals": ["在示意图中辨认家庭电路的控制与保护功能", "用简化功率模型解释过载和短路的区别", "判断常见危险行为并给出安全替代行动"], "sections": [{"title": "19.1 家庭电路", "body": "家庭电路包含进户线、电能表、控制开关、保护装置、插座和用电器等。我国常见家庭单相供电的标称电压为220V，各用电器通常并联，以便分别使用。控制某用电器的单极开关应接在其火线一侧，使断开时用电器与火线脱离；零线与保护接地线功能不同，不能混接或随意替代。需要保护接地的金属外壳电器应保持接地可靠，漏电保护装置也不能替代所有安全措施。课堂学习只分析示意图，实际布线、验电、安装和维修必须由有资质人员完成。"}, {"title": "19.2 家庭电路中电流过大的原因", "body": "在简化的纯电阻模型中，电压一定时总功率越大，总电流越大，多台大功率电器同时工作可能造成过载。短路则是低电阻路径绕过正常负载，使电流异常增大；它与正常负载过多的原因不同。过大电流会使导线发热增多，损伤绝缘并可能引发火灾。熔断器或断路器按规定条件切断故障电路，其规格要与线路和负载协调，不能用铜丝、铁丝替代保险丝，也不能见跳闸就盲目增大额定值。读到额定值只是判断的必要信息，不意味着连接完好、散热合格等条件都已满足。"}, {"title": "19.3 安全用电", "body": "触电危险与通过人体的电流及作用时间、路径、环境等有关，不能只凭电压数值作绝对安全判断。保持手和环境干燥，不触碰裸露带电部分，不使用破损电线，不私拆或改装电器；发现焦味、冒烟、打火或反复跳闸，应停止使用并请专业人员处理。发现有人疑似触电时，先保障自己安全，不徒手拉人；及时呼叫成人和120，由能够安全操作的人员切断电源。电气起火要远离危险并报警119，未确认断电不能用水扑救。高压设施附近应遵守警戒与距离要求，不能靠近试探。"}], "formulas": [{"text": "I总=P总/U（简化纯电阻模型）", "note": "本章计算题假设电器为纯电阻或已给出适用模型；实际交流设备还可能涉及功率因数。"}, {"text": "P总=P₁+P₂+…", "note": "只统计同一时刻工作的设备；不能忽略插线板、插座与线路各自限制。"}, {"text": "Q=I²Rt", "note": "电流增大会显著增加导线发热；实际危险还与接触、散热和绝缘状况有关。"}], "examples": [{"question": "纸上模型中，220V插线板标示10A，接入1500W和1000W两个纯电阻电器同时工作，电流约多大？", "steps": ["P总=1500+1000=2500W。", "I总=2500/220≈11.36A，与10A比较。"], "answer": "约11.36A，超过给定额定电流，不能这样同时使用。"}, {"question": "某简化家庭支路接有880W、660W两个纯电阻负载，电压220V。求总电流；能否只据此断言线路安全？", "steps": ["P总=880+660=1540W。", "I总=1540/220=7A；还要核查各处额定值、连接和绝缘等。"], "answer": "总电流7A；不能仅凭这个数值断言安全。"}], "activity": {"title": "为一个房间画安全用电概念图", "materials": "纸笔、教师提供的房间平面草图、用电器功率卡、保护装置示意卡。", "steps": ["把照明与不同用电器画成并联支路，并标出控制灯的开关。", "在概念图中标注火线、零线、保护接地线的不同功能。", "列出可能同时工作的电器，在题设简化模型下估算总电流。", "互评“湿手操作、破损导线、超额负载、私改保护装置”等情境，写出安全行动。"], "recordHeaders": ["情境", "电器总功率/W", "模型电流/A", "潜在问题", "正确行动"], "conclusion": "家庭用电要同时考虑正确连接、负载限制、可靠保护和使用行为；课堂概念图不是可直接施工的布线图。", "safety": "全程纸上设计或网页模拟，不接家庭电源，不拆插座、电器或配电箱，不用试电笔对市电进行学生操作。"}, "mistakes": ["“零线和地线可以互换”错误：功能不同，不得混接。", "“保险丝越粗越好”错误：保护器件须与线路相匹配，擅自加粗会破坏保护。", "“没超过总功率就绝对安全”错误：还需考虑接触不良、破损、潮湿、散热和其他额定限制。"], "quiz": [{"type": "choice", "question": "家庭中各用电器通常采取哪种连接？", "options": ["全部串联", "全部短路连接", "并联", "不需要完整回路"], "answer": 2, "explanation": "并联使各用电器可分别获得供电并独立使用。"}, {"type": "choice", "question": "控制灯泡的单极开关应接在？", "options": ["灯泡的火线一侧", "保护地线中", "任意一根导线都完全等效", "火线与零线之间直接相接"], "answer": 0, "explanation": "接在火线一侧可在断开时切断灯泡与火线的连接，实际维修仍须专业断电确认。"}, {"type": "choice", "question": "下列行为哪一个正确？", "options": ["湿手插拔电器", "跳闸后不断强行合闸", "用铜丝替代保险丝", "发现插座冒烟后远离危险并通知成人处理"], "answer": 3, "explanation": "冒烟表示可能存在故障，不应继续使用或自行拆修。"}, {"type": "choice", "question": "220V的简化纯电阻支路同时使用1100W和660W电器，总电流为？", "options": ["5A", "8A", "3A", "0.125A"], "answer": 1, "explanation": "I=(1100+660)/220=8A。"}, {"type": "short", "question": "说明“过载”和“短路”各是什么，并说出它们共有的一种危害。", "answer": "过载是正常负载总电流超过允许值；短路是异常低电阻路径绕过负载。两者都可能造成过大电流，引发导线过热。", "explanation": "两者成因不同，但电流增大都会使导线热效应增强。", "rubric": ["分别说明两种故障的不同成因。", "指出过热或绝缘损坏、火灾等共同危害。"]}, {"type": "short", "question": "同学看到疑似触电者，准备徒手拉开。请指出问题并给出优先行动。", "answer": "徒手拉人可能使自己触电。应先确保自身安全，不接触触电者或带电物，呼叫成人并拨打120，由能安全操作的人切断电源。", "explanation": "先防止二次伤害，再组织断电和专业救援；不能把课堂知识当作带电救援操作资格。", "rubric": ["明确禁止直接徒手拉人。", "说明安全断电、呼救和拨打120的优先原则。"]}], "sim": "safety", "tags": ["家庭电路", "过载", "短路", "安全用电", "保护接地"]}, {"id": "physics-20", "subject": "physics", "chapter": "第二十章", "title": "电与磁", "term": "全一册", "category": "同步", "intro": "电怎样产生磁，磁又怎样产生电？比较电动机与发电机，建立两种能量转化模型。", "periods": "7—8课时（建议）", "goals": ["用磁感线和小磁针描述磁场方向", "运用安培定则并解释电磁铁、继电器原理", "区分通电导体受力与电磁感应，辨认电动机和发电机"], "sections": [{"title": "20.1 磁现象 磁场", "body": "磁体能吸引铁、钴、镍等材料，磁性最强的区域称磁极，自由转动的小磁针静止时指北的一端标N、指南的一端标S。同名磁极相斥、异名磁极相吸。磁体周围存在磁场，磁场方向规定为小磁针N极在该点所指方向。磁感线是帮助表示磁场的模型，实际并不存在一根根可见线；磁体外部从N极指向S极，线较密处通常表示磁场较强。地球也有磁场，但地理两极与地磁两极并不完全重合，不能简单认为地理北极就是条形磁体的N极。"}, {"title": "20.2 电生磁", "body": "通电导线周围存在磁场，这是电流的磁效应。改变电流方向，磁场方向也随之改变；线圈绕成螺线管后，磁场形状与条形磁体相似。用安培定则判断通电螺线管磁极：右手四指沿管上电流方向弯曲，拇指指向螺线管N极。电流方向采用正电荷定向移动的规定方向，不能直接当成电子移动方向。看图时要先辨线圈前后走向，再用手势判断。未通电的小磁针本身可作探测工具，其偏转说明局部磁场合成方向改变，并不是电流把磁针直接“推走”。"}, {"title": "20.3 电磁铁 电磁继电器", "body": "带铁芯的通电螺线管常用作电磁铁，通断电可以控制磁性的有无，改变电流方向可改变磁极。其他条件相同时，电流越大、线圈匝数越多，磁性通常越强；比较匝数时要控制电流相同。电磁继电器利用电磁铁吸引衔铁，从而带动触点，使控制电路决定另一个工作电路的通断。课堂用低压模型理解“控制与工作回路分开”，不代表学生可以接入高压负载。实际电磁铁必须遵守额定电流和通电时间限制，线圈过热会损坏绝缘。"}, {"title": "20.4 电动机", "body": "通电导体在磁场中会受到力，力的方向与电流方向、磁场方向有关；只改变其中一个方向，受力方向反转，同时改变两者则受力方向可保持不变。把线圈放入磁场，适当布置后两边受力形成转动效果，把电能转化为机械能。简易直流电动机用换向器等装置在适当时刻改变线圈电流方向，使转动连续；没有恰当换向，线圈可能停在平衡位置。电动机工作时也发热，电能输入不会全部成为机械能。学习重点是辨认“先通电、再受磁场力”的因果顺序。"}, {"title": "20.5 磁生电", "body": "闭合电路的一部分导体在磁场中做切割磁感线运动时，电路中可产生感应电流，这是电磁感应。仅仅有磁场、仅仅导体静止在磁场中，通常不足以在该模型中产生持续电流；导体沿磁感线运动时也未形成相应切割。电流方向与运动方向和磁场方向有关，改变其中一个可改变感应电流方向。发电机把机械能转化为电能，转动线圈或磁体可持续改变相对关系。感应并非无中生有，维持发电需要机械功输入，理想化图示还忽略了电阻发热等实际损耗。"}], "formulas": [{"text": "电动机：电能 → 机械能 + 内能等", "note": "原理为通电导体在磁场中受力；直流模型需适当换向。"}, {"text": "发电机：机械能 → 电能 + 内能等", "note": "原理为电磁感应；需要能量输入。"}, {"text": "安培定则：四指沿电流，拇指指N极", "note": "适用于通电螺线管磁极判断，先确定绕线前后关系。"}], "examples": [{"question": "某线圈在磁场中通电后向左受力，只把电源正负极对调，运动趋势如何？若又同时把磁场反向呢？", "steps": ["只反接电源使电流方向反转，磁场不变，受力反向。", "电流和磁场都反向时，两种反向作用共同使受力方向回到原方向。"], "answer": "只反接电源时向右；电流与磁场同时反向时仍向左。"}, {"question": "某发电模型输入机械能200J，输出电能150J。求转换效率，并说明剩余能量。", "steps": ["η=150/200×100%=75%。", "能量差为200−150=50J，可能转为装置及环境内能、声音等。"], "answer": "效率75%；其余50J未消失，而是形成其他输出或装置储能变化。"}], "activity": {"title": "给看不见的磁场画地图", "materials": "条形磁铁、小指南针、白纸、铅笔；磁铁由教师保管。", "steps": ["在纸上标出磁铁轮廓和N、S极，移去附近明显磁性物体。", "把指南针放在磁铁周围不同位置，记录N极所指方向。", "在8—12个位置画小箭头，顺着箭头描出几条方向曲线。", "旋转磁铁重新观察，区分磁场变化与指南针自身响应。"], "recordHeaders": ["位置编号", "距磁铁位置", "N极指向", "箭头方向", "重复观察"], "conclusion": "磁铁外部磁场方向可由小磁针N极指向描绘；磁感线是根据测量建立的模型。", "safety": "不吞咽小磁铁，避免夹手；远离磁卡和对磁场敏感设备。活动无需通电，不接市电，不用铁屑飞散演示。"}, "mistakes": ["“磁感线是真实细线”错误：它是描述方向与强弱的模型。", "“电动机与发电机原理一样”错误：前者主要用磁场对电流的力，后者用电磁感应。", "“导体在磁场中任意运动都产生电流”错误：本节模型还要求闭合回路和有效切割等条件。"], "quiz": [{"type": "choice", "question": "磁场方向规定为小磁针哪一端的指向？", "options": ["N极", "S极", "中点", "任意端"], "answer": 0, "explanation": "某点磁场方向由小磁针N极在该点所指方向定义。"}, {"type": "choice", "question": "关于电磁铁，其他条件相同且在额定范围内，哪项通常能增强磁性？", "options": ["减小电流", "增大电流", "去掉所有线圈", "断开电源"], "answer": 1, "explanation": "在规定工作范围内，电流增大通常使磁场增强。"}, {"type": "choice", "question": "电动机主要把什么能量转成机械能？", "options": ["太阳辐射能", "核能", "电能", "只有化学能"], "answer": 2, "explanation": "电动机从电路获得电能，部分转为机械能。"}, {"type": "choice", "question": "下列哪项符合本节产生感应电流的条件？", "options": ["导体静止放在磁场中", "断开的导线沿磁感线静止", "任何金属随意摆放", "闭合电路的一部分导体做切割磁感线运动"], "answer": 3, "explanation": "闭合回路与有效切割是该简单实验模型的必要条件。"}, {"type": "short", "question": "比较不同匝数电磁铁强弱，为什么不能只把两个线圈接到相同电压电源就下结论？", "answer": "匝数不同可能使线圈电阻不同，同电压下电流未必相等，应测量并控制电流相同。", "explanation": "磁性强弱同时受匝数与电流影响，若两者同时变化就无法单独判断匝数作用。", "rubric": ["说明线圈电阻与电流可能不同。", "提出控制电流相同的实验改进。"]}, {"type": "short", "question": "一台电动模型吸收100J电能，对外输出70J机械能。求效率并判断是否违反能量守恒。", "answer": "效率70%，不违反能量守恒。", "explanation": "η=70/100=70%，其余30J可成为内能等其他形式，计入全部输出后守恒。", "rubric": ["效率计算70%。", "解释其余能量去向而非消失。"]}], "sim": "magnet", "tags": ["磁场", "安培定则", "电磁铁", "继电器", "电动机", "电磁感应"]}, {"id": "physics-21", "subject": "physics", "chapter": "第二十一章", "title": "信息的传递", "term": "全一册", "category": "同步", "intro": "你说出的一句话怎样到达远方？沿“信息—信号—载体—接收”追踪通信全过程。", "periods": "4—5课时（建议）", "goals": ["辨认声音信号与电信号之间的转化", "用波速、频率、波长关系作简单计算", "比较广播、移动、卫星和光纤通信的基本过程"], "sections": [{"title": "21.1 现代顺风耳——电话", "body": "通信要把原始信息变为适合传输的信号。传统电话的话筒把声音引起的振动转变为相应电信号，信号沿线路传到接收端，再由听筒转为声音；电话交换系统负责建立用户间的连接。现代通信常把连续变化的声音采样、编码成数字信号，接收端再重建声音。数字信号并不意味着“没有物理载体”，仍需电压、电磁波或光等物理过程承载。把声波在空气中传播与电信号沿线路传输区分开，才能解释远距离电话不是把原来的空气振动一路送到另一端。"}, {"title": "21.2 电磁波的海洋", "body": "电磁波可以在真空中传播，光也是电磁波；声波则需要介质，所以宇航员之间不能靠真空直接传声。电磁波在真空中的传播速度约为3.0×10⁸m/s，频率f表示每秒振动次数，单位Hz，波长λ表示相邻同相位波峰等的空间间距。它们满足c=λf；在同一介质、波速可视为相同时，频率越高，波长越短。无线电波、微波、红外线、可见光等属于不同频段，不能把所有电磁波都当成可见光，也不能凭“有辐射”三个字判断其具体作用和风险。"}, {"title": "21.3 广播、电视和移动通信", "body": "广播发射端把声音信息转换成电信号，并使它附着在适于远传的电磁波上；接收机选择相应信号并恢复声音。电视还要传递图像信息，移动通信则需要手机与网络之间双向交换信息，基站承担无线接入等功能。手机不是永远直接与另一部手机远距离通话，也不是一般通话都直接经过卫星。通信质量受到覆盖、障碍物、干扰、网络负载等多因素影响。频率、发射功率和数字编码属于不同概念，不能单凭“频率高”就断言传播距离更远或网速必然更快。"}, {"title": "21.4 越来越宽的信息之路", "body": "微波通信常借助中继站克服直线传播与地形、地球曲率的限制，卫星可承担远距离中继；信号往返路径长会带来不可忽略的传播延迟。光纤利用光在介质中的传播和导光结构传递信息，能承载大量数据，但还需要发射、接收与网络设备配合。互联网把许多网络连接起来，信息可被分成数据包，经不同节点转发到目的地。比较方案时，应同时考虑覆盖范围、容量、延迟、成本与可靠性，而不是只比较一个速度值；光纤中的传播速度也不直接等于信息服务的实际下载速度。"}], "formulas": [{"text": "c=λf；c≈3.0×10⁸m/s", "note": "真空中电磁波；λ用m，f用Hz。其他介质用相应波速v。"}, {"text": "s=vt；t=s/v", "note": "距离是信号实际走过的总路径，单程与往返不要混淆。"}, {"text": "1MHz=10⁶Hz；1GHz=10⁹Hz", "note": "频率不是传播速度，也不是直接的下载速率。"}], "examples": [{"question": "某无线电波在真空中频率为100MHz，波长是多少？", "steps": ["f=100×10⁶Hz=1.0×10⁸Hz。", "λ=c/f=3.0×10⁸/(1.0×10⁸)m。"], "answer": "3.0m。"}, {"question": "信号沿近似直线从地面到距其36000km的卫星，再返回另一地面站，两段路程均取36000km。忽略设备处理，至少约需多久？", "steps": ["总路程s=72000km=7.2×10⁷m。", "t=s/c=7.2×10⁷/(3.0×10⁸)s。"], "answer": "约0.24s；是真空波速近似下两段传播时间，不含其他网络延迟。"}], "activity": {"title": "给一条消息选择传输路径", "materials": "纸卡、纸笔、计时器；卡片代表手机、基站、交换节点、卫星和光纤节点。", "steps": ["一组将一句短信息编码为编号纸卡，另一组按约定解码。", "分别设计近距离移动网络路径和带卫星中继的路径。", "给每条边标注假设距离与固定处理时间，计算端到端延迟。", "删除一个中间节点，讨论重路由、冗余和丢包重传会带来什么变化。"], "recordHeaders": ["方案", "路径总长/km", "传播时间/ms", "处理等待/ms", "总延迟/ms"], "conclusion": "消息必须由信号承载并通过具体路径传送；端到端延迟包括传播、处理和等待，不能只看波速。", "safety": "纸卡模拟不产生真实无线发射；不拆手机、微波炉或路由器，不使用激光照眼或拆看光纤端口。"}, "mistakes": ["“声波和电磁波都能在真空传播”错误：声波需要介质。", "“频率越高，真空中传播速度越大”错误：真空中电磁波传播速度相同，改变的是波长。", "“手机通话一定直接连卫星”错误：常规移动通信通常先通过地面基站和网络。"], "quiz": [{"type": "choice", "question": "哪一种波能够在真空中传播？", "options": ["水波", "空气中的声波", "绳波", "电磁波"], "answer": 3, "explanation": "电磁波无需物质介质，声波和机械波需要介质。"}, {"type": "choice", "question": "真空中电磁波频率变为原来的2倍，波长如何变化？", "options": ["变为2倍", "变为一半", "保持不变", "变为4倍"], "answer": 1, "explanation": "c不变，由λ=c/f，频率加倍则波长减半。"}, {"type": "choice", "question": "话筒的基本作用是？", "options": ["把声音信息转换成电信号", "把电能完全变成核能", "让空气穿过电线", "只放大图像"], "answer": 0, "explanation": "话筒将声振动转化为相应的电信号。"}, {"type": "choice", "question": "某电磁波频率为2.0GHz，在真空中波长约为？", "options": ["1.5m", "150m", "0.15m", "0.015m"], "answer": 2, "explanation": "λ=3.0×10⁸/(2.0×10⁹)=0.15m。"}, {"type": "short", "question": "无线信号在真空近似条件下传播600km，忽略处理时间，需多少毫秒？", "answer": "2.0ms。", "explanation": "s=6.0×10⁵m，t=s/c=0.002s=2.0ms。", "rubric": ["把600km换为6.0×10⁵m。", "传播时间与秒到毫秒换算正确。"]}, {"type": "short", "question": "有人说“光纤里的光传播得快，所以视频永远不会卡顿”。指出至少两项没有考虑的因素。", "answer": "还要考虑网络可用带宽和拥塞、节点处理与排队、服务器供给、设备性能等。", "explanation": "光传播速度只决定传播延迟的一部分；数据吞吐能力和等待时间也影响观看。", "rubric": ["合理列出至少两个不同因素。", "说明传播速度不等于整个网络的服务速度。"]}], "sim": "wave", "tags": ["电话", "电磁波", "波长", "频率", "移动通信", "光纤", "卫星"]}, {"id": "physics-22", "subject": "physics", "chapter": "第二十二章", "title": "能源与可持续发展", "term": "全一册", "category": "同步", "intro": "怎样为学校选择更合适的能源方案？在能量、环境、成本与稳定供给之间作有依据的比较。", "periods": "4—5课时（建议）", "goals": ["按可再生性和获取方式分类常见能源", "辨认核裂变、核聚变与太阳能利用的基本路径", "结合数据制定有边界条件的节能方案"], "sections": [{"title": "22.1 能源", "body": "能够提供可利用能量的资源称为能源。煤、石油、天然气等来自自然界，是一次能源；电能通常需由其他能源转化获得，常作为二次能源使用。分类标准不同，不能混用：可再生能源强调在人的时间尺度上能自然补充，例如太阳能、风能、水能；化石能源与目前利用的铀等燃料储量有限，属于不可再生能源。能源利用历史与技术发展有关，方便运输、能量密度和环境影响都会改变选择。风能、水循环和生物质等与太阳辐射有关，但地热、核能等不能全部归为太阳能的直接转化。"}, {"title": "22.2 核能", "body": "原子核发生变化时可以释放能量，重原子核裂变与轻原子核聚变是两种不同过程。核电站利用受控核裂变产生热量，再经蒸汽、汽轮机和发电机等环节把能量转为电能；并不是让原子核直接转成电流。太阳的巨大能量来自其内部的核聚变。理解核能要同时看到能量密度高、发电运行过程碳排放较低等特点，以及辐射防护、废物管理和工程安全等要求。核能是否可再生要按所用燃料与技术条件判断，常规铀燃料核电在中学分类中通常按不可再生能源处理。"}, {"title": "22.3 太阳能", "body": "太阳向外辐射能量，地表接收的太阳辐射可直接用于加热，也可由太阳能电池转成电能。太阳能热水器主要将太阳辐射能转为水的内能，光伏电池则将光能转为电能，两种装置的主要转换路径不同。实际可获得的能量受日照强弱、面积、时间、安装条件和转换效率影响，阴雨与夜间会影响供给，所以常需储能或其他电源配合。比较太阳能方案不能只说“取之不尽”，还应考虑制造、占地、维护和回收等全过程；可再生不等于没有环境代价或任何地点都同样适用。"}, {"title": "22.4 能源与可持续发展", "body": "能源需求要与资源补充、环境承受和长期供给协调。化石燃料燃烧可带来温室气体和污染物排放，提高效率、减少浪费、合理发展不同能源都是可讨论路径。能量守恒并不取消节能的必要：转为分散内能的能量通常难以全部恢复成便于利用的形式。制定方案应先定义服务需求，例如相同照度、相同出行人数，再比较耗能，不能通过降低必要生活或学习条件来制造“节能成绩”。使用数据时标出单位、时间和假设，区分实测与估算，同时考虑成本、可靠性与当地条件。"}], "formulas": [{"text": "η=E有用/E输入×100%", "note": "明确转换阶段，例如光伏板的电能输出与接收太阳辐射能。"}, {"text": "E节约=(P原−P新)t", "note": "功率用kW、时间用h时结果为kW·h；需保证相同服务需求。"}, {"text": "E入=辐射功率密度×面积×时间", "note": "本章简化估算假设照射均匀、强度恒定，并考虑有效受光面积。"}], "examples": [{"question": "某光伏模型接收太阳辐射能8000J，输出电能1600J，转换效率多少？", "steps": ["明确输入是接收辐射能，输出是电能。", "η=1600/8000×100%。"], "answer": "20%。"}, {"question": "学校把20盏36W灯更换为满足相同照明需求的18W灯，每天使用5h，每月按20天。每月约节电多少度？", "steps": ["减少总功率20×(36−18)=360W=0.36kW。", "月使用时间5×20=100h，节电E=0.36×100kW·h。"], "answer": "36kW·h，即36度；忽略其他配套耗电变化。"}, {"question": "太阳能板有效面积2m²，平均接收辐射功率密度500W/m²，连续有效照射3h，效率20%。求电能输出。", "steps": ["接收功率500×2=1000W=1kW。", "接收能量1×3=3kW·h，输出电能3×20%。"], "answer": "0.60kW·h；估算假设平均辐照和效率可视为恒定。"}], "activity": {"title": "给学校设计一项可核查的节能行动", "materials": "教室设备清单、功率资料、使用时长日志、计算器、纸笔。", "steps": ["选定一个目标，例如在满足照明需求下减少空教室开灯。", "连续记录或使用教师给定的一周数据，计算原耗电量。", "提出具体措施，估计可减少的时长或功率，列明假设。", "对比节能量、实施成本和执行难度，安排实施后的相同口径复查。"], "recordHeaders": ["措施", "原用电/kW·h", "预计用电/kW·h", "节电量/kW·h", "验证方法"], "conclusion": "好的节能方案具有明确服务需求、可复核计算和后续验证；预计节能量不能冒充已实测成果。", "safety": "仅观察和计算，不拆电器、不改线路；太阳能活动不使用聚光镜对准人或可燃物，核能内容只作模型学习。"}, "mistakes": ["“电能一定是可再生能源”错误：电是二次能源，其来源可由不同能源转化。", "“核电站与太阳都靠同一种核反应”错误：常规核电站以受控裂变为主，太阳以聚变释放能量。", "“可再生能源完全没有环境影响”错误：还要考虑材料、制造、占地、储能、维护和回收。"], "quiz": [{"type": "choice", "question": "下列哪一种通常属于二次能源？", "options": ["煤", "石油", "天然气", "电能"], "answer": 3, "explanation": "电能通常由其他能源转化获得；煤、石油、天然气为一次能源。"}, {"type": "choice", "question": "下列哪组都属于可再生能源？", "options": ["煤和风能", "太阳能和风能", "石油和天然气", "铀燃料和煤"], "answer": 1, "explanation": "太阳能、风能在人的时间尺度上可自然持续补充。"}, {"type": "choice", "question": "常规核电站的主要能量来源是？", "options": ["受控核裂变", "燃烧原子壳层", "水的化学分解", "太阳能电池"], "answer": 0, "explanation": "常规核电站利用受控裂变释放能量，再进行热机与发电转换。"}, {"type": "choice", "question": "太阳能热水器主要完成哪种转化？", "options": ["内能变成太阳辐射能", "机械能变成核能", "太阳辐射能变成内能", "电能全部变成声音"], "answer": 2, "explanation": "热水器主要吸收太阳辐射，使水等物体内能增加。"}, {"type": "short", "question": "一装置输入5000J能量，输出1500J有用能量，效率多少？其余能量是否消失？", "answer": "效率30%；其余3500J没有消失，可能转为环境内能等。", "explanation": "η=1500/5000×100%=30%；总能量守恒，有用与其他输出之和等于输入（忽略储能变化）。", "rubric": ["正确计算30%。", "说明其余能量去向并联系守恒。"]}, {"type": "short", "question": "满足相同照明需求时，把10盏30W灯换成15W灯，每天工作4h，20天约节电多少？写出主要假设。", "answer": "12kW·h；假设照明效果满足同一需求、实际功率近似给定值、每天使用4h且忽略其他耗电变化。", "explanation": "减少功率10×15W=150W=0.15kW，时间80h，节电0.15×80=12kW·h。", "rubric": ["节电量计算12kW·h且单位正确。", "至少写出相同照明需求与使用时长等关键假设。"]}], "sim": "energy", "tags": ["能源", "可再生", "核能", "太阳能", "可持续发展", "节能方案"]}]}, {"subject": "chemistry", "edition": "人教版经典 12 单元目录", "editionNote": "按人民教育出版社 2015 年公开的九年级上册及下册教师用书目录编排，覆盖上下册 12 单元核心内容。本资料为原创教学辅导，不是教材全文，不声称是 2024/2025 修订版的逐章对应目录；修订版使用者可按知识主题查找，授课时以本校教材为准。数值题采用常用近似相对原子质量：H 1、C 12、N 14、O 16、Na 23、Mg 24、Al 27、S 32、Cl 35.5、Ca 40、Fe 56、Cu 64、Zn 65。", "sources": [{"title": "人民教育出版社：义务教育教科书 化学 九年级上册（公开经典目录）", "url": "https://www.pep.com.cn/products/jc/czjks/201510/t20151026_1250692.shtml"}, {"title": "人民教育出版社：教师教学用书 化学 九年级下册（公开经典目录）", "url": "https://www.pep.com.cn/products/jc/jks/201510/t20151026_1250892.shtml"}, {"title": "人民教育出版社：中小学教材电子版入口（核对本校版本）", "url": "https://jc.pep.com.cn/"}], "chapters": [{"id": "chemistry-01", "subject": "chemistry", "chapter": "第1单元", "title": "走进化学世界", "term": "上册", "category": "同步", "intro": "蜡烛熔化与燃烧都发生了变化，凭什么判断它们是否属于同一类？", "periods": "5–6课时（建议）", "goals": ["用是否生成新物质区分两类变化，并说明证据", "区分实验现象、推论与结论，设计单变量对照", "规范取用药品、读取体积并选择适当仪器"], "sections": [{"title": "课题1 物质的变化和性质", "body": "判断变化的关键是有没有生成新物质，而不是颜色、形状或温度是否改变。冰熔化后仍是水，属于物理变化；铁生锈形成了与铁不同的物质，属于化学变化。颜色改变、放热、产生气泡只能提供线索，例如水沸腾也有气泡。性质描述物质能够怎样变化，如酒精具有可燃性；变化描述一次实际过程，如酒精正在燃烧。密度、熔点等物理性质可以不经化学变化测得；可燃性、氧化性等化学性质要在化学变化中表现。"}, {"title": "课题2 化学是一门以实验为基础的科学", "body": "科学探究从可检验的问题开始，依次提出猜想、设计方案、收集证据、解释结果并反思。比较两种条件的影响时，应只改变一个因素，其余条件尽量相同。观察蜡烛时，要分别记录点燃前、燃烧中与熄灭后的事实，再解释事实；“看到杯壁有液滴”是现象，“生成了水”还需要结合检验与排除干扰。一次现象与预想不同，不应修改记录，而应检查仪器、步骤和控制条件，用重复实验评价结果是否可靠。"}, {"title": "课题3 走进化学实验室", "body": "进入实验室先读标签和风险提示，在教师指导下取用少量药品，不能尝、不能直接凑近闻，也不能把剩余药品倒回原瓶。量筒应放平，视线与液体凹液面最低处保持水平；量程应接近需要测量的体积。滴管悬空滴加，避免接触容器内壁造成污染。加热试管时，管口不能朝向任何人；使用酒精灯须由教师安排，不能用燃着的灯引燃另一盏。实验结束按指定方式收集废液、清洗并归位仪器。"}], "formulas": [{"text": "证据 → 推理 → 结论", "note": "观察事实与解释分开记录；判断化学变化以生成新物质为依据。"}, {"text": "比较实验：一个自变量，其余条件尽量相同", "note": "实验组与对照组要有可比性，重复测量可检验结果稳定性。"}], "examples": [{"question": "将白砂糖研碎与加热至焦黑分别属于什么变化？", "steps": ["研碎只改变颗粒大小，仍是蔗糖。", "变焦黑过程中形成新物质，不能仅因颜色变深就下结论，要结合产物性质。"], "answer": "研碎是物理变化；加热至焦黑是化学变化。"}, {"question": "需要量取18 mL水，可选10 mL、25 mL或100 mL量筒，怎样选择？", "steps": ["选一次能量取所需体积、量程最接近目标的量筒。", "放平25 mL量筒，临近18 mL时用滴管微调，平视凹液面最低处。"], "answer": "选择25 mL量筒。"}], "activity": {"title": "把“看到的”与“解释的”分开", "materials": "透明杯、清水、食盐、搅拌棒、记录表", "steps": ["记录盐、水的外观；向清水中加入少量食盐并搅拌。", "只写看得见的现象，再另写一种解释。", "比较“看不见盐粒”与“盐不存在了”是否等价。", "讨论用蒸发结晶检验解释的思路，仅由教师示范加热。"], "recordHeaders": ["步骤", "直接观察", "解释", "还需什么证据"], "conclusion": "盐粒看不见不能证明盐消失；溶解是分散过程，可用回收溶质提供证据。", "safety": "材料虽为食品也不得品尝实验样品；不安排学生自行加热或烧干。"}, "mistakes": ["有气泡不一定是化学变化，沸腾也产生气泡。", "物质的性质与变化不同：“能燃烧”是性质，“正在燃烧”是变化。", "量筒读数不能俯视或仰视，应平视凹液面最低处。"], "quiz": [{"type": "choice", "question": "下面哪一个过程可以确定生成了新物质？", "options": ["玻璃杯碎裂", "铁钉生成铁锈", "冰块融化", "酒精挥发"], "answer": 1, "explanation": "铁锈与铁是不同物质，其余过程仅改变状态或形状。"}, {"type": "choice", "question": "“铜能导电”描述的是铜的哪一类信息？", "options": ["物理性质", "化学性质", "一次化学变化", "一次物理变化"], "answer": 0, "explanation": "能导电是一种性质，不需要通过化学变化才能表现。"}, {"type": "choice", "question": "量取液体时，正确的读数位置是？", "options": ["从量筒上方向下看", "从液面下方向上看", "与凹液面最低处保持水平", "看液面最高处"], "answer": 2, "explanation": "平视凹液面最低处可减少视差，普通水溶液按该方法读数。"}, {"type": "choice", "question": "探究搅拌对同种食盐溶解快慢的影响，哪项设计最合理？", "options": ["同时改变水温与水量", "两杯温度、水量、盐量相同，一杯搅拌", "一杯盐用颗粒、一杯用粉末，同时搅拌", "两杯都搅拌且水量不同"], "answer": 1, "explanation": "应只改变搅拌条件，控制水温、水量及食盐质量和颗粒状态。"}, {"type": "short", "question": "“加入粉末后有气泡，所以一定发生化学变化。”这句判断有什么问题？", "answer": "气泡只是线索，也可能是逸出的空气；还需证明生成了新物质。", "explanation": "观察与结论之间需要证据链，不能将一种现象机械等同于一种变化。", "rubric": ["指出有气泡不是充分证据", "提出需要检验新物质"]}, {"type": "short", "question": "写出使用滴管时两项避免污染的做法。", "answer": "滴管悬空滴加、不伸入或接触受液容器内壁；不同试剂使用清洁的专用滴管，不能混用。", "explanation": "污染会改变试剂成分并干扰实验，少量污染也可能导致错误结论。", "rubric": ["正确说明滴加位置", "正确说明防止试剂交叉污染"]}], "sim": "particles", "tags": ["实验基本操作", "物质变化", "控制变量"]}, {"id": "chemistry-02", "subject": "chemistry", "chapter": "第2单元", "title": "我们周围的空气", "term": "上册", "category": "同步", "intro": "空气看不见，怎样证明它是一种混合物，并分辨氧气的性质与用途？", "periods": "6–7课时（建议）", "goals": ["描述空气主要成分及体积分数", "比较氧气、空气中的燃烧现象并解释助燃性", "读懂氧气制取、收集、检验及催化剂的实验方案"], "sections": [{"title": "课题1 空气", "body": "空气是由多种气体组成的混合物，通常按体积计算，氮气约占78%，氧气约占21%，其余约占1%。“氧气约占五分之一”指空气体积分数，不是质量分数。测定氧气含量可让一定量空气中的氧气被选择性消耗，待气体恢复与初始相同的温度和压强且未引入新气体后根据气体体积减小量估计。装置漏气、氧气未充分消耗或未冷却就读数都会影响结果。空气成分具有用途，氮气可作保护气；保持空气清洁需要控制颗粒物及有害气体排放。"}, {"title": "课题2 氧气", "body": "氧气通常是无色无味的气体，能支持许多可燃物燃烧，但氧气本身不是一般意义上的燃料。物质在纯氧中燃烧常比在空气中更剧烈，这是反应条件不同所致。硫、铁丝等实验应关注反应物、生成物和安全要求，不能只记火焰颜色。铁丝在氧气中燃烧可生成四氧化三铁，瓶底需预置少量水或细沙防止高温熔滴损坏容器。化合反应强调多种物质生成一种；氧化反应强调与氧发生反应，两种分类角度并不相同。"}, {"title": "课题3 制取氧气", "body": "实验室可利用过氧化氢溶液分解制氧气，二氧化锰常用作催化剂。催化剂改变反应速率，反应前后自身质量和化学性质保持不变，但其他性质不必不变；它不改变给定反应物完全反应时生成氧气的总量。选装置时先看反应物状态和是否加热；收集气体再看溶解性和密度。排水收集较纯净，向上排空气收集可获得较干燥气体。检验氧气可利用带火星木条复燃，检验与验满的放置位置不同。"}], "formulas": [{"text": "2H₂O₂ —MnO₂催化→ 2H₂O + O₂↑", "note": "过氧化氢分解；使用稀溶液并由教师组织，不把MnO₂写成反应物。"}, {"text": "3Fe + 2O₂ —点燃→ Fe₃O₄", "note": "铁丝在氧气中燃烧；生成物不是Fe₂O₃。"}, {"text": "2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑", "note": "固体加热制氧气；本资料仅作方程式和装置分析，不作为家庭操作指南。"}], "examples": [{"question": "密闭装置中原有空气100 mL，氧气被选择性充分消耗，恢复与初始相同的温度和压强，且不引入新的气体后剩余80 mL，估测氧气体积分数。", "steps": ["气体减少100−80=20 mL。", "氧气体积分数约为20÷100×100%。"], "answer": "约20%，与约五分之一接近。"}, {"question": "同量同浓度过氧化氢分成两份，一份加二氧化锰，比较产生氧气的速度和最终总量。", "steps": ["催化剂加快该反应的速率。", "反应物质量相同，完全反应的产氧总量相同。"], "answer": "加二氧化锰的一份产生氧气更快，两份完全反应后的氧气总量相同。"}], "activity": {"title": "用体积卡片重建空气组成", "materials": "100格方格纸、两色笔、教师提供的气体体积数据", "steps": ["用78格表示氮气、21格表示氧气、1格表示其余气体。", "分析原气体50 mL、反应冷却后40 mL的数据。", "分别预测漏入外界空气与氧气未完全消耗时的结果。", "用体积比例解释空气在何种意义下是混合物。"], "recordHeaders": ["原体积/mL", "剩余体积/mL", "减少量/mL", "估计氧气比例"], "conclusion": "50 mL减少10 mL，对应20%；剩余体积偏大时测得氧气比例偏小。", "safety": "使用纸面数据，不在家庭燃烧磷、硫或进行高温密闭实验；涉及气体制取的实验由教师在实验室组织。"}, "mistakes": ["氧气能助燃，不等于氧气本身可燃。", "空气中氧气约21%通常指体积分数，不能套为质量分数。", "催化剂可改变速度，不会使同量反应物凭空多产生氧气。"], "quiz": [{"type": "choice", "question": "通常情况下空气中体积分数最大的气体是？", "options": ["氧气", "二氧化碳", "氮气", "稀有气体"], "answer": 2, "explanation": "氮气约占78%，多于氧气的约21%。"}, {"type": "choice", "question": "能使带火星木条复燃的气体通常可判断为？", "options": ["氮气", "氧气", "二氧化碳", "氦气"], "answer": 1, "explanation": "这是初中实验常用的氧气检验方法。"}, {"type": "choice", "question": "关于二氧化锰催化过氧化氢分解，正确的是？", "options": ["自身质量必定减少", "完全反应后氧气总量增多", "反应前后化学性质保持不变", "任何反应都能被它催化"], "answer": 2, "explanation": "催化剂具有选择性，能改变速率，自身质量与化学性质反应前后不变。"}, {"type": "choice", "question": "测空气中氧气含量时氧气没有消耗完全，其他条件理想，测得结果会？", "options": ["偏小", "偏大", "恰好为100%", "无法出现体积变化"], "answer": 0, "explanation": "氧气未完全消耗使体积减少量偏小。"}, {"type": "short", "question": "铁丝在氧气中燃烧前，为什么要在集气瓶底放少量水或细沙？", "answer": "防止高温熔化物溅落使集气瓶底炸裂。", "explanation": "该安排保护容器，水或细沙不作为此反应的反应物。", "rubric": ["指出高温熔化物危险", "说明防止瓶底损坏"]}, {"type": "short", "question": "60 mL空气中的氧气被充分消耗，恢复相同温度和压强后剩48 mL，求测得的氧气体积分数。", "answer": "(60−48)÷60×100%=20%。", "explanation": "先求被消耗的气体体积，再除以原空气体积。", "rubric": ["减少量为12 mL", "体积分数为20%"]}], "sim": "reaction", "tags": ["空气", "氧气", "催化剂", "气体制取"]}, {"id": "chemistry-03", "subject": "chemistry", "chapter": "第3单元", "title": "物质构成的奥秘", "term": "上册", "category": "同步", "intro": "为什么气味能扩散，钠原子失去一个电子后又为什么不是另一种元素？", "periods": "5–6课时（建议）", "goals": ["用粒子运动、间隔解释生活现象", "根据质子数、电子数判断原子与离子", "读懂元素符号和周期表中单个元素的信息"], "sections": [{"title": "课题1 分子和原子", "body": "物质由微观粒子构成，分子、原子、离子都是常见的构成粒子。分子不断运动，粒子之间有间隔，温度升高时运动通常加快。气味扩散可以用运动解释，气体压缩主要体现间隔减小，不能说分子被压小。由分子构成的物质在物理变化中，分子本身一般不变；化学变化中分子可以分成原子，原子重新组合形成新物质。原子是化学变化中的最小粒子，这个范围不能省略，原子还具有更细的内部结构。"}, {"title": "课题2 原子的结构", "body": "原子由位于中心的原子核与核外电子构成；原子核中的质子带正电，中子不带电，电子带负电。中性原子中质子数等于核外电子数；原子得到或失去电子可形成带电的离子，而质子数不变。钠原子失去一个电子形成Na⁺，氯原子得到一个电子形成Cl⁻，离子电荷写在符号右上角。相对原子质量是相对于特定基准的比值，近似可用质子数与中子数之和理解，但它不是一个原子的实际克数。"}, {"title": "课题3 元素", "body": "元素是质子数相同的一类原子的总称，决定元素种类的是核内质子数。氧原子与氧离子只要质子数相同，都属于氧元素。元素符号通常第一个字母大写、第二个字母小写，Co与CO的含义不同；前者是钴元素符号，后者是一个一氧化碳分子的化学式。元素周期表中原子序数对应质子数，元素符号和相对原子质量可帮助书写化学用语。描述水的组成说“含氢、氧元素”，描述一个水分子则说“含两个氢原子、一个氧原子”。"}], "formulas": [{"text": "中性原子：质子数 = 核外电子数", "note": "质子数又等于原子序数；离子不能直接套用电子数相等。"}, {"text": "离子所带电荷数 = 质子数 − 电子数", "note": "差为正时为阳离子，差为负时为阴离子。"}, {"text": "Aᵣ ≈ 质子数 + 中子数", "note": "用于初中简单近似计算；Aᵣ无质量单位，不表示实际原子质量。"}], "examples": [{"question": "某粒子有12个质子、10个电子，它带什么电，属于哪种常见离子？", "steps": ["正电荷比负电荷多2个单位。", "12个质子决定它是镁元素。"], "answer": "带两个单位正电荷，为Mg²⁺。"}, {"question": "解释“氧气受压后体积变小”和“氧气变为其他物质”在微观上有什么不同。", "steps": ["受压主要使氧分子之间间隔缩小，氧分子没有改变。", "若发生化学变化，则参与反应的氧分子发生重组，形成其他粒子。"], "answer": "前者主要改变分子间隔；后者改变物质的粒子组成。"}], "activity": {"title": "用纸片建立原子与离子模型", "materials": "标有质子、中子、电子的纸片，元素周期表", "steps": ["摆出11个质子、12个中子和11个电子的粒子模型。", "去掉一个电子，计算净电荷并写符号。", "保持质子数不变，再讨论中子数变化是否改变元素种类。", "说明该模型没有表现哪些真实结构特点。"], "recordHeaders": ["质子数", "中子数", "电子数", "电荷与名称"], "conclusion": "11质子11电子为中性钠原子；失去一个电子成为Na⁺，仍属于钠元素。", "safety": "纸片模型不按比例，也不表示电子沿固定圆形轨道真实运动；不拆解电池或接触金属钠。"}, "mistakes": ["分子变小不是气体被压缩的主要原因，通常是间隔变小。", "元素种类由质子数决定，不由电子数决定。", "原子在化学变化中不能再分，不等于原子没有内部结构。"], "quiz": [{"type": "choice", "question": "香味在房间里逐渐扩散，主要说明？", "options": ["分子静止", "分子不断运动", "分子没有质量", "分子一定发生化学变化"], "answer": 1, "explanation": "扩散能用分子不断运动解释。"}, {"type": "choice", "question": "决定一种原子属于哪种元素的是？", "options": ["中子数", "电子层数", "质子数", "相对原子质量的小数位数"], "answer": 2, "explanation": "元素定义依据核内质子数。"}, {"type": "choice", "question": "氯原子得到1个电子后的符号是？", "options": ["Cl⁺", "Cl⁻", "Cl₂", "2Cl"], "answer": 1, "explanation": "电子带负电，得到一个电子形成氯离子Cl⁻。"}, {"type": "choice", "question": "一个中性原子有8个质子，它有多少个核外电子？", "options": ["6个", "8个", "10个", "16个"], "answer": 1, "explanation": "中性原子的正负电荷总量相等，电子数等于质子数。"}, {"type": "short", "question": "分别写出“2O”和“O₂”的粒子含义。", "answer": "2O表示两个氧原子；O₂可表示一个氧分子，一个氧分子由两个氧原子构成。", "explanation": "符号前的系数与符号右下角数字的位置不同，含义也不同。", "rubric": ["2O解释为两个氧原子", "O₂解释为氧分子及其构成"]}, {"type": "short", "question": "粒子含13个质子、10个电子，判断其电荷，并说明失去电子是否改变元素种类。", "answer": "带三个单位正电荷；失去电子不改变元素种类，因为质子数未变。", "explanation": "元素种类与电荷状态要分开判断。", "rubric": ["电荷为+3", "质子数不变所以元素不变"]}], "sim": "atom", "tags": ["微观粒子", "原子结构", "元素", "离子"]}, {"id": "chemistry-04", "subject": "chemistry", "chapter": "第4单元", "title": "自然界的水", "term": "上册", "category": "同步", "intro": "看上去澄清的水就是纯水吗？怎样从水的组成走向化学式计算？", "periods": "7–8课时（建议）", "goals": ["选择沉淀、过滤、吸附、蒸馏等净水方法并说出局限", "根据水电解证据解释水的元素组成", "按化合价写常见化学式并计算元素质量分数"], "sections": [{"title": "课题1 爱护水资源", "body": "地球水资源总量大，但可方便利用的淡水有限，且存在地域和季节分布不均。评价用水问题需同时考虑数量与水质，节约用水和防治污染应共同进行。生活污水、农业面源污染和工业排水都可能影响水体，治理应针对污染源采用合适措施。课堂可根据学校水龙头的流量和使用时长估算耗水量，再比较改进方案。所谓节水不只是减少开水龙头的时间，也包括及时检漏、适当重复利用和改进生产工艺。"}, {"title": "课题2 水的净化", "body": "沉淀可让较大颗粒沉降，过滤可除去难溶固体，活性炭吸附有助于去除部分色素和异味，蒸馏利用沸点差异进一步获得较纯的水。各种方法针对的杂质不同，过滤后的水不一定可饮用，透明也不代表无菌或没有溶解物。过滤操作注意滤纸低于漏斗口、液面低于滤纸边缘，并用玻璃棒引流。硬水含较多可溶性钙、镁化合物，可用肥皂水与软水作比较；生活中煮沸能降低部分硬度，但不能除去所有杂质。"}, {"title": "课题3 水的组成", "body": "在适当电解装置中，水通电分解生成氢气和氧气，理想情况下相同温度、压强下两者体积比约为2∶1。验证产物身份后，可以根据化学反应前后元素种类不变，推断水由氢、氧元素组成。体积比不是质量比，水中氢、氧元素质量比为1∶8。加入少量合适电解质主要为改善导电性，不能因此把观察到的任何气泡直接认定为某种气体。实验记录要考虑装置漏气、气体溶解等因素，不强行把实测数值改成理论值。"}, {"title": "课题4 化学式与化合价", "body": "化学式用元素符号和数字表示物质的组成；化合物中各元素正、负化合价的代数和为零，可据此求未知价或确定原子个数比。写化学式时应按实际物质组成，不能为了配平方程式改动右下角数字。相对分子质量等于式中各原子的相对原子质量总和，不带克等单位。求某元素质量分数，用该元素在一个化学式单位中的相对质量除以总相对质量。元素原子个数比、元素质量比与元素质量分数含义不同，需要先辨清题目所问。"}], "formulas": [{"text": "2H₂O —通电→ 2H₂↑ + O₂↑", "note": "理论气体体积比2∶1（相同温度、压强）；需专用装置和教师指导。"}, {"text": "化合物中：Σ(化合价 × 原子个数) = 0", "note": "化合价带正负号；单质中元素的化合价为0。"}, {"text": "元素质量分数 = 该元素的相对原子质量×个数 ÷ 相对分子质量 ×100%", "note": "化学式对应的是纯物质；含杂质样品还需先求纯物质质量。"}], "examples": [{"question": "求硫酸H₂SO₄中氧元素的质量分数。", "steps": ["相对分子质量为2×1+32+4×16=98。", "氧元素对应相对质量为64，质量分数64÷98×100%。"], "answer": "约65.3%。"}, {"question": "已知氧通常显−2价，求Fe₂O₃中铁的化合价，并比较水中氢氧个数比与质量比。", "steps": ["设铁化合价为x，2x+3×(−2)=0，得x=+3。", "H₂O中氢氧原子个数比2∶1，质量比(2×1)∶16=1∶8。"], "answer": "铁为+3价；水中氢氧原子个数比2∶1，元素质量比1∶8。"}], "activity": {"title": "纸面设计一条净水流程", "materials": "教师提供的含沙、有色、有可溶盐模拟水资料卡，净水方法卡", "steps": ["列出悬浮物、色素、可溶性盐三类杂质。", "选择沉淀、过滤、吸附或蒸馏并排列顺序。", "逐步标出能除去什么、还留下什么。", "评判“过滤后就能喝”的说法并修订流程说明。"], "recordHeaders": ["杂质类型", "选择方法", "主要作用", "残留问题"], "conclusion": "先处理难溶颗粒，再吸附部分色素；可溶盐不能靠普通过滤去除，饮用安全还需要相应检测和处理。", "safety": "使用资料卡，不饮用任何实验处理水；水电解只分析教师数据，不自制电解器或点燃收集气体。"}, "mistakes": ["水电解的气体体积比2∶1，不是氢氧元素的质量比。", "过滤除去难溶固体，不能保证水无菌，也不能除尽可溶性盐。", "化学式右下角数字不能随意改动，求质量比要乘相对原子质量。"], "quiz": [{"type": "choice", "question": "普通过滤最适合除去水中的哪种杂质？", "options": ["氯化钠", "酒精", "泥沙", "所有细菌"], "answer": 2, "explanation": "过滤主要除去难溶性固体，不能保证去除全部微生物。"}, {"type": "choice", "question": "水在理想电解条件下产生氢气与氧气的体积比约为？", "options": ["1∶1", "1∶2", "2∶1", "1∶8"], "answer": 2, "explanation": "相同温压下理论体积比与气体分子数比相同。"}, {"type": "choice", "question": "CO₂中碳、氧元素的质量比为？", "options": ["1∶2", "3∶8", "3∶4", "12∶16"], "answer": 1, "explanation": "一个化学式单位中相对质量为12∶32=3∶8。"}, {"type": "choice", "question": "已知Ca为+2价、Cl为−1价，氯化钙化学式为？", "options": ["CaCl", "Ca₂Cl", "CaCl₂", "Ca₂Cl₃"], "answer": 2, "explanation": "一个+2与两个−1代数和为零。"}, {"type": "short", "question": "解释为什么“澄清透明的水一定是纯水”错误。", "answer": "水中可能溶有无色的盐或其他物质；澄清只表示没有明显悬浮颗粒，不能确定只含一种物质。", "explanation": "应依据组成是否单一判断纯净物，而不是只看外观。", "rubric": ["指出可含溶解物", "指出纯净物必须只含一种物质"]}, {"type": "short", "question": "计算CaCO₃的相对分子质量和钙元素的质量分数。", "answer": "相对分子质量40+12+3×16=100；钙的质量分数40÷100×100%=40%。", "explanation": "化学式中每个元素的原子个数都要计入。", "rubric": ["总相对质量100", "钙质量分数40%"]}], "sim": "particles", "tags": ["水", "净化", "化学式", "化合价", "元素质量分数"]}, {"id": "chemistry-05", "subject": "chemistry", "chapter": "第5单元", "title": "化学方程式", "term": "上册", "category": "同步", "intro": "反应后天平读数改变，是否意味着质量守恒定律失效？", "periods": "6–7课时（建议）", "goals": ["用原子重组解释质量守恒并界定研究系统", "正确书写、配平常见化学方程式并标条件", "利用化学方程式进行一步质量计算"], "sections": [{"title": "课题1 质量守恒定律", "body": "化学反应中，参加反应的各物质质量总和等于生成的各物质质量总和。微观原因是原子的种类、数目和质量在普通化学反应前后不变，原子只重新组合。研究时要把进入或离开系统的气体计入，否则开放容器中测得的质量可以增加或减少。没有参加反应的过量物质不应计入反应物消耗量。质量守恒能帮助推断未知质量和元素组成，但不能据此认为反应前后分子种类、分子数、气体体积都必定相同。"}, {"title": "课题2 如何正确书写化学方程式", "body": "写方程式先以客观反应为依据，正确写出反应物和生成物的化学式，再调整化学式前的系数，使两边各元素原子数相等，最后检查条件、气体或沉淀符号。配平不能改变化学式内部数字，因为那会改变物质身份。最简整数系数表示微观粒子数比，不直接表示质量比。点燃、加热、高温、通电、催化剂等条件各有含义，应与具体反应相符。当反应物中已有气体时，通常不在生成气体后再标上升箭头。"}, {"title": "课题3 利用化学方程式的简单计算", "body": "依据方程式计算时，先找已知的纯物质质量，再写配平方程式，列出相关物质的相对质量关系，代入已知量设比例，最后检查结果与单位。系数必须与相对分子质量相乘，例如两份H₂不是2 g对应一份O₂，而是4 g对应32 g。若题目给出溶液质量或不纯样品质量，应先转化为真正参与反应的纯物质质量；若有两种反应物，应判断谁有剩余。计算只适用于题目给定的反应和完全反应程度，不能随意混用不同产物。"}], "formulas": [{"text": "m(参加反应的物质总和) = m(生成物总和)", "note": "普通化学反应；把进出系统的物质都计入。"}, {"text": "2H₂ + O₂ —点燃→ 2H₂O", "note": "相对质量关系4∶32∶36；氢气燃烧是教师演示内容。"}, {"text": "CaCO₃ —高温→ CaO + CO₂↑", "note": "相对质量关系100∶56∶44；不把高温条件漏掉。"}], "examples": [{"question": "10 g纯碳酸钙完全分解生成多少克二氧化碳？", "steps": ["CaCO₃ —高温→ CaO+CO₂↑，相关质量比100∶44。", "设二氧化碳质量x，100/44=10 g/x。"], "answer": "x=4.4 g。"}, {"question": "密闭容器中4 g氢气与40 g氧气在适当条件下充分反应，生成水多少克，剩什么？", "steps": ["4 g氢气需要32 g氧气，氧气有剩余。", "水质量4+32=36 g，剩余氧气40−32=8 g。"], "answer": "生成36 g水，剩余8 g氧气。"}], "activity": {"title": "用粒子卡片配平水生成反应", "materials": "氢原子、氧原子纸片，系数卡片", "steps": ["先摆出H₂、O₂、H₂O的模型，不改每个分子内部组成。", "通过增加分子个数使两边氢原子、氧原子分别相等。", "记录最简系数，并根据相对原子质量换算质量比。", "比较反应前后原子总数和分子总数是否都相同。"], "recordHeaders": ["物质", "系数", "原子数贡献", "相对质量贡献"], "conclusion": "系数2∶1∶2；原子数保持不变，分子总数可由3变为2，质量比4∶32∶36。", "safety": "仅用纸片或网页模型；不在家庭混合氢气与氧气，不用密封加热装置演示。"}, "mistakes": ["反应后的溶液变轻可能是气体逸出，不是质量不守恒。", "系数表示粒子数比，质量比还需乘相对分子质量。", "配平只能改系数，不能把H₂O改成H₂O₂。"], "quiz": [{"type": "choice", "question": "化学反应前后一定不变的是？", "options": ["分子总数", "物质种类", "原子种类和数目", "气体体积"], "answer": 2, "explanation": "普通化学反应是原子重新组合的过程。"}, {"type": "choice", "question": "配平Fe+O₂→Fe₃O₄，最简系数依次为？", "options": ["1、1、1", "3、2、1", "2、3、1", "3、1、2"], "answer": 1, "explanation": "左右铁均3个，氧均4个；完整反应还需标点燃条件。"}, {"type": "choice", "question": "敞口容器里碳酸盐与酸反应后读数减小，最可能原因是？", "options": ["原子消失", "生成气体逸出", "质量守恒只适用固体", "天平一定损坏"], "answer": 1, "explanation": "逸出的气体仍属于生成物，计入后质量守恒。"}, {"type": "choice", "question": "若反应中A与B的质量比为2∶3，4 g A完全反应需要B多少克？", "options": ["2 g", "3 g", "6 g", "8 g"], "answer": 2, "explanation": "4×3÷2=6 g。"}, {"type": "short", "question": "反应2Mg+O₂ —点燃→ 2MgO中，12 g镁完全燃烧需要多少克氧气？", "answer": "质量关系48∶32；所需氧气12×32÷48=8 g。", "explanation": "需用相对质量关系，不能把系数2∶1当作质量比。", "rubric": ["列出48∶32", "得8 g并写单位"]}, {"type": "short", "question": "某物质在纯氧中完全燃烧只生成CO₂和H₂O，能确定它含哪些元素，不能确定哪一种？", "answer": "一定含碳、氢元素；不能仅凭产物判断是否含氧元素。", "explanation": "产物碳、氢只能来自该物质，而氧可能来自氧气，也可能来自原物质。", "rubric": ["确定碳和氢", "说明氧元素来源不唯一"]}], "sim": "balance", "tags": ["质量守恒", "方程式", "配平", "质量计算"]}, {"id": "chemistry-06", "subject": "chemistry", "chapter": "第6单元", "title": "碳和碳的氧化物", "term": "上册", "category": "同步", "intro": "金刚石与石墨都含碳，为什么性质不同？只差一个氧原子的CO与CO₂又为何差别很大？", "periods": "6–7课时（建议）", "goals": ["联系结构解释碳单质的性质与用途", "比较CO₂与CO的性质、检验及环境影响", "设计并解释实验室制取CO₂的装置与检验方案"], "sections": [{"title": "课题1 金刚石、石墨和C₆₀", "body": "金刚石、石墨和C₆₀都是由碳元素组成的单质，但碳原子的排列和结合方式不同，因此硬度、导电性等性质不同。金刚石硬度大，可用于切割；石墨能导电且层间易滑动，可用于电极等。木炭、活性炭具有多孔结构，吸附作用主要是把某些物质留在表面，不能简单说把杂质分解了。碳在常温下化学性质较稳定，在点燃或高温条件下可发生反应；氧气是否充足会影响燃烧产物，高温下碳还可表现还原性。"}, {"title": "课题2 二氧化碳制取的研究", "body": "实验室常用大理石或石灰石与稀盐酸反应制取二氧化碳。选择药品既看能否反应，也要看速率是否适中、是否便于收集以及杂质影响。碳酸钙与稀硫酸可能形成微溶覆盖层，使反应受阻，因此不宜简单替代。装置应先检查气密性，固液常温反应一般不需加热；二氧化碳密度比空气大，且能溶于水，通常用向上排空气法收集。检验应使用澄清石灰水；燃着木条在瓶口熄灭是常用的验满方法之一，但不是气体身份的唯一证明。"}, {"title": "课题3 二氧化碳和一氧化碳", "body": "二氧化碳在通常条件下不能燃烧也不支持一般可燃物燃烧，与水反应形成碳酸，能使澄清石灰水变浑浊。干冰是固态二氧化碳，升华吸热可用于制冷；大气中二氧化碳增加与温室效应增强有关。一氧化碳是无色无味的有毒气体，能燃烧并具有还原性。两者组成不同，分子结构不同，因此性质不能互相照搬。涉及一氧化碳还原金属氧化物的内容仅用于方程式与装置原理分析，实验尾气必须专业处理，不能自行生成或测试一氧化碳。"}], "formulas": [{"text": "CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂↑", "note": "碳酸钙与稀盐酸常温反应；反应式可用于制气和碳酸盐检验。"}, {"text": "CO₂ + Ca(OH)₂ → CaCO₃↓ + H₂O", "note": "少量CO₂通入澄清石灰水变浑浊；过量CO₂情形需另作讨论。"}, {"text": "CO₂ + H₂O ⇌ H₂CO₃", "note": "表示水中存在碳酸形成与分解的平衡；初中也常用分别书写的反应表示。"}, {"text": "2CO + O₂ —点燃→ 2CO₂", "note": "一氧化碳可燃且有毒，仅作学习分析。"}, {"text": "C + 2CuO —高温→ 2Cu + CO₂↑", "note": "高温条件下碳还原氧化铜；非家庭实验。"}], "examples": [{"question": "25 g含CaCO₃ 80%的石灰石与足量稀盐酸反应，可生成多少克CO₂？假设杂质不反应。", "steps": ["纯CaCO₃质量25×80%=20 g。", "方程式中CaCO₃与CO₂质量比100∶44，气体质量20×44÷100。"], "answer": "生成8.8 g CO₂。"}, {"question": "收集的一瓶气体使燃着木条熄灭，是否一定是CO₂？怎样进一步检验？", "steps": ["氮气等也能使一般可燃物熄灭，现象不唯一。", "取样通入澄清石灰水，结合气体来源判断。"], "answer": "不能确定；可观察是否使澄清石灰水变浑浊，并结合其他证据。"}], "activity": {"title": "比较三种制气方案", "materials": "CaCO₃与稀盐酸、CaCO₃与稀硫酸、Na₂CO₃粉末与稀盐酸的教师资料卡", "steps": ["列出反应物状态和是否需要加热。", "按教师视频或文字数据比较气泡产生的快慢与持续性。", "选择较平稳便于收集的一组并解释。", "为选定方案标出气密性检查、收集与检验步骤。"], "recordHeaders": ["反应方案", "速率特点", "问题", "适用性"], "conclusion": "常用石灰石与稀盐酸；粉末反应可能太快，稀硫酸可能形成覆盖层影响反应。", "safety": "仅分析资料；真实制气由教师提供稀试剂并在实验室指导，严禁封堵出气口或尝试制一氧化碳。"}, "mistakes": ["金刚石与石墨性质不同，不代表它们属于不同元素。", "木条熄灭只能说明不支持该燃烧，不能单独证明是CO₂。", "CO有毒且无色无味，不能凭气味判断是否存在。"], "quiz": [{"type": "choice", "question": "金刚石与石墨物理性质差异主要因为？", "options": ["元素种类不同", "碳原子的排列和结合方式不同", "都能燃烧", "原子质量随意变化"], "answer": 1, "explanation": "同一元素可形成结构不同的单质，结构影响性质。"}, {"type": "choice", "question": "实验室检验CO₂通常使用？", "options": ["蒸馏水", "食盐水", "澄清石灰水", "带火星木条"], "answer": 2, "explanation": "CO₂与氢氧化钙生成碳酸钙沉淀，使石灰水变浑浊。"}, {"type": "choice", "question": "关于CO的说法正确的是？", "options": ["有刺激性气味，可直接闻", "无毒且不可燃", "无色无味，有毒且可燃", "与CO₂性质完全相同"], "answer": 2, "explanation": "CO的毒性与可燃性都需要特别注意，无味不代表安全。"}, {"type": "choice", "question": "固态CO₂转变为气态CO₂主要属于？", "options": ["化学变化", "升华这一物理变化", "生成了氧气", "金属腐蚀"], "answer": 1, "explanation": "状态改变而物质身份没有改变。"}, {"type": "short", "question": "写出二氧化碳使澄清石灰水变浑浊的方程式，并指出白色固体名称。", "answer": "CO₂+Ca(OH)₂→CaCO₃↓+H₂O；白色固体是碳酸钙。", "explanation": "澄清石灰水中的有效成分是氢氧化钙，产物碳酸钙难溶于水。", "rubric": ["正确配平方程式", "指出CaCO₃沉淀名称"]}, {"type": "short", "question": "为什么利用CO还原氧化铜的演示不能直接把尾气排入教室？", "answer": "尾气可能含未反应的一氧化碳，具有毒性，必须由教师使用合适的专业尾气处理与通风措施。", "explanation": "化学方程式显示发生反应，不意味着每个CO分子都必定反应完全。", "rubric": ["指出可能有未反应CO", "说明需要专业处理而非直接排放"]}], "sim": "reaction", "tags": ["碳单质", "二氧化碳", "一氧化碳", "气体检验"]}, {"id": "chemistry-07", "subject": "chemistry", "chapter": "第7单元", "title": "燃料及其利用", "term": "上册", "category": "同步", "intro": "燃烧需要同时具备哪些条件？更充分地利用燃料与减少污染如何兼顾？", "periods": "4–5课时（建议）", "goals": ["用燃烧三个条件解释常见灭火方法", "区分化学变化中的能量转化与物质变化", "比较化石燃料、氢能与可再生能源的应用条件"], "sections": [{"title": "课题1 燃烧和灭火", "body": "常见燃烧需要可燃物、与氧气接触、温度达到可燃物的着火点三个条件同时具备。灭火通常通过清除可燃物、隔绝氧气或使温度降到着火点以下来破坏其中的条件，不能说水把物质的着火点降低了。可燃物与氧气的接触面积越大、氧气供应越充分，反应往往越快；因此粉尘与空气混合后也可能存在爆炸风险。生活安全情境应先识别燃烧物类型，不能给所有火情套用泼水的方法；发生火情时按学校或场所应急要求撤离和求助。"}, {"title": "课题2 燃料的合理利用与开发：化石燃料", "body": "煤、石油和天然气是重要的化石燃料，形成周期长，相对人类使用速度属于不可再生能源。石油分馏依据各组分沸点不同分离，主要属于物理过程；煤的干馏会生成新物质，属于化学过程。燃料燃烧是否充分取决于氧气供应、接触面积等条件，充分燃烧通常有利于提高利用效率并减少一氧化碳等产物，但仍可能排放二氧化碳。评价燃料不能只看热量，还要同时考虑来源、运输、成本和污染控制。"}, {"title": "课题2 拓展：化学反应与能源选择", "body": "化学反应常伴随能量变化，燃料燃烧把化学能转化为热能和光能；电池则利用化学反应向外供电。能量释放不等于能量凭空产生，使用过程体现能量转化。氢气燃烧的产物是水，但其环境表现还取决于制氢方法、储运及使用过程，不能直接把氢气等同于一次可再生能源。太阳能、风能与水能的开发条件各不相同。比较方案时应明确边界，例如只比较使用端排放，还是考虑从生产到废弃的全过程。"}], "formulas": [{"text": "CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O", "note": "甲烷充分燃烧；质量关系16∶64∶44∶36。"}, {"text": "2C + O₂ —点燃→ 2CO", "note": "氧气不足时碳可能不完全燃烧生成CO；实际产物可能是混合物。"}, {"text": "C₂H₅OH + 3O₂ —点燃→ 2CO₂ + 3H₂O", "note": "乙醇充分燃烧；乙醇汽油并不等于没有碳排放。"}], "examples": [{"question": "完全燃烧8 g甲烷需要多少克氧气，并生成多少克CO₂？", "steps": ["甲烷、氧气、CO₂质量比16∶64∶44。", "8 g是16 g的一半，相关质量也各为一半。"], "answer": "需要32 g氧气，生成22 g CO₂。"}, {"question": "灭火毯覆盖燃烧物与森林防火隔离带主要分别破坏哪个条件？", "steps": ["灭火毯覆盖使燃烧物与周围空气隔离。", "隔离带移除连续分布的可燃物，使火不能继续蔓延。"], "answer": "灭火毯主要隔绝氧气；隔离带主要清除可燃物。"}], "activity": {"title": "用情景卡判断燃烧条件", "materials": "燃烧三条件卡、灭火毯/防火隔离带/冷却等情景卡", "steps": ["先把每种情景与其主要破坏的条件配对。", "给出“将温度降至着火点以下”与“降低着火点”，比较两者。", "讨论同样的燃料为什么粉碎后燃烧可能更快。", "列出还需要知道的现场信息，并说明不适宜直接照做的情景。"], "recordHeaders": ["情景", "燃烧条件", "改变的条件", "适用限制"], "conclusion": "多种方法可能共同作用；不能把某一种灭火措施推广到所有物质和场景。", "safety": "只作纸面推理，不点火、不制造粉尘云、不混合可燃气体；实际火情遵循现场应急安排，优先撤离求助。"}, "mistakes": ["灭火降温是降至着火点以下，不是把物质着火点降低。", "充分燃烧能减少部分污染物，不等于完全没有排放。", "氢气是能源载体，是否低碳要看制备等全过程。"], "quiz": [{"type": "choice", "question": "常见燃烧条件不包括以下哪一项？", "options": ["有可燃物", "接触氧气", "达到着火点", "必须有可见火焰"], "answer": 3, "explanation": "并非所有燃烧都必须出现可见火焰，前三项是本单元模型条件。"}, {"type": "choice", "question": "把燃烧物温度降到着火点以下，主要属于哪种灭火原理？", "options": ["降低着火点", "冷却", "增加氧气", "使燃料变多"], "answer": 1, "explanation": "温度降低，而着火点是物质在一定条件下的特性。"}, {"type": "choice", "question": "下列属于不可再生化石燃料的是？", "options": ["太阳能", "风能", "天然气", "水能"], "answer": 2, "explanation": "天然气的形成周期远长于人类消耗速度。"}, {"type": "choice", "question": "甲烷充分燃烧的主要产物是？", "options": ["碳和氢气", "CO₂和H₂O", "氧气和水", "只有CO₂"], "answer": 1, "explanation": "碳和氢元素分别进入CO₂和H₂O。"}, {"type": "short", "question": "说明把煤制成蜂窝状通常有利于燃烧的一个原因，并指出仍需注意的条件。", "answer": "增大煤与空气的接触面积，有利于燃烧；仍需合适且充分的氧气供应，使用设备须安全通风。", "explanation": "改变形状改善接触条件，不能代替供氧或污染治理。", "rubric": ["说明接触面积增大", "说明氧气供应或安全通风条件"]}, {"type": "short", "question": "“氢气燃烧生成水，因此制备和使用氢气全过程绝无碳排放。”这句话的推理缺少什么？", "answer": "缺少制氢、储运和设备生产等环节的信息；只知道燃烧产物不能推断全过程排放。", "explanation": "要把使用端的化学反应与能源全流程评价区分开。", "rubric": ["指出评价范围扩大但证据不足", "举出制备或储运等环节"]}], "sim": "combustion", "tags": ["燃烧", "灭火", "燃料", "能量", "新能源"]}, {"id": "chemistry-08", "subject": "chemistry", "chapter": "第8单元", "title": "金属和金属材料", "term": "下册", "category": "同步", "intro": "同是金属，为什么铝罐较耐用而铁钉容易生锈？如何把反应证据排成活动性顺序？", "periods": "6–7课时（建议）", "goals": ["联系金属和合金性质选择生活材料", "用与酸或盐溶液的反应推断金属活动性", "解释铁的冶炼与锈蚀条件并设计防锈方案"], "sections": [{"title": "课题1 金属材料", "body": "金属通常具有金属光泽、导电性、导热性和延展性，但不同金属在密度、熔点和硬度方面差异明显。选择导线、锅具或结构材料时，应把性能、成本、资源和加工条件综合考虑。合金是在金属中熔合其他金属或非金属形成的具有金属特性的材料；钢和生铁都是铁合金，含碳量和加工方式影响其性能。合金常比组成它的纯金属硬，熔点常较低，但不能把“所有性质都更好”当成普遍规律，应依据具体用途评价。"}, {"title": "课题2 金属的化学性质", "body": "金属活动性顺序可用于判断某些反应是否容易发生。在常见条件下，位于氢前的某些金属可与稀盐酸、稀硫酸反应生成氢气，铜等位于氢后的金属不能按同样规则生成氢气。较活泼金属可把较不活泼金属从其盐溶液中置换出来，但钾、钙、钠等与水剧烈反应的情况不能直接套用。观察铝时应考虑表面致密氧化膜，它可保护内部金属；这不说明铝的金属活动性弱于铁。实验比较要控制试剂、表面积及表面处理。"}, {"title": "课题3 金属资源的利用和保护", "body": "铁的冶炼是把铁矿石中的铁转化为金属铁，课堂常用一氧化碳高温还原氧化铁的反应表示其原理。工业过程比一个方程式复杂，还涉及燃料、熔剂和杂质处理。铁生锈通常需要同时接触氧气和水，盐分等因素会加快某些腐蚀过程。涂漆、涂油、镀层等可隔绝环境，改变材料组成也可改善耐蚀性。金属资源保护还包括节约使用、回收再利用和合理开采；回收不是无限无成本循环，也要考虑分选与处理过程。"}], "formulas": [{"text": "Fe + 2HCl → FeCl₂ + H₂↑", "note": "铁与稀盐酸反应通常生成+2价铁盐；盐酸过量不自动改为FeCl₃。"}, {"text": "Fe + CuSO₄ → FeSO₄ + Cu", "note": "盐溶液中的置换反应；常见现象为铁表面出现红色物质。"}, {"text": "Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂", "note": "还原冶铁原理，质量关系160∶84∶112∶132；有毒气体实验仅由教师专业安排。"}, {"text": "常见顺序：Mg > Al > Zn > Fe > (H) > Cu > Ag", "note": "仅为常用节选；使用时核对介质与反应条件，不能泛化到任意酸或溶液。"}], "examples": [{"question": "5.6 g铁与足量稀盐酸反应，生成多少克H₂？", "steps": ["Fe与H₂质量比56∶2。", "氢气质量为5.6×2÷56。"], "answer": "生成0.2 g氢气。"}, {"question": "金属A能从B盐溶液中置换出B，金属B能从C盐溶液中置换出C，判断顺序。三者均不与水反应。", "steps": ["第一条证据表明A比B活泼。", "第二条证据表明B比C活泼，合并两条关系。"], "answer": "A > B > C。"}], "activity": {"title": "用教师锈蚀数据检验双条件", "materials": "三组等规格铁钉资料：干燥空气、水与空气、除氧水并隔绝空气", "steps": ["先预测三组一段时间后的锈蚀情况。", "读取教师提供的照片或记录，注意“未见锈”不等于绝对没有变化。", "逐对比较，指出控制的变量和未改变的因素。", "提出涂油、涂漆方案并用条件模型解释。"], "recordHeaders": ["组别", "是否有水", "是否接触氧气", "锈蚀情况"], "conclusion": "同时接触水与氧气的一组易明显生锈；隔绝其中之一可减缓锈蚀。", "safety": "学生不自行煮沸封存样品或使用强干燥剂；使用教师准备的样品或照片，禁止品尝、徒手接触尖锐锈钉。"}, "mistakes": ["铝耐蚀可源于致密氧化膜，不能据此判断铝不活泼。", "铁与稀盐酸的典型产物是FeCl₂，不是FeCl₃。", "金属活动性规则有介质条件，不能直接套用硝酸、浓硫酸等反应。"], "quiz": [{"type": "choice", "question": "以下材料属于合金的是？", "options": ["纯铜", "蒸馏水", "钢", "石墨"], "answer": 2, "explanation": "钢是铁与碳等形成的合金。"}, {"type": "choice", "question": "相同条件下能与稀盐酸反应生成H₂的是？", "options": ["铜片", "银片", "铁片", "金片"], "answer": 2, "explanation": "铁在活动性顺序中位于氢前，其余列举金属位于氢后。"}, {"type": "choice", "question": "铁片放入CuSO₄溶液后出现红色物质，该物质主要是？", "options": ["铜", "铁锈", "硫", "氯化铁"], "answer": 0, "explanation": "铁把铜从其盐溶液中置换出来。"}, {"type": "choice", "question": "日常涂漆防止铁栏杆生锈，主要是？", "options": ["提高铁的纯度", "隔绝氧气和水", "把铁变为塑料", "让铁更容易失去电子"], "answer": 1, "explanation": "完整漆膜可减少铁与环境中氧气、水接触。"}, {"type": "short", "question": "比较铁生锈与铁丝在氧气中燃烧的共同点和一个不同点。", "answer": "都涉及铁与氧发生化学变化；生锈缓慢且通常需水参与，燃烧剧烈并需点燃条件，产物也不相同。", "explanation": "同为氧化过程不代表速率、条件和产物相同。", "rubric": ["共同点为与氧有关的化学变化", "说明速度、条件或产物差异"]}, {"type": "short", "question": "含Fe₂O₃ 80%的矿石200 t，理论上最多可炼得多少吨铁？假设只有Fe₂O₃提供铁。", "answer": "Fe₂O₃质量160 t；铁质量160×112÷160=112 t。", "explanation": "先去除杂质，再按Fe₂O₃与铁的相对质量比计算。", "rubric": ["纯Fe₂O₃为160 t", "理论铁产量112 t"]}], "sim": "materials", "tags": ["金属", "合金", "活动性", "冶炼", "防锈"]}, {"id": "chemistry-09", "subject": "chemistry", "chapter": "第9单元", "title": "溶液", "term": "下册", "category": "同步", "intro": "“浓”与“饱和”是同一回事吗？怎样准确配出一瓶指定浓度的盐水？", "periods": "6–7课时（建议）", "goals": ["识别溶质、溶剂并说明溶液均一稳定的条件", "在给定温度下判断饱和并读懂溶解度曲线", "计算溶质质量分数、稀释量并规范配制溶液"], "sections": [{"title": "课题1 溶液的形成", "body": "一种或几种物质分散到另一种物质中，形成均一、稳定的混合物，称为溶液。被溶解的物质是溶质，起溶解作用的物质是溶剂；均一指各部分组成相同，稳定指外界条件不变时不会自行分层或析出。溶液不一定无色，蔗糖水不导电也仍是溶液。溶解过程中可能吸热或放热，不能把温度改变直接等同于发生化学反应。油和水摇匀后的乳浊液与真溶液不同，加入洗涤剂可形成较稳定的乳化分散体系，但不能简单说油分子全溶于水。"}, {"title": "课题2 溶解度", "body": "在一定温度下，一定量溶剂里不能再溶解某种溶质的溶液，是该溶质的饱和溶液；条件改变后饱和状态也可能改变。固体溶解度通常指一定温度下，100 g溶剂中达到饱和时所溶解的溶质质量，表述时温度、100 g溶剂、饱和状态和质量四项不可缺。饱和不等于浓，不饱和不等于稀。读取曲线要先确定横纵轴，判断升温、降温或蒸发如何改变可溶量；大多数固体随温度升高溶解度增大，但氢氧化钙等不能套用这一趋势。"}, {"title": "课题3 溶液的浓度", "body": "溶质质量分数等于溶质质量除以溶液质量再乘100%，其中溶液质量等于已溶解的溶质与溶剂质量之和，未溶固体不计入。配制时依次计算、称量或量取、溶解、转移并贴标签，固体称量使用天平，水量可依据密度换算体积并量取。稀释只加水且无损失时，溶质质量守恒；蒸发浓缩若有晶体析出，则不能再直接认为溶液中溶质质量不变。实验误差分析要判断溶质或溶液总质量怎样改变，再判断质量分数方向。"}], "formulas": [{"text": "w = m(溶质) ÷ m(溶液) ×100%", "note": "溶液质量=已溶解溶质+溶剂；未溶固体不能算作溶质。"}, {"text": "稀释：m₁w₁ = m₂w₂", "note": "只加水，无反应、蒸发、泄漏或溶质析出；w代入小数时两边一致。"}, {"text": "饱和溶液溶质质量分数 = S ÷ (100+S) ×100%", "note": "S为该温度下以100 g溶剂为基准的溶解度数值，适用于相应溶质与溶剂。"}], "examples": [{"question": "配制100 g质量分数为10%的氯化钠溶液，需要食盐和水各多少克？", "steps": ["溶质质量100×10%=10 g。", "水质量100−10=90 g。"], "answer": "氯化钠10 g，水90 g。"}, {"question": "把50 g的20%盐水稀释成5%，需要加多少克水？", "steps": ["原溶质质量50×20%=10 g。", "稀释后总质量10÷5%=200 g；加水量200−50。"], "answer": "加150 g水。"}], "activity": {"title": "配制并核对一瓶10%食盐水", "materials": "食盐、清水、天平、烧杯、玻璃棒、标签；教师指导使用", "steps": ["计算配制50 g的10%盐水需5 g盐和45 g水。", "检查器具洁净，分别称取盐与水。", "将盐加入水并搅拌至完全溶解。", "贴上溶质名称、质量分数、配制日期标签，分析多加水或少称盐的影响。"], "recordHeaders": ["目标总质量/g", "盐质量/g", "水质量/g", "计算质量分数"], "conclusion": "5 g盐与45 g水形成50 g溶液，质量分数10%；在溶质不变时多加水会降低质量分数。", "safety": "不饮用实验溶液；只用食盐和清水，不加热，不混合未知清洁剂；玻璃器皿由教师检查。"}, "mistakes": ["饱和描述还能否继续溶解，浓稀描述相对含量，两者不是同一概念。", "质量分数分母是溶液总质量，不是水的质量。", "稀释溶质不变，但总质量增加；未溶固体不算在溶液质量内。"], "quiz": [{"type": "choice", "question": "20 g食盐全部溶于80 g水，溶质质量分数为？", "options": ["20%", "25%", "80%", "100%"], "answer": 0, "explanation": "溶液总质量100 g，20÷100=20%。"}, {"type": "choice", "question": "判断某溶液是否饱和，必须首先明确？", "options": ["容器颜色", "一定温度与指定溶质", "是否无色", "是否导电"], "answer": 1, "explanation": "饱和状态与温度、溶剂量和所讨论溶质有关。"}, {"type": "choice", "question": "某温度下溶解度为25 g，饱和溶液溶质质量分数为？", "options": ["25%", "20%", "75%", "125%"], "answer": 1, "explanation": "25 g溶质加100 g溶剂，质量分数25÷125=20%。"}, {"type": "choice", "question": "配制指定浓度盐水时，盐质量正确但水加多了，结果是？", "options": ["浓度偏高", "浓度偏低", "浓度不变", "必定有盐析出"], "answer": 1, "explanation": "溶质不变而溶液总质量增大，质量分数减小。"}, {"type": "short", "question": "在同一温度下，“饱和溶液一定比不饱和溶液浓”为什么不能对任意两种溶质成立？", "answer": "不同溶质的溶解度不同，低溶解度物质的饱和溶液可能比另一种物质的不饱和溶液更稀。", "explanation": "只有限定同一溶质、同一溶剂和温度，比较才有合适基础。", "rubric": ["说明溶质种类必须限定", "说明低溶解度饱和溶液可能较稀"]}, {"type": "short", "question": "把80 g的15%盐水稀释为10%，求最终总质量与加水质量。", "answer": "溶质12 g；最终溶液12÷10%=120 g；需加水40 g。", "explanation": "只加水时溶质质量守恒。", "rubric": ["溶质12 g与总质量120 g", "加水40 g"]}], "sim": "concentration", "tags": ["溶液", "溶解度", "饱和", "浓度", "配制"]}, {"id": "chemistry-10", "subject": "chemistry", "chapter": "第10单元", "title": "酸和碱", "term": "下册", "category": "同步", "intro": "酸与碱混合一定会恰好中性吗？溶液显碱性，就一定含有属于“碱”的物质吗？", "periods": "7–8课时（建议）", "goals": ["用指示剂和pH判断常温水溶液酸碱性", "归纳常见酸、碱的性质并写出代表反应", "从微观与数量角度解释中和及反应物剩余"], "sections": [{"title": "课题1 常见的酸和碱：酸", "body": "盐酸是氯化氢的水溶液，硫酸也是常见的酸。酸在水溶液中具有若干相似性质，与溶液中的氢离子有关。稀盐酸、稀硫酸可使紫色石蕊变红，可与某些活泼金属反应生成氢气，也可与某些金属氧化物、碱或盐反应。不同酸并非性质完全相同，浓硫酸的性质不能直接套用稀硫酸的规则。除铁锈时应控制酸的用量与时间，铁锈反应后铁本身仍可能继续反应。浓酸有腐蚀性，浓硫酸稀释会明显放热，必须由教师按实验室规范操作。"}, {"title": "课题1 常见的酸和碱：碱", "body": "氢氧化钠和氢氧化钙是常见的碱，可溶碱的水溶液含有氢氧根离子，因而具有一些相似性质。氢氧化钠易吸水，且能与空气中的二氧化碳反应，保存时需要密封；氢氧化钙俗称熟石灰，溶解度较小，其澄清溶液称石灰水。碱性溶液能使紫色石蕊变蓝、无色酚酞变红。但显碱性的物质不一定在分类上属于碱，例如碳酸钠是一种盐。研究性质既要依据离子组成，也要考虑溶解性和反应物条件。"}, {"title": "实验活动 酸碱性的检验与pH", "body": "在通常课堂所讨论的约25℃水溶液中，pH小于7显酸性，等于7显中性，大于7显碱性。pH表示酸碱程度，不能把pH数值直接当作酸的质量分数，也不能把两份溶液的pH简单平均来预测混合结果。测定时用洁净玻璃棒蘸取少量待测液滴在干燥pH试纸上，与标准比色卡比较；预先润湿试纸可能稀释样品、影响判断。普通pH试纸给出近似范围，并非任意精度的数值；有色溶液还可能干扰颜色观察。"}, {"title": "课题2 酸和碱的中和反应", "body": "酸与碱作用生成盐和水的反应称为中和反应，其核心可以用氢离子与氢氧根离子结合生成水来解释。酸碱混合后是否中性取决于物质种类、用量及生成物性质；只说发生中和，不能保证恰好完全反应。对于盐酸与氢氧化钠的典型情境，可以借指示剂颜色或pH变化判断趋势，再用质量关系核对。金属氧化物与酸也可能生成盐和水，但不属于酸与碱的中和反应。实际调节酸碱性应逐步加入、搅拌并检测，避免过量。"}], "formulas": [{"text": "HCl + NaOH → NaCl + H₂O", "note": "典型中和反应；相对质量关系36.5∶40∶58.5∶18。"}, {"text": "2HCl + Ca(OH)₂ → CaCl₂ + 2H₂O", "note": "一份氢氧化钙对应两份氯化氢，不能漏系数。"}, {"text": "Fe₂O₃ + 6HCl → 2FeCl₃ + 3H₂O", "note": "铁锈可用含氧化铁成分的模型解释；此反应不是中和反应。"}, {"text": "2NaOH + CO₂ → Na₂CO₃ + H₂O", "note": "氢氧化钠与二氧化碳反应；可能无明显可见现象。"}, {"text": "约25℃水溶液：pH<7酸性，pH=7中性，pH>7碱性", "note": "本单元常见课堂条件；不能把中性pH=7不加条件地推广到任意温度。"}], "examples": [{"question": "4.0 g NaOH与足量稀盐酸恰好反应，其中消耗HCl多少克，生成NaCl多少克？", "steps": ["NaOH、HCl、NaCl质量比40∶36.5∶58.5。", "4.0 g是40 g的0.1倍。"], "answer": "消耗HCl 3.65 g，生成NaCl 5.85 g。"}, {"question": "一份NaOH溶液滴加稀盐酸，pH由12变为9再到7、4，分别表示什么？", "steps": ["12和9都为碱性，说明碱逐渐被消耗。", "该典型强酸强碱体系在约25℃达到7时近于恰好中和，继续到4说明酸过量。"], "answer": "经历碱性减弱、接近中性、酸过量三个阶段。"}], "activity": {"title": "读懂一条中和过程的pH记录", "materials": "教师提供数据：加稀盐酸体积0、5、10、15、20 mL；对应pH 12、11、7、3、2", "steps": ["把酸加入量标作横轴、pH标作纵轴绘制数据点。", "标出碱性、中性、酸性三个区域。", "解释10 mL附近与15 mL时主要反应物的剩余情况。", "讨论仅从pH点线是否能算出原NaOH的质量，并列出还缺哪些数据。"], "recordHeaders": ["加酸体积/mL", "pH", "酸碱性", "可能剩余物"], "conclusion": "典型盐酸与NaOH情境中约10 mL达中性，继续加酸后酸过量；仅凭pH数据不能直接得到溶质质量。", "safety": "使用教师数据或演示；学生不接触浓酸浓碱，不混合清洁剂。真实实验佩戴护目镜，废液按教师要求回收。"}, "mistakes": ["中和发生不等于酸碱恰好无剩余。", "生成盐和水的反应不全是中和，须有酸与碱参加。", "碳酸钠溶液显碱性，但碳酸钠按组成属于盐。"], "quiz": [{"type": "choice", "question": "约25℃时，pH=3的水溶液显？", "options": ["酸性", "中性", "碱性", "无法依据pH判断"], "answer": 0, "explanation": "在本题温度和水溶液条件下，pH<7显酸性。"}, {"type": "choice", "question": "NaOH需密封保存的原因主要包括？", "options": ["会自动生成铁", "易吸水并可与CO₂反应", "不溶于水", "能与氮气迅速反应"], "answer": 1, "explanation": "暴露会改变样品质量与组成。"}, {"type": "choice", "question": "哪一个属于中和反应？", "options": ["HCl与NaOH反应", "HCl与Fe反应", "HCl与Fe₂O₃反应", "CO₂与石灰水反应"], "answer": 0, "explanation": "中和要求酸与碱作用生成盐和水。"}, {"type": "choice", "question": "测定溶液pH的合适操作是？", "options": ["把整卷试纸浸入原试剂瓶", "先把试纸充分润湿", "用洁净玻璃棒蘸液滴到干燥试纸上", "凭气味估计"], "answer": 2, "explanation": "这样可减少污染和稀释误差。"}, {"type": "short", "question": "向无色NaOH溶液中逐渐加入稀盐酸，若没有肉眼可见变化，能否判断没有反应？说明如何提供证据。", "answer": "不能；可观察加入适当指示剂后的颜色变化，或检测pH随加酸逐渐改变，证明体系酸碱性变化。", "explanation": "很多反应没有明显气体、沉淀或颜色变化，需要借助检测。", "rubric": ["指出无明显现象不等于无反应", "给出适当指示剂或pH检测方案"]}, {"type": "short", "question": "0.8 g纯NaOH恰好中和HCl多少克？", "answer": "0.8×36.5÷40=0.73 g。", "explanation": "先依据HCl+NaOH→NaCl+H₂O得到36.5∶40的质量关系。", "rubric": ["使用正确方程式或质量比", "得0.73 g"]}], "sim": "ph", "tags": ["酸", "碱", "pH", "中和", "指示剂"]}, {"id": "chemistry-11", "subject": "chemistry", "chapter": "第11单元", "title": "盐 化肥", "term": "下册", "category": "同步", "intro": "食盐只是盐的一种。怎样用反应规律区分常见盐，又怎样评价化肥中的有效养分？", "periods": "6–7课时（建议）", "goals": ["区分常见盐的组成、俗名与用途", "利用复分解反应条件分析简单检验与除杂", "计算化肥有效元素含量并解释合理使用原则"], "sections": [{"title": "课题1 生活中常见的盐", "body": "盐是一类由金属离子或铵根离子与酸根离子等构成的化合物，食盐中的氯化钠只是其中一种。碳酸钠俗称纯碱、苏打，虽然名字有“碱”却属于盐；碳酸氢钠俗称小苏打，碳酸钙是石灰石的重要成分。这些物质都不能只根据俗名判断类别或用途。碳酸盐与适当酸反应常产生二氧化碳，可结合石灰水检验；含碳酸氢根的物质也会出现类似现象。因此只凭酸后放气，未必能把碳酸钠和碳酸氢钠相互区分。"}, {"title": "课题1 反应规律：复分解与检验", "body": "两种化合物相互交换成分生成另外两种化合物的反应称为复分解反应。初中常见水溶液情境中，生成沉淀、气体或水是反应能发生的重要条件，不能只按交换符号就断定一定反应。判断时还要看反应物能否接触，例如盐与盐溶液间的反应通常要求相应反应物可溶；酸与难溶碳酸盐则可能发生反应。检验离子要考虑干扰，除杂要尽量不引入新杂质，并有后续分离办法。只背颜色和方程式，不能代替对实验目的和条件的分析。"}, {"title": "课题2 化学肥料", "body": "植物生长需要多种营养元素，常把能提供氮、磷、钾中的一种主要营养元素的化肥称为氮肥、磷肥或钾肥，能提供其中两种或三种的称为复合肥。硝酸钾同时含氮与钾，因此属于复合肥。评价肥料的有效养分时，需要从化学式计算元素质量分数，不能把化合物总质量当作养分质量。铵态氮肥不宜与碱性物质随意混用，以免放出氨而降低肥效。合理施肥应依据土壤和作物需要，过量使用可能造成水体污染和资源浪费。"}, {"title": "实验活动 粗盐中难溶性杂质的去除", "body": "含泥沙的粗盐可按溶解、过滤、蒸发的思路处理：溶解让盐进入水中，过滤除去难溶杂质，蒸发水分回收固体。各步骤作用不同，蒸发不是把盐分解。过滤前充分搅拌有助于盐溶解，但过量用水会增加后续蒸发负担；滤液浑浊应检查滤纸破损、液面过高等原因并重新过滤。此流程只能去除难溶性杂质，若粗盐还含可溶性钙、镁盐等，所得固体仍非化学纯氯化钠。回收率偏低应从转移损失、残留等具体环节分析。"}], "formulas": [{"text": "Na₂CO₃ + 2HCl → 2NaCl + H₂O + CO₂↑", "note": "碳酸钠与稀盐酸反应，不能以此单独区分所有碳酸盐。"}, {"text": "NaHCO₃ + HCl → NaCl + H₂O + CO₂↑", "note": "碳酸氢钠也能与稀盐酸放出CO₂。"}, {"text": "Na₂CO₃ + CaCl₂ → CaCO₃↓ + 2NaCl", "note": "两种盐溶液反应生成难溶碳酸钙。"}, {"text": "有效元素质量 = 化肥质量 × 纯度 × 该元素质量分数", "note": "若产品含多种提供相同元素的成分，应分别计算后相加。"}], "examples": [{"question": "求纯尿素CO(NH₂)₂中氮元素质量分数，并求60 kg尿素含氮多少千克。", "steps": ["相对质量12+16+2×14+4×1=60，氮的相对质量28。", "氮质量分数28÷60≈46.7%；60 kg尿素中氮为60×28÷60。"], "answer": "氮质量分数约46.7%，60 kg尿素含氮28 kg。"}, {"question": "某白色粉末遇稀盐酸放出气体，气体使石灰水变浑浊，是否能确定是Na₂CO₃？", "steps": ["可支持粉末含能与酸产生CO₂的成分。", "CaCO₃、NaHCO₃等也会给出类似证据。"], "answer": "不能唯一确定；需要进一步检测或已知成分范围。"}], "activity": {"title": "为粗盐提纯流程纠错", "materials": "粗盐提纯流程图、过滤装置图片、教师演示数据", "steps": ["给“溶解、过滤、蒸发”三个步骤分别写出目标。", "在图上找出滤纸高于漏斗口、液面高于滤纸等错误。", "阅读回收质量数据，区分盐损失与水未除尽造成的影响。", "解释为什么去掉泥沙仍不一定得到纯氯化钠。"], "recordHeaders": ["步骤", "分离依据", "常见误差", "改进方法"], "conclusion": "过滤分离难溶固体，蒸发回收溶质；可溶杂质会随溶液保留，需要额外方案。", "safety": "使用图卡或教师演示；涉及蒸发加热由教师组织，禁止品尝提纯后的盐，不自行加热铵盐或闻生成气体。"}, "mistakes": ["纯碱是碳酸钠，属于盐；熟石灰才属于碱。", "酸后放出CO₂不能单独证明样品必为碳酸钠。", "氮肥的总质量不等于氮元素质量，计算要看纯度和化学式。"], "quiz": [{"type": "choice", "question": "“纯碱”对应的化学式和类别是？", "options": ["NaOH，碱", "Na₂CO₃，盐", "Ca(OH)₂，盐", "NaCl，酸"], "answer": 1, "explanation": "俗名不能代替物质组成判断。"}, {"type": "choice", "question": "下面属于复合肥的是？", "options": ["KCl", "CO(NH₂)₂", "KNO₃", "NH₄Cl"], "answer": 2, "explanation": "KNO₃能同时提供氮、钾两种主要营养元素。"}, {"type": "choice", "question": "下列两种溶液混合通常产生沉淀的是？", "options": ["NaCl和KNO₃", "Na₂CO₃和CaCl₂", "NaCl和稀HCl", "KCl和NaNO₃"], "answer": 1, "explanation": "生成难溶的CaCO₃，其余常见情境没有对应反应驱动力。"}, {"type": "choice", "question": "粗盐提纯时过滤主要除去？", "options": ["所有可溶性盐", "氯化钠", "难溶性固体杂质", "全部水分"], "answer": 2, "explanation": "滤纸通常不能去除溶解在水中的离子。"}, {"type": "short", "question": "纯NH₄NO₃中氮元素的质量分数是多少？", "answer": "相对质量2×14+4×1+3×16=80；氮质量分数28÷80×100%=35%。", "explanation": "铵根与硝酸根都含氮，不能漏算其中一个。", "rubric": ["相对质量80且计入两个N", "氮质量分数35%"]}, {"type": "short", "question": "为什么不能用“把化学式交换一下”就断定两种盐溶液一定反应？", "answer": "还须判断生成物中是否有沉淀、气体等能使反应发生的产物，并满足相应溶解性和反应条件；例如NaCl与KNO₃溶液混合通常无此反应。", "explanation": "符号重排必须符合客观反应事实。", "rubric": ["说明要判断反应发生条件", "给出合适的无反应反例或条件解释"]}], "sim": "reaction", "tags": ["盐", "复分解", "化肥", "粗盐提纯", "养分计算"]}, {"id": "chemistry-12", "subject": "chemistry", "chapter": "第12单元", "title": "化学与生活", "term": "下册", "category": "同步", "intro": "一件衣服、一张食品标签背后包含哪些化学信息？如何区分材料性能与不可靠的推断？", "periods": "4–5课时（建议）", "goals": ["识别人类重要营养物质并区别供能与其他作用", "从元素和物质两个层次解释食品标签", "区分天然与合成高分子材料并比较使用和回收方案"], "sections": [{"title": "课题1 人类重要的营养物质", "body": "蛋白质、糖类、油脂、维生素、无机盐和水是常见的六类营养物质。蛋白质与生长、修复及多种生命活动有关，糖类是重要供能物质，油脂也可供能并储存能量；维生素、无机盐和水具有各自重要作用，但不能都简单当作能量来源。营养分类与化学组成分类不是同一个层次，例如许多糖类含碳、氢、氧元素。分析食品标签时要先核对每100 g、每份或每包的计量基础，再比较数值。本单元讨论化学知识，不据标签自行作诊断或制定补充剂用量。"}, {"title": "课题2 化学元素与人体健康", "body": "人体中的元素以多种物质形式存在，骨骼中的钙、含铁化合物中的铁等不能等同于金属钙或金属铁。常量元素与微量元素的分类主要根据含量，不表示微量元素不重要；元素的作用还与其化学形态和摄入量有关。含量过少或过多都可能影响正常生理过程，因此“含某元素越多越好”不是科学结论。阅读加碘盐、含钙食品等标签时，应区分元素质量与提供该元素的化合物质量，并结合产品标示条件理解，不把课堂计算当作医疗建议。"}, {"title": "课题3 有机合成材料", "body": "多数含碳化合物归为有机化合物，但一氧化碳、二氧化碳、碳酸及其盐等通常归入无机化合物，不能只凭有没有碳作机械判断。塑料、合成纤维和合成橡胶是常见有机合成材料；棉、羊毛和天然橡胶属于天然材料。不同高分子结构带来不同的耐热、弹性和加工性能，某些塑料受热软化，另一些不会简单熔融。评价材料时既看使用性能，也看生产、使用寿命、回收条件与废弃影响。减少不必要使用、重复使用和按类别回收，需要与当地实际处理能力相配合。"}], "formulas": [{"text": "C₆H₁₂O₆的相对分子质量 = 6×12 + 12×1 + 6×16 = 180", "note": "以葡萄糖化学式作组成计算；并非所有糖都具有这一化学式。"}, {"text": "整包某营养成分质量 = 标示每100 g含量 × 整包质量 ÷100 g", "note": "先核对标签是每100 g还是每份，单位必须一致。"}, {"text": "元素质量 = 化合物质量 × 对应元素质量分数", "note": "元素与单质不同，例如“含钙量”不是金属钙的质量。"}], "examples": [{"question": "某食品标签注明每100 g含蛋白质8 g，一包净含量250 g，整包含蛋白质多少克？", "steps": ["确认标签以100 g为基准。", "整包是100 g的2.5倍，蛋白质为8×2.5。"], "answer": "含蛋白质20 g。"}, {"question": "一件300 g的衣物面料标示棉60%、聚酯纤维40%，求两种纤维质量并分类。", "steps": ["棉质量300×60%=180 g，聚酯纤维质量300×40%=120 g。", "棉属于天然纤维，聚酯纤维属于合成纤维。"], "answer": "棉180 g；聚酯纤维120 g。"}], "activity": {"title": "制作材料与标签证据表", "materials": "干净食品包装、衣物成分标签、塑料制品标识照片", "steps": ["选两件衣物或两种包装，抄录原始标签并注明计量基准。", "根据成分区分天然材料、合成材料或复合使用。", "选择一个数值换算成整件或整包的含量。", "列出仅凭标签不能判断的性能，并设计需要补充的信息。"], "recordHeaders": ["物品", "标签证据", "分类或计算", "尚不能确定"], "conclusion": "标签可支持成分及用量判断，但耐热性、可回收性等还需要产品用途说明和当地回收条件。", "safety": "不焚烧塑料或纤维，不尝试未知化学鉴别，不把食品含量计算作为个人诊疗或补充剂方案。"}, "mistakes": ["“人体含铁”不等于人体里含有金属铁块，元素以化合物等形式存在。", "微量表示含量较少，不表示作用可忽略，也不表示越多越好。", "含碳不一定都归为有机物，CO₂和碳酸盐等是常见例外。"], "quiz": [{"type": "choice", "question": "下列属于天然纤维的是？", "options": ["聚酯纤维", "锦纶", "棉", "腈纶"], "answer": 2, "explanation": "棉来自植物，属于天然纤维；其他三项均为合成纤维。"}, {"type": "choice", "question": "下列通常归为无机化合物的是？", "options": ["葡萄糖", "乙醇", "二氧化碳", "甲烷"], "answer": 2, "explanation": "CO₂是含碳化合物分类中的常见例外。"}, {"type": "choice", "question": "标签中“含钙”通常描述的是？", "options": ["食品中一定有金属钙片", "钙元素的含量信息", "钙元素可以无限摄入", "所有钙化合物性质相同"], "answer": 1, "explanation": "元素含量不等于金属单质存在，也不说明各种化学形态性质相同。"}, {"type": "choice", "question": "某饮品每100 g含糖6 g，一瓶质量300 g，含糖多少克？", "options": ["6 g", "12 g", "18 g", "30 g"], "answer": 2, "explanation": "6×300÷100=18 g；本题按质量而非体积计算。"}, {"type": "short", "question": "葡萄糖C₆H₁₂O₆中碳元素质量分数是多少？18 g纯葡萄糖含碳多少克？", "answer": "碳质量分数72÷180=40%；18 g中含碳7.2 g。", "explanation": "碳原子个数是6，须乘相对原子质量12。", "rubric": ["质量分数40%", "碳质量7.2 g"]}, {"type": "short", "question": "“这种塑料耐用，所以使用后可以随意丢弃。”推理为什么不成立？", "answer": "使用阶段耐用只说明一种性能，不代表废弃后无环境影响；还应考虑减少不必要使用、重复使用、分类收集和实际回收处理条件。", "explanation": "材料评价需要考虑不同阶段，性能优点不能替代废弃管理证据。", "rubric": ["指出耐用不能推出可随意丢弃", "提出合理的全流程或回收考虑"]}], "sim": "materials", "tags": ["营养", "元素", "有机物", "合成材料", "标签阅读"]}]}, {"subject": "biology", "edition": "初中生物复习专题", "editionNote": "对应初中已学知识的九年级复习补充，不是人教版九年级生物分册。", "sources": [{"title": "义务教育课程标准目录", "url": "https://www.ictr.edu.cn/download_center/ywjy.html"}], "chapters": [{"id": "biology-01", "subject": "biology", "chapter": "专题 01", "title": "细胞、DNA与生命结构", "term": "复习", "category": "复习", "intro": "为什么一个细胞能保存并传递生命信息？", "periods": "1–2课时（建议）", "goals": ["解释“细胞的结构与功能”的核心概念", "用证据说明“DNA与细胞分裂”", "完成“纸片模拟遗传物质分配”并说清模型的限制"], "sections": [{"title": "细胞的结构与功能", "body": "细胞是生物体结构和功能的基本单位，病毒没有细胞结构。细胞膜控制物质进出；细胞质是许多生命活动进行的场所；细胞核中有重要遗传物质。常见植物细胞还具有细胞壁、液泡，叶片绿色部位细胞常有叶绿体，不能据“植物细胞”断言每个细胞都有叶绿体。"}, {"title": "DNA与细胞分裂", "body": "染色体主要由DNA和蛋白质组成，DNA上具有遗传效应的片段可称为基因。细胞分裂前遗传物质先复制，再分配到子细胞。在初中常见的体细胞分裂模型中，子细胞与原细胞的染色体数目相同；细胞生长主要增加体积，分裂主要增加数目。"}, {"title": "观察与模型", "body": "显微镜放大倍数等于目镜与物镜倍数的乘积；放大倍数增加，通常视野变小，可看到的细胞数变少。装片、染色与图示都可能改变观察结果，图中颜色并不总等于细胞天然颜色。模型用于表现结构关系，不代表真实大小比例。"}], "formulas": [{"text": "总放大倍数=目镜倍数×物镜倍数", "note": "两者倍数相乘"}, {"text": "1→2→4→8", "note": "理想同步分裂示意，不表示实际固定时间"}], "examples": [{"question": "10倍目镜配40倍物镜，总放大倍数是多少？", "steps": ["认清两个镜头倍数", "10×40=400"], "answer": "400倍"}, {"question": "一个体细胞连续分裂3次，共得到多少个细胞？", "steps": ["每次细胞数量加倍", "依次为2、4、8"], "answer": "8个，假设每轮所有细胞均完成分裂"}], "activity": {"title": "纸片模拟遗传物质分配", "materials": "双色纸条、纸环、记录纸", "steps": ["用纸条表示一套染色体", "复制每条纸条再将两套分开", "比较分裂前后每个细胞内的数量"], "recordHeaders": ["改变的条件", "观察或计算", "证据", "解释"], "conclusion": "分裂前先复制，使子细胞能获得与母细胞相同数目的染色体。", "safety": "纸条颜色、形状和大小均为示意。"}, "mistakes": ["病毒不是由细胞构成。", "植物根部许多细胞没有叶绿体。", "分裂前的复制不等于子细胞染色体数加倍。"], "quiz": [{"type": "choice", "question": "没有细胞结构的是哪一种？", "options": ["酵母菌", "细菌", "病毒", "洋葱"], "answer": 2, "explanation": "病毒无细胞结构，其余有细胞结构。"}, {"type": "choice", "question": "显微镜目镜5倍、物镜20倍，总倍数是多少？", "options": ["25倍", "100倍", "15倍", "400倍"], "answer": 1, "explanation": "5×20=100。"}, {"type": "choice", "question": "细胞分裂主要增加什么？", "options": ["细胞数目", "每个细胞体积", "每个细胞染色体数", "每个细胞液泡大小"], "answer": 0, "explanation": "分裂产生更多细胞；生长主要增大体积。"}, {"type": "choice", "question": "下列说法正确的是哪一个？", "options": ["每个植物细胞都有叶绿体", "DNA只存在于植物中", "染色体只由蛋白质构成", "基因与遗传信息有关"], "answer": 3, "explanation": "基因是具有遗传效应的DNA片段；其余表述过于绝对或错误。"}, {"type": "short", "question": "为何分裂前要复制遗传物质？", "answer": "为两个子细胞分别提供相应遗传物质。", "explanation": "仅将未复制的一套平均分开会导致每个子细胞获得的数量减少。", "rubric": ["为两个子细胞分别提供相应遗传物质。", "说明条件或推理过程"]}, {"type": "short", "question": "放大倍数增加后，视野中的细胞数通常如何变化？", "answer": "通常变少。", "explanation": "放大倍数增大使可观察范围变小。", "rubric": ["通常变少。", "说明条件或推理过程"]}], "sim": "cells", "tags": ["细胞", "DNA", "显微镜"]}, {"id": "biology-02", "subject": "biology", "chapter": "专题 02", "title": "光合作用与呼吸作用", "term": "复习", "category": "复习", "intro": "植物白天制造有机物，晚上就停止生命活动了吗？", "periods": "1–2课时（建议）", "goals": ["解释“光合作用”的核心概念", "用证据说明“呼吸作用”", "完成“设计叶片遮光对照”并说清模型的限制"], "sections": [{"title": "光合作用", "body": "绿色植物利用光能，在叶绿体中把二氧化碳和水转变成有机物，并释放氧气。它使无机物转变为有机物，把光能储存在有机物中。探究需要控制光照、二氧化碳等变量；实验前暗处理旨在消耗叶片原有淀粉，碘液用于检验淀粉。"}, {"title": "呼吸作用", "body": "细胞通过呼吸作用分解有机物、释放能量，供生命活动利用。初中常讨论有氧呼吸：有机物与氧反应生成二氧化碳和水并释放能量。植物的活细胞白天和夜晚一般都进行呼吸作用，种子萌发同样需要释放能量。"}, {"title": "气体变化与控制变量", "body": "植物在光下同时进行光合作用和呼吸作用，外界观测到的是二者共同造成的净变化。看到气泡不能仅凭外观判定其气体种类。研究光的作用应设置有光和遮光的对照，其他条件保持一致；实验结论应与实际控制条件相符。"}], "formulas": [{"text": "光合作用：CO₂+水 → 有机物+O₂", "note": "文字关系式，需光和叶绿体；不是已配平的化学方程式"}, {"text": "有氧呼吸：有机物+O₂ → CO₂+水+能量", "note": "能量不是一种物质"}], "examples": [{"question": "植物夜晚不能进行光合作用，是否仍会消耗有机物？", "steps": ["夜晚缺少光照，光合作用受限", "活细胞仍进行呼吸作用"], "answer": "会，呼吸作用仍消耗有机物并释放能量"}, {"question": "检验叶片遇光是否产生淀粉，为什么先暗处理？", "steps": ["叶片可能已含淀粉", "先消耗原有淀粉，减少干扰"], "answer": "使检验结果更能反映实验期间新形成的淀粉"}], "activity": {"title": "设计叶片遮光对照", "materials": "纸上叶片模型、黑纸、实验记录卡", "steps": ["提出光是否为必要条件", "在同一叶片设见光和遮光部分", "写出暗处理、脱色、碘液检验及预期对照"], "recordHeaders": ["改变的条件", "观察或计算", "证据", "解释"], "conclusion": "见光部分出现淀粉证据，需在其他条件可比时解释。", "safety": "酒精脱色涉及加热，只由教师按规范水浴演示；本活动可仅作方案设计。"}, "mistakes": ["植物白天也呼吸。", "光合作用与呼吸作用不是同一过程的机械反向播放。", "气泡本身不能证明气体一定是氧气。"], "quiz": [{"type": "choice", "question": "光合作用主要把什么能转化为化学能？", "options": ["声能", "光能", "电能", "核能"], "answer": 1, "explanation": "植物通过光合作用储存光能。"}, {"type": "choice", "question": "植物通常在什么时候进行呼吸作用？", "options": ["只在白天", "只在夜晚", "只在开花时", "白天和夜晚"], "answer": 3, "explanation": "活细胞生命活动需要持续获得能量。"}, {"type": "choice", "question": "检验淀粉常用什么试剂？", "options": ["碘液", "食盐水", "蒸馏水", "稀盐酸"], "answer": 0, "explanation": "淀粉遇碘液显蓝色，可作为实验依据。"}, {"type": "choice", "question": "探究光照作用时，最重要的设计是什么？", "options": ["一次改变所有条件", "只观察一片没有处理的叶子", "设见光和遮光对照", "只看叶片颜色"], "answer": 2, "explanation": "对照与控制变量帮助判断因果关系。"}, {"type": "short", "question": "光照下叶片同时进行哪两种相关作用？", "answer": "光合作用与呼吸作用。", "explanation": "看到的气体净变化取决于二者强弱。", "rubric": ["光合作用与呼吸作用。", "说明条件或推理过程"]}, {"type": "short", "question": "为什么不能把呼吸作用简单说成吸气和呼气？", "answer": "细胞呼吸是分解有机物并释放能量的过程。", "explanation": "人体吸气呼气是气体交换的环节，与细胞内反应不同。", "rubric": ["细胞呼吸是分解有机物并释放能量的过程。", "说明条件或推理过程"]}], "sim": "photosynthesis", "tags": ["叶绿体", "光合作用", "呼吸"]}, {"id": "biology-03", "subject": "biology", "chapter": "专题 03", "title": "遗传规律与变异", "term": "复习", "category": "复习", "intro": "父母相同的表现，会不会生出不同表现的后代？", "periods": "1–2课时（建议）", "goals": ["解释“基因与性状”的核心概念", "用证据说明“分离与概率”", "完成“用卡片模拟基因组合”并说清模型的限制"], "sections": [{"title": "基因与性状", "body": "性状是生物可观察的形态、生理等特征。基因通过影响相关物质的合成参与性状表达，但环境也会影响表现。成对基因中，A和a可表示一对显隐性等位基因；在单基因完全显性模型下，AA与Aa表现显性，aa表现隐性。"}, {"title": "分离与概率", "body": "生殖过程中，亲代成对基因通过生殖细胞传递，后代从双亲各获得一个。Aa与Aa组合可列出AA、Aa、aA、aa，基因型比例为1∶2∶1，显性与隐性表现概率为3∶1。这是每次组合的概率，不保证每四个后代恰有一个隐性。"}, {"title": "变异与适用范围", "body": "遗传物质变化造成的变异可能遗传；仅由环境改变且遗传物质未变造成的变化，通常不能按相同方式遗传。人的身高、肤色等涉及多个基因及环境，不能套用简单豌豆式单基因计算。禁止用性状判断人的价值或能力。"}], "formulas": [{"text": "Aa×Aa → AA、Aa、Aa、aa", "note": "仅用于单基因完全显性模型"}, {"text": "P(aa)=1/4", "note": "等可能配子、随机结合的简化模型"}], "examples": [{"question": "Aa与aa杂交，隐性后代概率是多少？", "steps": ["第一方可提供A或a", "第二方只提供a", "组合为Aa和aa"], "answer": "1/2"}, {"question": "AA与aa组合，子代基因型是什么？", "steps": ["双方分别只提供A和a", "每个子代组合为Aa"], "answer": "全部为Aa，表现显性（模型条件下）"}], "activity": {"title": "用卡片模拟基因组合", "materials": "A、a卡片各两套", "steps": ["两位同学各准备A、a卡", "每轮各随机取一张并放回", "记录20轮再与另一组数据合并"], "recordHeaders": ["改变的条件", "观察或计算", "证据", "解释"], "conclusion": "次数增加后频率有机会接近理论概率，小样本可明显偏离。", "safety": "仅为概率模型，不用于判断真实个人遗传风险。"}, "mistakes": ["显性不等于优良。", "每次事件的概率不等于少量后代的固定数量比例。", "真实复杂性状不可直接套用单基因模型。"], "quiz": [{"type": "choice", "question": "完全显性模型中，aa表现什么性状？", "options": ["隐性", "显性", "无法形成个体", "两种各一半"], "answer": 0, "explanation": "两个隐性等位基因组合表现隐性。"}, {"type": "choice", "question": "Aa×Aa得到AA的概率为多少？", "options": ["1", "1/2", "1/4", "3/4"], "answer": 2, "explanation": "四种等可能组合中AA占一种。"}, {"type": "choice", "question": "AA×aa的子代基因型是什么？", "options": ["AA", "Aa", "aa", "AA和aa"], "answer": 1, "explanation": "子代分别从双亲获得A和a。"}, {"type": "choice", "question": "以下说法正确的是？", "options": ["每四个后代必有一个aa", "性状完全不受环境影响", "所有性状都只受一个基因控制", "性状可能同时受遗传与环境影响"], "answer": 3, "explanation": "复杂性状需要考虑多种因素。"}, {"type": "short", "question": "为何连续出生三个显性后代不否定隐性概率为1/4？", "answer": "概率并不保证小样本中严格按比例出现。", "explanation": "不同组合是随机事件，次数少时偏差正常。", "rubric": ["概率并不保证小样本中严格按比例出现。", "说明条件或推理过程"]}, {"type": "short", "question": "Aa×aa中Aa和aa的理论比是多少？", "answer": "1∶1。", "explanation": "A、a两种配子分别与a结合得到Aa、aa。", "rubric": ["1∶1。", "说明条件或推理过程"]}], "sim": "genetics", "tags": ["基因", "遗传", "概率"]}, {"id": "biology-04", "subject": "biology", "chapter": "专题 04", "title": "生态系统与生物多样性", "term": "复习", "category": "复习", "intro": "一条食物链中的某种生物减少，会牵动哪些关系？", "periods": "1–2课时（建议）", "goals": ["解释“生态系统组成”的核心概念", "用证据说明“食物链与能量流动”", "完成“校园微生境观察”并说清模型的限制"], "sections": [{"title": "生态系统组成", "body": "生态系统由一定区域内的生物与非生物环境组成。生产者把无机物转化为有机物，消费者直接或间接利用其他生物获取有机物，分解者把有机物分解，促进物质循环。细菌与真菌中许多属于分解者，但并非所有细菌都只有分解作用。"}, {"title": "食物链与能量流动", "body": "食物链中的箭头从被捕食者指向捕食者，表示物质和能量的传递方向。初中常见食物链从生产者开始，不把阳光和分解者写进捕食食物链。能量流动通常单向且逐级递减；物质可以在系统中循环，能量并不循环利用。"}, {"title": "稳定与保护", "body": "生态系统有一定自我调节能力，但有界限。减少某一物种可能改变多个种群，不能仅凭一条线预测所有数量变化。保护生物多样性包括保护遗传多样性、物种多样性和生态系统多样性，保护栖息地具有重要意义。"}], "formulas": [{"text": "草 → 食草昆虫 → 青蛙 → 蛇", "note": "箭头指向摄食者"}, {"text": "能量逐级递减", "note": "本课不把固定传递效率作为普遍常数"}], "examples": [{"question": "草、兔、狐之间怎样画一条食物链？", "steps": ["从生产者草开始", "兔吃草，狐吃兔", "箭头由食物指向消费者"], "answer": "草→兔→狐"}, {"question": "一片森林仅列出树木、鸟类和昆虫，是否构成完整生态系统描述？", "steps": ["还要包含其他生物与非生物环境", "还需注意分解者等生态功能"], "answer": "描述不完整，还应考虑水、空气、土壤等环境与完整生物组成"}], "activity": {"title": "校园微生境观察", "materials": "记录本、放大镜（可选）", "steps": ["划定小范围观察区域", "记录生物与非生物因素", "用观察证据画关系图", "写出至少一种保护建议"], "recordHeaders": ["改变的条件", "观察或计算", "证据", "解释"], "conclusion": "生态系统研究要同时关注生物联系与环境条件。", "safety": "不捕捉、不采食未知生物，不破坏栖息地。"}, "mistakes": ["能量不能像物质一样在系统中反复循环。", "食物链箭头由被食者指向摄食者。", "自我调节能力不是无限的。"], "quiz": [{"type": "choice", "question": "捕食食物链通常从什么开始？", "options": ["分解者", "阳光", "生产者", "顶级捕食者"], "answer": 2, "explanation": "食物链的生物起点通常为生产者。"}, {"type": "choice", "question": "草→兔中的箭头主要表示什么？", "options": ["兔变成草", "物质和能量由草传向兔", "草追赶兔", "数量一定相等"], "answer": 1, "explanation": "箭头从被吃的生物指向摄食者。"}, {"type": "choice", "question": "哪项属于非生物因素？", "options": ["水分", "草", "鸟", "蘑菇"], "answer": 0, "explanation": "水分是环境因素，不是生物。"}, {"type": "choice", "question": "生态系统自我调节能力有什么特点？", "options": ["无限强", "完全不存在", "能消除一切污染", "有一定限度"], "answer": 3, "explanation": "扰动过大可超出其调节能力。"}, {"type": "short", "question": "分解者对生态系统有什么重要作用？", "answer": "分解有机物，促进物质循环。", "explanation": "让部分物质以无机形式回到环境，供生产者利用。", "rubric": ["分解有机物，促进物质循环。", "说明条件或推理过程"]}, {"type": "short", "question": "能量流动与物质循环有何区别？", "answer": "能量通常单向流动并逐级递减，物质可循环。", "explanation": "二者不能简单视为同一种循环过程。", "rubric": ["能量通常单向流动并逐级递减，物质可循环。", "说明条件或推理过程"]}], "sim": "ecosystem", "tags": ["生态系统", "食物链", "多样性"]}]}, {"subject": "astronomy", "edition": "九年级科学拓展", "editionNote": "跨学科拓展，不作为人教版九年级必修目录或中考考纲。", "sources": [{"title": "NASA：月相", "url": "https://science.nasa.gov/moon/moon-phases/"}, {"title": "NASA：日食与月食", "url": "https://science.nasa.gov/moon/eclipses/"}, {"title": "NASA：黑洞", "url": "https://science.nasa.gov/universe/black-holes/"}], "chapters": [{"id": "astronomy-01", "subject": "astronomy", "chapter": "专题 01", "title": "太阳系与轨道运动", "term": "拓展", "category": "拓展", "intro": "为什么行星绕太阳运行，却不会在一圈以后停下来？", "periods": "1–2课时（建议）", "goals": ["解释“层次与分类”的核心概念", "用证据说明“轨道与引力”", "完成“给太阳系图写比例说明”并说清模型的限制"], "sections": [{"title": "层次与分类", "body": "太阳是恒星，地球是绕太阳运行的行星，月球是地球的天然卫星。太阳系包含八颗行星以及卫星、小行星、彗星等。恒星能通过内部过程持续释放能量，行星和卫星的可见光主要来自反射。太阳系只是银河系的一部分。"}, {"title": "轨道与引力", "body": "引力改变天体运动方向，维持轨道运动。理想二体模型中，行星轨道可近似看作椭圆，太阳位于一个焦点；椭圆可以很接近圆。行星到太阳的距离和公转时间有关系，实际多体系统还会受到其他天体影响。"}, {"title": "比例尺意识", "body": "太阳系图常把天体画得过大、距离画得过小，目的是便于辨认。太阳系的天体大小与彼此距离无法在普通屏幕上同时清晰按真实比例展示。使用模型时应分别说明大小比例、距离比例和动画时间比例。"}], "formulas": [{"text": "恒星 → 行星 → 卫星", "note": "关系示意，箭头不是物体演化顺序"}], "examples": [{"question": "把地球标为行星、月球标为恒星，哪里有误？", "steps": ["判断绕谁运行", "月球围绕地球运行，主要反射太阳光"], "answer": "月球应标为天然卫星"}, {"question": "模型把1 AU表示为1 m，约5 AU的距离应画多长？", "steps": ["采用同一线性比例尺", "5×1 m"], "answer": "约5 m；AU是地日平均距离的尺度单位"}], "activity": {"title": "给太阳系图写比例说明", "materials": "白纸、尺、轨道示意图", "steps": ["选定距离比例尺", "计算几个相对轨道半径", "比较按同一比例画天体大小是否清楚"], "recordHeaders": ["改变的条件", "观察或计算", "证据", "解释"], "conclusion": "科学示意图的大小、距离和时间常采用不同缩放。", "safety": "不把模型速度或大小当成真实数值。"}, "mistakes": ["太阳系不是整个宇宙。", "月球主要反射太阳光。", "图示轨道速度与大小并非真实比例。"], "quiz": [{"type": "choice", "question": "太阳属于哪一类天体？", "options": ["恒星", "行星", "卫星", "彗星"], "answer": 0, "explanation": "太阳是太阳系的恒星。"}, {"type": "choice", "question": "月球主要围绕什么公转？", "options": ["火星", "地球", "木星", "北极星"], "answer": 1, "explanation": "月球是地球的天然卫星。"}, {"type": "choice", "question": "太阳系中目前通常认定有几颗行星？", "options": ["7", "9", "8", "10"], "answer": 2, "explanation": "通常采用八行星分类。"}, {"type": "choice", "question": "关于教材太阳系示意图，正确的是？", "options": ["天体大小全部是真实比例", "距离全部是真实比例", "时间尺度一定真实", "可能使用不同缩放比例"], "answer": 3, "explanation": "示意图优先表达关系，需要查看比例说明。"}, {"type": "short", "question": "引力对轨道运动起什么作用？", "answer": "改变运动方向，使天体维持绕行。", "explanation": "不能把轨道运动解释成物体完全不受力。", "rubric": ["改变运动方向，使天体维持绕行。", "说明条件或推理过程"]}, {"type": "short", "question": "为何不能根据示意图直接比较地球与太阳的实际距离比例？", "answer": "示意图可能没有按真实距离比例绘制。", "explanation": "应先查比例尺或明确数值。", "rubric": ["示意图可能没有按真实距离比例绘制。", "说明条件或推理过程"]}], "sim": "orbit", "tags": ["太阳系", "行星", "轨道"]}, {"id": "astronomy-02", "subject": "astronomy", "chapter": "专题 02", "title": "月相与日月食", "term": "拓展", "category": "拓展", "intro": "每个月都有新月和满月，为什么并非每月都有日食与月食？", "periods": "1–2课时（建议）", "goals": ["解释“月相的形成”的核心概念", "用证据说明“日食与月食”", "完成“灯与球模拟月相”并说清模型的限制"], "sections": [{"title": "月相的形成", "body": "月球本身不发可见光，太阳照亮它的一半。随着月球绕地球运动，地球上的观察者看到被照亮部分的比例变化，形成月相。新月与满月大致对应月球在地球和太阳之间、地球在太阳和月球之间的方向关系；普通月相并非地球影子造成。"}, {"title": "日食与月食", "body": "日食发生时，月球位于太阳和地球之间，其影子可能落到地球上；月食发生时，地球在太阳和月球之间，月球进入地球影区。形成食还需要近乎共线及轨道位置等几何条件，仅有新月或满月并不充分。"}, {"title": "轨道倾角与观察", "body": "月球轨道相对地球公转轨道平面有倾角，多数新月和满月时三者不精确对齐。模型若把所有轨道压到同一平面，会错误暗示每月都有食。太阳观测必须使用专门合规设备与指导，普通墨镜不能替代太阳观测滤镜。"}], "formulas": [{"text": "日食排列：太阳—月球—地球", "note": "还需接近共线等几何条件"}, {"text": "月食排列：太阳—地球—月球", "note": "月球进入地球影区"}], "examples": [{"question": "新月时是否一定有日食？", "steps": ["新月给出大致方向关系", "轨道倾角可能使影子错开地球"], "answer": "不一定，还须满足对齐条件"}, {"question": "看到半月能否断言地球挡住了半个月球？", "steps": ["月相取决于看到的受光部分", "地球影子只与月食有关"], "answer": "不能，普通月相不是地球影子造成的"}], "activity": {"title": "灯与球模拟月相", "materials": "台灯、小球、固定观察点", "steps": ["用台灯代表太阳", "小球绕观察点移动", "记录不同位置看到的亮面", "倾斜小球运行平面，观察对齐条件"], "recordHeaders": ["改变的条件", "观察或计算", "证据", "解释"], "conclusion": "月相与受光视角有关，食还要求恰当对齐。", "safety": "用台灯即可，不直视太阳；尺寸与轨道不按真实比例。"}, "mistakes": ["月相并非地球影子造成。", "新月不一定发生日食。", "普通墨镜不能用于直接观测太阳。"], "quiz": [{"type": "choice", "question": "普通月相主要由什么造成？", "options": ["月球自身发光变化", "看到的受光部分变化", "每天发生月食", "月球大小变化"], "answer": 1, "explanation": "月球受光面与观察角度的相对关系发生变化。"}, {"type": "choice", "question": "日食时中间的天体是哪一个？", "options": ["月球", "地球", "太阳", "火星"], "answer": 0, "explanation": "月球处于太阳和地球之间。"}, {"type": "choice", "question": "月食时中间的天体是哪一个？", "options": ["月球", "金星", "地球", "木星"], "answer": 2, "explanation": "地球的影子遮住月球。"}, {"type": "choice", "question": "为什么不每月发生月食？", "options": ["月球每月消失", "地球不产生影子", "太阳每月熄灭", "轨道倾角使多数满月不精确对齐"], "answer": 3, "explanation": "轨道倾斜使月球常从影区上方或下方经过。"}, {"type": "short", "question": "日食与月食的排列分别是什么？", "answer": "日食：日—月—地；月食：日—地—月。", "explanation": "排列只是必要方向关系，还要满足近乎共线等条件。", "rubric": ["日食：日—月—地；月食：日—地—月。", "说明条件或推理过程"]}, {"type": "short", "question": "月相模型应说明哪一项局限？", "answer": "天体尺寸、距离和轨道倾角通常被简化。", "explanation": "同平面模型不能准确表示日月食出现频率。", "rubric": ["天体尺寸、距离和轨道倾角通常被简化。", "说明条件或推理过程"]}], "sim": "eclipse", "tags": ["月相", "日食", "月食"]}, {"id": "astronomy-03", "subject": "astronomy", "chapter": "专题 03", "title": "昼夜、四季与地轴倾斜", "term": "拓展", "category": "拓展", "intro": "如果夏天只是因为靠太阳更近，为什么南北半球季节相反？", "periods": "1–2课时（建议）", "goals": ["解释“昼夜交替”的核心概念", "用证据说明“四季的主要原因”", "完成“手电照射角度比较”并说清模型的限制"], "sections": [{"title": "昼夜交替", "body": "地球近似球体，同一时刻通常只有一半表面被太阳直接照亮。地球自转使各地点交替进入向阳面和背阳面，造成昼夜交替。公转与自转是不同运动：自转是绕地轴转动，公转是绕太阳运行。"}, {"title": "四季的主要原因", "body": "地轴相对公转轨道平面的倾斜，使一年中太阳直射位置和各地白昼长度发生变化。某半球更朝向太阳时，通常太阳高度较大、白昼较长，单位面积接收的太阳能更多，容易形成夏季。南北半球季节相反，不能仅用地日距离解释四季。"}, {"title": "模型与当地气候", "body": "纬度、海陆位置、地形和大气环流等也影响实际气温。示意中的季节与平均受光情况相关，不能用一次气温测量证明四季机制。讨论极昼极夜需要考虑纬度及季节，本专题只进行定性探索。"}], "formulas": [{"text": "自转 → 昼夜交替", "note": "需考虑球形地球受光"}, {"text": "地轴倾斜 + 公转 → 四季变化", "note": "地轴方向在一年尺度内可近似保持不变"}], "examples": [{"question": "北半球夏季时，南半球大致是什么季节？", "steps": ["地轴倾斜使南北半球受光趋势相反", "北半球朝向太阳更多"], "answer": "南半球大致为冬季"}, {"question": "将地球模型不倾斜地绕灯移动，能否很好解释真实四季？", "steps": ["该模型忽略主要条件地轴倾斜", "不能得到正确的季节受光差异"], "answer": "不能，需要加入地轴倾斜"}], "activity": {"title": "手电照射角度比较", "materials": "手电、白纸、球体", "steps": ["固定距离照射白纸", "比较直照和斜照光斑面积", "在球面不同位置重复", "说明同样光能分布到不同面积的区别"], "recordHeaders": ["改变的条件", "观察或计算", "证据", "解释"], "conclusion": "光线越斜，光能通常分布在更大面积上。", "safety": "不将强光照向眼睛，模型不能代替真实气象数据。"}, "mistakes": ["四季不能只用地日距离解释。", "太阳高度变化不等于太阳大小变化。", "一次天气观测不是季节机制的充分证据。"], "quiz": [{"type": "choice", "question": "昼夜交替主要与什么有关？", "options": ["月球自转", "地球自转", "地球形变", "云量变化"], "answer": 1, "explanation": "地球自转使各地交替进入明暗两侧。"}, {"type": "choice", "question": "解释四季的重要条件是？", "options": ["地轴倾斜", "太阳每年熄灭", "地球每天变大", "月球反光消失"], "answer": 0, "explanation": "倾斜地轴随地球公转改变季节受光情况。"}, {"type": "choice", "question": "南北半球季节通常怎样？", "options": ["始终相同", "都只有冬季", "大致相反", "随机互换"], "answer": 2, "explanation": "地轴倾斜导致两半球季节受光趋势相反。"}, {"type": "choice", "question": "下列哪项不能单独解释地球四季？", "options": ["太阳高度变化", "昼长变化", "地轴倾斜", "地日距离变化"], "answer": 3, "explanation": "距离变化不能解释南北半球季节相反。"}, {"type": "short", "question": "自转与公转如何区分？", "answer": "自转绕自身地轴；公转绕太阳。", "explanation": "研究对象及所绕轴或中心不同。", "rubric": ["自转绕自身地轴；公转绕太阳。", "说明条件或推理过程"]}, {"type": "short", "question": "为何斜照时单位面积接收能量通常较少？", "answer": "同样的光能分布在更大的面积上。", "explanation": "比较应保持光源强度和距离等条件可比。", "rubric": ["同样的光能分布在更大的面积上。", "说明条件或推理过程"]}], "sim": "seasons", "tags": ["四季", "自转", "地轴"]}, {"id": "astronomy-04", "subject": "astronomy", "chapter": "专题 04", "title": "恒星、黑洞与宇宙尺度", "term": "拓展", "category": "拓展", "intro": "看不见黑洞内部，科学家如何研究它？", "periods": "1–2课时（建议）", "goals": ["解释“恒星与星系”的核心概念", "用证据说明“黑洞与观测证据”", "完成“伸缩点阵与模型边界”并说清模型的限制"], "sections": [{"title": "恒星与星系", "body": "恒星是持续释放能量的天体，银河系包含大量恒星、气体与尘埃等。光年是光在真空中一年传播的距离，属于长度单位，不是时间单位。望远镜看到远方天体的光，就在接收它过去发出的信息。"}, {"title": "黑洞与观测证据", "body": "黑洞具有事件视界；越过视界后，连光也无法逃离。它不是无条件吸走整个宇宙的吸尘器。研究者通过附近恒星和气体的运动、吸积物质辐射、引力波等证据研究黑洞。图像中的亮环通常来自周围高温物质，不是黑洞内部发出的光。"}, {"title": "宇宙膨胀", "body": "在足够大的尺度上，星系间空间整体呈膨胀趋势，可用气球表面点间距离增大作类比。这个模型不是说宇宙一定有气球那样的外部空间或表面中心；引力束缚系统也不会简单随膨胀等比例变大。本专题为定性科学阅读。"}], "formulas": [{"text": "1光年：光在真空中一年传播的距离", "note": "长度单位"}, {"text": "证据 → 模型 → 新观测检验", "note": "模型必须受证据约束"}], "examples": [{"question": "“这颗星距我们10光年，因此光走了约10年”是否合理？", "steps": ["光年表示距离", "按光在真空中的速度传播计算"], "answer": "可作为简化理解，实际天文距离解释还需模型条件"}, {"question": "黑洞周围有亮环，是否说明光从事件视界内部逃出？", "steps": ["区分内部与外部", "周围吸积物质可发光"], "answer": "不是，亮环主要反映周围物质与引力效应"}], "activity": {"title": "伸缩点阵与模型边界", "materials": "弹性带或纸上比例图、尺", "steps": ["画出三个相隔的点", "均匀拉伸或放大间距", "比较不同点间距离变化", "写出该模型不能表达的现象"], "recordHeaders": ["改变的条件", "观察或计算", "证据", "解释"], "conclusion": "比例放大可帮助理解距离变化，但不能当作宇宙真实形状。", "safety": "拉伸时避免弹回；不把二维模型解释成宇宙全部结构。"}, "mistakes": ["光年不是时间单位。", "黑洞不是无限距离的吸尘器。", "气球类比不证明宇宙有外壁。"], "quiz": [{"type": "choice", "question": "光年是什么单位？", "options": ["时间", "质量", "长度", "温度"], "answer": 2, "explanation": "光年定义为光一年传播的距离。"}, {"type": "choice", "question": "黑洞事件视界内部的光能否逃出？", "options": ["不能", "一定可以", "只在白天可以", "只要光够亮就可以"], "answer": 0, "explanation": "事件视界是无法向外传出光信号的边界。"}, {"type": "choice", "question": "银河系与太阳系的关系是什么？", "options": ["完全相同", "太阳系是银河系的一部分", "银河系在地球内部", "互不相关"], "answer": 1, "explanation": "太阳系位于银河系中。"}, {"type": "choice", "question": "气球模型的正确用法是什么？", "options": ["证明宇宙有外壁", "证明地球在宇宙中心", "证明所有原子都会膨胀", "帮助理解距离变化并说明局限"], "answer": 3, "explanation": "类比能说明部分关系，不能推广全部性质。"}, {"type": "short", "question": "列举一种研究黑洞的间接证据。", "answer": "周围恒星运动、吸积辐射或引力波。", "explanation": "从可观测效应约束不可直接看见的对象。", "rubric": ["周围恒星运动、吸积辐射或引力波。", "说明条件或推理过程"]}, {"type": "short", "question": "为什么看遥远天体相当于接收过去的信息？", "answer": "光传播需要时间。", "explanation": "接收到的光在更早时刻已从天体发出。", "rubric": ["光传播需要时间。", "说明条件或推理过程"]}], "sim": "universe", "tags": ["黑洞", "光年", "宇宙"]}]}, {"subject": "coding", "edition": "九年级信息科技与编程拓展", "editionNote": "使用伪代码和纸上算法，不绑定某一版信息科技教材，也不要求安装开发工具。", "sources": [], "chapters": [{"id": "coding-01", "subject": "coding", "chapter": "专题 01", "title": "算法与流程控制", "term": "拓展", "category": "拓展", "intro": "怎样把“我知道怎么做”写成别人也能执行的步骤？", "periods": "1–2课时（建议）", "goals": ["解释“算法的表达”的核心概念", "用证据说明“顺序、分支与循环”", "完成“手工运行伪代码”并说清模型的限制"], "sections": [{"title": "算法的表达", "body": "算法是解决特定问题的一组明确步骤。输入、输出、步骤顺序、终止条件要说清楚，可以用自然语言、流程图或伪代码表达。好算法不仅产生预期结果，还应能处理边界情况；“一直做直到成功”若没有可判断条件就不够明确。"}, {"title": "顺序、分支与循环", "body": "顺序结构依次执行步骤；分支依据条件选择路径；循环重复执行一段过程。求1到n的和时，需要设置初始和为0、计数器从1开始、累加后更新计数器，并明确停止位置。少更新计数器可能导致无限循环。"}, {"title": "测试与调试", "body": "测试要包括普通输入、最小输入与特殊输入。检查结果不符时，记录每一步变量值，找出首次偏离预期的位置。调试是定位和修正错误，不是不断更改答案直到看起来正确。本课使用伪代码，不要求安装编程软件。"}], "formulas": [{"text": "S=1+2+…+n=n(n+1)/2", "note": "正整数n，可与循环结果互检"}], "examples": [{"question": "用循环求1到4之和，累加器依次是多少？", "steps": ["初值S=0", "加入1、2、3、4后为1、3、6、10"], "answer": "10"}, {"question": "为什么循环变量一直等于1会出问题？", "steps": ["若条件为i≤n，且n≥1", "不更新i会使条件一直满足"], "answer": "循环可能无法终止"}], "activity": {"title": "手工运行伪代码", "materials": "变量记录表、笔", "steps": ["设S=0，i=1", "当i≤5时计算S=S+i", "再令i=i+1并重复", "记录每一步i和S"], "recordHeaders": ["改变的条件", "观察或计算", "证据", "解释"], "conclusion": "运行轨迹帮助检验更新顺序与停止条件。", "safety": "仅处理示例数字，不使用个人敏感数据。"}, "mistakes": ["循环不等于无条件无限重复。", "算法可以先用纸笔表达。", "一次正确结果不能证明所有输入都正确。"], "quiz": [{"type": "choice", "question": "选择不同路径通常使用什么结构？", "options": ["顺序", "分支", "循环", "注释"], "answer": 1, "explanation": "分支根据条件决定执行路径。"}, {"type": "choice", "question": "累加求和的初始S通常设为多少？", "options": ["0", "1", "n", "未知"], "answer": 0, "explanation": "0是加法的起始累加值。"}, {"type": "choice", "question": "下列哪项有助于循环结束？", "options": ["删除所有条件", "不更新变量", "设置可达到的终止条件", "隐藏错误"], "answer": 2, "explanation": "循环需有可达到的终止条件和正确更新。"}, {"type": "choice", "question": "较合理的测试方法是？", "options": ["只试一次", "只试最大值", "不看中间步骤", "包含普通与边界输入"], "answer": 3, "explanation": "边界输入常能暴露遗漏。"}, {"type": "short", "question": "求1到5之和是多少？", "answer": "15。", "explanation": "1+2+3+4+5=15，可用5×6÷2验证。", "rubric": ["15。", "说明条件或推理过程"]}, {"type": "short", "question": "变量追踪表有什么作用？", "answer": "记录每一步状态，定位首次错误。", "explanation": "能区分初始化、条件、更新等不同错误来源。", "rubric": ["记录每一步状态，定位首次错误。", "说明条件或推理过程"]}], "sim": "algorithm", "tags": ["流程图", "循环", "调试"]}, {"id": "coding-02", "subject": "coding", "chapter": "专题 02", "title": "数组、查找与数据组织", "term": "拓展", "category": "拓展", "intro": "成绩存在列表里，怎样准确找到需要的一项？", "periods": "1–2课时（建议）", "goals": ["解释“列表与索引”的核心概念", "用证据说明“顺序查找”", "完成“比较两种查找”并说清模型的限制"], "sections": [{"title": "列表与索引", "body": "列表按顺序保存多个数据，索引用于定位元素。不同语言可能从0或1计数，本课模型从0开始：三个元素的索引是0、1、2。索引表示位置，不是元素本身的数值。访问不存在的位置应判为越界，不能直接当成0。"}, {"title": "顺序查找", "body": "顺序查找从一端依次比较目标与元素，找到后可以停止；全部比较仍未找到，应明确返回“未找到”。对于长度n的无序列表，最坏需要比较n次。若存在重复值，应事先说明要返回第一个位置、全部位置还是出现次数。"}, {"title": "有序数据与二分思想", "body": "有序列表可以用二分思想：先看中间元素，再缩小到可能包含目标的一半区间。二分查找的前提是数据已按确定顺序排列。数据的存储方式应服务于问题，不能只根据列表长度判断哪种方法总是最快。"}], "formulas": [{"text": "索引范围：0到n−1", "note": "本课约定从0开始"}, {"text": "顺序查找最坏比较n次", "note": "逐项查找长度n的列表"}], "examples": [{"question": "列表[7,2,9]中索引1对应什么？", "steps": ["本课从0开始计数", "索引0是7，索引1是2"], "answer": "2"}, {"question": "在[4,8,3,6]中顺序查找3，需要比较几次？", "steps": ["比较4，不相等", "比较8，不相等", "比较3，找到"], "answer": "3次"}], "activity": {"title": "比较两种查找", "materials": "有序和无序数字卡片", "steps": ["打乱8张数字卡做顺序查找", "记录比较次数", "排序后尝试二分缩小区间", "比较方法所需前提"], "recordHeaders": ["改变的条件", "观察或计算", "证据", "解释"], "conclusion": "查找策略依赖数据是否有序及任务要求。", "safety": "使用虚构数据，不公开真实成绩或个人名单。"}, "mistakes": ["索引与数值不同。", "二分查找需要有序前提。", "找不到时必须有明确结果。"], "quiz": [{"type": "choice", "question": "长度5列表从0计数，最大合法索引是多少？", "options": ["5", "6", "4", "1"], "answer": 2, "explanation": "合法索引为0、1、2、3、4。"}, {"type": "choice", "question": "二分查找通常要求数据怎样？", "options": ["有序", "全部相同", "必须字符串", "必须恰好10项"], "answer": 0, "explanation": "需要利用顺序关系排除一半区间。"}, {"type": "choice", "question": "目标不存在时，程序应该怎样？", "options": ["随便返回一项", "明确报告未找到", "永远循环", "自动创造目标"], "answer": 1, "explanation": "输出约定应包括未找到情况。"}, {"type": "choice", "question": "有重复值时，应先明确什么？", "options": ["电脑颜色", "变量字体", "屏幕大小", "要找第一个还是全部位置"], "answer": 3, "explanation": "查找任务定义影响返回结果。"}, {"type": "short", "question": "在[1,5,7,9]中顺序查找9需比较几次？", "answer": "4次。", "explanation": "逐项比较至最后一个元素。", "rubric": ["4次。", "说明条件或推理过程"]}, {"type": "short", "question": "为何无序列表不能直接套用普通二分查找？", "answer": "中间元素大小不能确定目标在哪一半。", "explanation": "丢弃一半时可能把目标错误排除。", "rubric": ["中间元素大小不能确定目标在哪一半。", "说明条件或推理过程"]}], "sim": "search", "tags": ["列表", "索引", "查找"]}, {"id": "coding-03", "subject": "coding", "chapter": "专题 03", "title": "排序与复杂度直觉", "term": "拓展", "category": "拓展", "intro": "同样把数字排好，为什么有的方法比较次数更多？", "periods": "1–2课时（建议）", "goals": ["解释“排序与保持数据”的核心概念", "用证据说明“冒泡排序”", "完成“数字卡片冒泡排序”并说清模型的限制"], "sections": [{"title": "排序与保持数据", "body": "排序改变元素顺序，使其满足升序或降序要求；不能删除重复项或随意修改数值。判断排序正确，需要同时检查顺序条件和元素是否完整保留。列表已排好、完全逆序、含重复值都是重要测试情况。"}, {"title": "冒泡排序", "body": "冒泡排序反复比较相邻元素，若顺序不对就交换。升序排序的一轮从左向右比较可把较大的元素逐步移向右端。每轮可以缩短尚未确定的范围；若某一完整轮没有交换，可以提前结束。"}, {"title": "增长趋势与条件", "body": "最坏情况下，基础冒泡排序比较次数为n(n−1)/2，随规模近似平方增长。复杂度讨论关注输入规模增大时工作量的变化，而非某台设备的一次计时。比较次数、交换次数和真实耗时不同，不能相互混用。"}], "formulas": [{"text": "最坏比较次数=n(n−1)/2", "note": "本课标准逐轮缩短范围的冒泡排序"}, {"text": "n翻倍，平方型工作量约变为4倍", "note": "渐近直觉，不是每次计时严格4倍"}], "examples": [{"question": "对[3,1,2]做从左到右的一轮升序冒泡，结果是什么？", "steps": ["3与1交换成[1,3,2]", "3与2交换成[1,2,3]"], "answer": "[1,2,3]"}, {"question": "5个元素基础冒泡排序最坏比较几次？", "steps": ["各轮比较4、3、2、1次", "相加为10"], "answer": "10次"}], "activity": {"title": "数字卡片冒泡排序", "materials": "5张数字卡、记录表", "steps": ["打乱数字卡", "每次只比较相邻两张", "需要时交换并记录次数", "每轮结束标出已确定位置"], "recordHeaders": ["改变的条件", "观察或计算", "证据", "解释"], "conclusion": "局部比较与交换重复执行，可以完成全局排序。", "safety": "动画每步用于理解算法，不代表计算机真实运行速度。"}, "mistakes": ["排序不能丢失重复元素。", "比较次数不同于交换次数。", "动画速度不等于算法真实运行速度。"], "quiz": [{"type": "choice", "question": "升序冒泡时何时交换相邻元素？", "options": ["左边小于右边", "左边大于右边", "两者始终相等", "每次都必须交换"], "answer": 1, "explanation": "相邻顺序相反时交换。"}, {"type": "choice", "question": "排序应该保持什么不变？", "options": ["元素及其出现次数", "原位置", "比较次数", "列表必须无重复"], "answer": 0, "explanation": "排序只调整顺序，不增删或改变原始元素。"}, {"type": "choice", "question": "4个元素最坏比较次数为多少？", "options": ["4", "8", "6", "16"], "answer": 2, "explanation": "3+2+1=6。"}, {"type": "choice", "question": "复杂度主要研究什么？", "options": ["程序颜色", "屏幕帧率", "文件名称", "工作量随输入规模如何增长"], "answer": 3, "explanation": "复杂度关注规模与资源需求的关系。"}, {"type": "short", "question": "[2,1,3]做一轮升序冒泡，结果是什么？", "answer": "[1,2,3]。", "explanation": "先交换2与1，再比较2与3无需交换。", "rubric": ["[1,2,3]。", "说明条件或推理过程"]}, {"type": "short", "question": "为什么一次计时不能直接证明算法更优？", "answer": "计时受设备、输入、系统状态等影响。", "explanation": "应比较适用条件、规模和多种输入，并区分理论工作量与实际耗时。", "rubric": ["计时受设备、输入、系统状态等影响。", "说明条件或推理过程"]}], "sim": "sort", "tags": ["排序", "冒泡", "复杂度"]}, {"id": "coding-04", "subject": "coding", "chapter": "专题 04", "title": "模块化与小项目设计", "term": "拓展", "category": "拓展", "intro": "怎样让一个练习程序既能出题，也能可靠地判分？", "periods": "1–2课时（建议）", "goals": ["解释“输入、处理与输出”的核心概念", "用证据说明“拆分与复用”", "完成“纸上设计练习器”并说清模型的限制"], "sections": [{"title": "输入、处理与输出", "body": "先把需求写清楚：输入是什么、处理规则是什么、输出需要说明什么。制作加法练习器时，题目、答案、用户输入、评分结果是不同的数据。空输入不能当成数字0；异常输入应提示修改，而不是直接显示正确。"}, {"title": "拆分与复用", "body": "把生成题目、读取答案、判定结果、显示解析拆成不同模块，每个模块承担清晰任务。这样能分别测试并复用，避免修改显示文字时改变评分规则。复杂设计模式不是本阶段的记忆重点，先练习合理分工与简单接口。"}, {"title": "数据与责任", "body": "练习记录应尽量保存在本机，只收集完成任务必需的数据。分享作品前，移除真实姓名、联系方式与个人成绩。程序应说明自动评分能判断什么；开放性解释题不应仅凭关键词匹配就宣称给出可靠成绩。"}], "formulas": [{"text": "输入 → 校验 → 处理 → 输出", "note": "校验缺失会影响后续判断"}], "examples": [{"question": "加法题答案是0，输入框为空，能否判正确？", "steps": ["空输入并不表示数字0", "应先检查是否填写", "再转换为数字比较"], "answer": "不能，应先要求填写答案"}, {"question": "把“出题”和“判分”写成两个模块有什么好处？", "steps": ["可以独立测试每个模块", "不同题型可复用显示与记录逻辑"], "answer": "便于维护、测试与复用"}], "activity": {"title": "纸上设计练习器", "materials": "流程卡、界面草图", "steps": ["画出题目和作答区域", "定义正常、空白、非数字三类输入", "分别写出处理路径", "与同伴按流程试运行"], "recordHeaders": ["改变的条件", "观察或计算", "证据", "解释"], "conclusion": "先处理输入合法性，再比较答案并解释结果。", "safety": "不收集无关个人信息；开放题采用明确参考答案和自评。"}, "mistakes": ["空字符串不等于用户确实输入0。", "模块越多不一定设计越好。", "开放题不能凭简单关键词匹配宣称可靠自动评分。"], "quiz": [{"type": "choice", "question": "作答框为空时，应先怎样？", "options": ["当作0", "当作满分", "提示填写", "删除题目"], "answer": 2, "explanation": "应校验输入，而非隐式当成某个数值。"}, {"type": "choice", "question": "模块化的主要目的是什么？", "options": ["拆分清晰职责以便测试复用", "尽量增加代码行数", "隐藏错误", "禁止修改"], "answer": 0, "explanation": "合理拆分降低耦合并方便独立检验。"}, {"type": "choice", "question": "分享学习项目时更合适的做法是？", "options": ["公开真实成绩名单", "移除不必要个人信息", "上传全部浏览记录", "要求家庭住址"], "answer": 1, "explanation": "遵守数据最小化原则。"}, {"type": "choice", "question": "开放题自动评分应如何说明？", "options": ["宣称永不出错", "只匹配一个词就给满分", "无需解释标准", "明确能力边界和评价标准"], "answer": 3, "explanation": "开放题判断复杂，应如实说明评价依据。"}, {"type": "short", "question": "为练习器列出两种边界输入。", "answer": "空输入、非数字输入等。", "explanation": "也可考虑负数、很大的数或带单位的字符串，并说明规则。", "rubric": ["空输入、非数字输入等。", "说明条件或推理过程"]}, {"type": "short", "question": "把项目拆成至少三个模块。", "answer": "出题、输入校验、判分、解析显示。", "explanation": "各模块输入输出清楚，并能分别测试。", "rubric": ["出题、输入校验、判分、解析显示。", "说明条件或推理过程"]}], "sim": "workflow", "tags": ["模块化", "项目", "数据"]}]}];
